def default_lease_end(lease_start_date):
    """
    Default lease term: 12 months, ending the day before the anniversary.
    Example: 2026-09-01 -> 2027-08-31.
    """
    start = pd.to_datetime(lease_start_date).date()
    return (
        pd.Timestamp(start)
        + pd.DateOffset(years=1)
        - pd.Timedelta(days=1)
    ).date()


def derived_lease_status(tenant_row, as_of=None):
    """
    Lease status is derived rather than stored:
      Upcoming: today is before lease_start
      Active: tenant is Active and today is within the lease period
      Expired: tenant remains Active after lease_end
      Ended: tenant is Moved Out / Inactive / Archived
    """
    as_of = as_of or date.today()
    row = tenant_row or {}
    tenant_status = str(row.get("status") or "").strip()

    if tenant_status in {"Moved Out", "Inactive", "Archived"}:
        return "Ended"

    try:
        start = (
            pd.to_datetime(row.get("lease_start")).date()
            if row.get("lease_start")
            else None
        )
    except Exception:
        start = None

    try:
        end = (
            pd.to_datetime(row.get("lease_end")).date()
            if row.get("lease_end")
            else None
        )
    except Exception:
        end = None

    if not start or not end:
        return "Needs Lease Dates"

    if as_of < start:
        return "Upcoming"
    if as_of > end:
        return "Expired"
    return "Active"




