def rentflow_debug_enabled():
    try:
        return str(rentflow_secret_get("RENTFLOW_DEBUG", "false")).strip().lower() in {
            "1", "true", "yes", "on"
        }
    except Exception:
        return False


def show_debug_exception(exc):
    if rentflow_debug_enabled():
        st.exception(exc)


def _supabase_jwt_role(token):
    try:
        parts = str(token).split(".")
        if len(parts) != 3:
            return None
        payload = parts[1] + "=" * (-len(parts[1]) % 4)
        claims = json.loads(
            base64.urlsafe_b64decode(payload.encode("utf-8")).decode("utf-8")
        )
        return claims.get("role")
    except Exception:
        return None


def validate_streamlit_supabase_key(key):
    key_text = str(key or "").strip()

    if not key_text:
        raise RuntimeError("SUPABASE_KEY is not configured.")

    if key_text.startswith("sb_secret_") or _supabase_jwt_role(key_text) == "service_role":
        raise RuntimeError(
            "RentFlow Streamlit must use the Supabase anon/publishable key, "
            "not a service-role/secret key."
        )

    return key_text


def get_supabase_server_client():
    """
    Server-only Supabase client for verified Stripe payment finalization.

    Keep SUPABASE_SERVICE_ROLE_KEY only in Streamlit secrets. It is never
    attached to the tenant's browser auth session and is never displayed.
    """
    url = str(rentflow_secret_get("SUPABASE_URL") or "").strip()
    server_key = str(
        rentflow_secret_get("SUPABASE_SERVICE_ROLE_KEY")
        or rentflow_secret_get("SUPABASE_SECRET_KEY")
        or ""
    ).strip()

    if not url:
        raise RuntimeError("SUPABASE_URL is not configured.")

    if not server_key:
        raise RuntimeError(
            "SUPABASE_SERVICE_ROLE_KEY is missing from .streamlit/secrets.toml. "
            "Add the server-only Supabase service-role/secret key so RentFlow "
            "can record verified Stripe payments through RLS."
        )

    # This client is intentionally NOT given the tenant's auth session.
    return create_client(url, server_key)




def validate_upload_size(uploaded_file, max_mb=10):
    if uploaded_file is None:
        return True, None

    size = getattr(uploaded_file, "size", None)
    if size is None:
        try:
            size = len(uploaded_file.getvalue())
        except Exception:
            size = 0

    if size > int(max_mb) * 1024 * 1024:
        return False, f"Maximum upload size is {max_mb} MB."

    return True, None


# =========================================================
# CENTRALIZED AUTHENTICATION — RC13D V3 + SESSION ROLE LOCK
# =========================================================
# One auth authority: Supabase.
# One browser persistence credential: Supabase refresh token.
# No persisted access-token copy, no auth_user copy, no cached global auth client.
_AUTH_COOKIE_NAME = "rentflow_auth_v3"
_AUTH_COOKIE_DAYS = 30
_AUTH_PORTAL_PARAM = "_rf_portal"
_AUTH_ROLE_SIG_PARAM = "_rf_role_sig"
_AUTH_VALID_PORTALS = {"owner", "tenant", "admin"}
_AUTH_SESSION_ROLE_KEY = "_rentflow_session_role"

@st.cache_resource
def _auth_role_signing_key():
    # Process-local signing key. A server restart intentionally invalidates old
    # role locks and requires a clean sign-in rather than guessing a role.
    return secrets.token_bytes(32)

def _auth_role_signature(refresh_token, role):
    payload = f"{str(refresh_token or '')}|{str(role or '').lower()}".encode("utf-8")
    return hmac.new(_auth_role_signing_key(), payload, hashlib.sha256).hexdigest()

def _auth_role_signature_valid(refresh_token, role, signature):
    if role not in _AUTH_VALID_PORTALS or not refresh_token or not signature:
        return False
    expected = _auth_role_signature(refresh_token, role)
    return hmac.compare_digest(expected, str(signature))

def _auth_new_client():
    return create_client(
        rentflow_secret_required("SUPABASE_URL"),
        validate_streamlit_supabase_key(rentflow_secret_required("SUPABASE_KEY")),
    )

def _auth_cookie_bridge(command, value="", cleanup_param=None):
    safe_value = str(value or "").replace("\\", "\\\\").replace("'", "\\'")
    cleanup_js = ""
    if cleanup_param:
        cleanup_js = f"""
        const u = new URL(window.parent.location.href);
        u.searchParams.delete({cleanup_param!r});
        window.parent.location.replace(u.toString());
        """
    components.html(f"""
    <script>
    const NAME = {_AUTH_COOKIE_NAME!r};
    const cmd = {command!r};
    const val = '{safe_value}';
    if (cmd === 'set') {{
      document.cookie = `${{NAME}}=${{encodeURIComponent(val)}}; Max-Age=${{_AUTH_COOKIE_DAYS*86400}}; Path=/; SameSite=Lax; Secure`;
    }} else if (cmd === 'delete') {{
      document.cookie = `${{NAME}}=; Max-Age=0; Path=/; SameSite=Lax; Secure`;
    }}
    {cleanup_js}
    </script>
    """, height=0, width=0)

def _auth_request_cookie_restore():
    if st.query_params.get("_rf_cookie"):
        return str(st.query_params.get("_rf_cookie") or "")
    components.html(f"""
    <script>
    (() => {{
      const name = {_AUTH_COOKIE_NAME!r} + '=';
      let value = '';
      for (const raw of document.cookie.split(';')) {{
        const c = raw.trim();
        if (c.startsWith(name)) {{
          value = decodeURIComponent(c.substring(name.length));
          break;
        }}
      }}
      if (value) {{
        const u = new URL(window.parent.location.href);
        if (!u.searchParams.get('_rf_cookie')) {{
          u.searchParams.set('_rf_cookie', value);
          window.parent.location.replace(u.toString());
        }}
      }}
    }})();
    </script>
    """, height=0, width=0)
    return ""

class RentFlowAuthManager:
    """Single owner of RentFlow browser authentication state."""
    CLIENT_KEY = "_rentflow_auth_client"

    def __init__(self):
        if self.CLIENT_KEY not in st.session_state:
            st.session_state[self.CLIENT_KEY] = _auth_new_client()
        self.client = st.session_state[self.CLIENT_KEY]

    def current_session(self):
        try:
            session = self.client.auth.get_session()
            return session if session and getattr(session, "user", None) else None
        except Exception:
            return None

    def current_user(self):
        session = self.current_session()
        return getattr(session, "user", None) if session else None

    def sign_in(self, email, password, role):
        # RC13D: the portal used for explicit login becomes the immutable role
        # for this authenticated browser session. URL routing cannot change it.
        role = str(role or "").strip().lower()
        if role not in _AUTH_VALID_PORTALS:
            raise ValueError("A valid RentFlow login role is required.")

        # A completed logout leaves a one-time _rf_logout marker in the URL until
        # the browser cookie-deletion handshake finishes. A new explicit login
        # supersedes that stale marker.
        try:
            if "_rf_logout" in st.query_params:
                del st.query_params["_rf_logout"]
        except Exception:
            pass

        result = self.client.auth.sign_in_with_password({
            "email": str(email or "").strip(),
            "password": str(password or ""),
        })
        session = getattr(result, "session", None)
        refresh_token = getattr(session, "refresh_token", None) if session else None
        if not session or not refresh_token:
            raise RuntimeError("Supabase did not return a valid session.")

        st.session_state[_AUTH_SESSION_ROLE_KEY] = role
        st.query_params["_rf_cookie"] = refresh_token
        st.query_params[_AUTH_PORTAL_PARAM] = role
        st.query_params[_AUTH_ROLE_SIG_PARAM] = _auth_role_signature(refresh_token, role)
        self.apply_portal_context()
        return result

    def persist_session(self, session):
        """Persist sessions returned by signup/recovery without duplicating tokens."""
        if session and getattr(session, "refresh_token", None):
            st.query_params["_rf_cookie"] = session.refresh_token
        return session

    def establish_session(self, access_token, refresh_token):
        """Establish a Supabase callback/recovery session through AuthManager."""
        result = self.client.auth.set_session(access_token, refresh_token)
        session = getattr(result, "session", None) or self.current_session()
        self.persist_session(session)
        return session

    def set_active_portal(self, portal):
        """Set portal context, but never override an authenticated RC13D role lock."""
        requested = str(portal or "").strip().lower()
        if requested not in _AUTH_VALID_PORTALS:
            raise ValueError("Invalid RentFlow portal context.")
        locked = str(st.session_state.get(_AUTH_SESSION_ROLE_KEY) or "").strip().lower()
        portal = locked if locked in _AUTH_VALID_PORTALS else requested
        st.query_params[_AUTH_PORTAL_PARAM] = portal
        self.apply_portal_context()

    def apply_portal_context(self):
        """Apply the authenticated role lock; URL routing never grants/switches roles."""
        locked = str(st.session_state.get(_AUTH_SESSION_ROLE_KEY) or "").strip().lower()
        requested = str(st.query_params.get(_AUTH_PORTAL_PARAM) or "").strip().lower()
        portal = locked if locked in _AUTH_VALID_PORTALS else requested
        if portal not in _AUTH_VALID_PORTALS:
            portal = ""
        if locked in _AUTH_VALID_PORTALS and requested != locked:
            st.query_params[_AUTH_PORTAL_PARAM] = locked
        if portal == "admin":
            st.session_state["admin_auth_mode"] = True
            st.session_state["tenant_auth_mode"] = False
            st.session_state["show_auth_screen"] = True
        elif portal == "tenant":
            st.session_state["admin_auth_mode"] = False
            st.session_state["tenant_auth_mode"] = True
        elif portal == "owner":
            st.session_state["admin_auth_mode"] = False
            st.session_state["tenant_auth_mode"] = False
        return portal

    def restore(self):
        # Logout handshake always wins over every other routing path.
        if st.query_params.get("_rf_logout"):
            st.session_state.pop(_AUTH_SESSION_ROLE_KEY, None)
            _auth_cookie_bridge("delete", cleanup_param="_rf_logout")
            return None

        refresh_token = str(st.query_params.get("_rf_cookie") or "")
        requested_role = str(st.query_params.get(_AUTH_PORTAL_PARAM) or "").strip().lower()
        role_sig = str(st.query_params.get(_AUTH_ROLE_SIG_PARAM) or "")
        locked_role = str(st.session_state.get(_AUTH_SESSION_ROLE_KEY) or "").strip().lower()

        # When a browser refresh supplies the persisted credential, restore the
        # role only from a server-signed role binding. A hand-edited _rf_portal
        # therefore cannot turn an Admin into an Owner (or vice versa).
        if refresh_token:
            signed_role = requested_role
            if _auth_role_signature_valid(refresh_token, signed_role, role_sig):
                locked_role = signed_role
                st.session_state[_AUTH_SESSION_ROLE_KEY] = locked_role
            elif locked_role not in _AUTH_VALID_PORTALS:
                # RC13C/unsigned or tampered persistence: fail closed.
                _auth_cookie_bridge("delete", cleanup_param="_rf_cookie")
                return None

            # The session role is authoritative even if the URL was edited.
            st.query_params[_AUTH_PORTAL_PARAM] = locked_role
            try:
                result = self.client.auth.refresh_session(refresh_token)
                session = getattr(result, "session", None)
                if session and getattr(session, "user", None):
                    newest = getattr(session, "refresh_token", None) or refresh_token
                    st.query_params[_AUTH_ROLE_SIG_PARAM] = _auth_role_signature(newest, locked_role)
                    _auth_cookie_bridge("set", newest, cleanup_param="_rf_cookie")
                    self.apply_portal_context()
                    return session
            except Exception:
                st.session_state.pop(_AUTH_SESSION_ROLE_KEY, None)
                _auth_cookie_bridge("delete", cleanup_param="_rf_cookie")
                return None

        current = self.current_session()
        if current and locked_role in _AUTH_VALID_PORTALS:
            st.query_params[_AUTH_PORTAL_PARAM] = locked_role
            self.apply_portal_context()
            return current

        # An authenticated Supabase session without a RentFlow role lock is not
        # enough to choose a portal. Require explicit RentFlow sign-in.
        if current:
            try:
                self.client.auth.sign_out()
            except Exception:
                pass

        self.apply_portal_context()
        _auth_request_cookie_restore()
        return None

    def logout(self):
        try:
            self.client.auth.sign_out()
        except Exception:
            pass
        st.session_state.pop(self.CLIENT_KEY, None)
        # Clear only auth/routing state that could reopen a protected portal.
        for key in (
            "show_auth_screen", "tenant_auth_mode", "admin_auth_mode",
            "auth_default_tab", "auth_recovery_mode", "forgot_email_mode",
            "tenant_password_recovery_mode", "password_recovery_verified",
            "password_recovery_origin", _AUTH_SESSION_ROLE_KEY,
        ):
            st.session_state.pop(key, None)
        st.query_params.clear()
        st.query_params["_rf_logout"] = "1"

_auth_manager = RentFlowAuthManager()
supabase = _auth_manager.client

def get_supabase():
    """Compatibility accessor; authentication is owned only by _auth_manager."""
    return _auth_manager.client

def save_auth_session(session):
    """Compatibility for signup/recovery flows; no token copies are stored."""
    return _auth_manager.persist_session(session)

def clear_auth_session():
    """Legacy compatibility name. Clear the live auth client only."""
    st.session_state.pop(_auth_manager.CLIENT_KEY, None)

def auth_sign_in_with_password(email, password, role):
    return _auth_manager.sign_in(email, password, role)

def auth_set_active_portal(portal):
    return _auth_manager.set_active_portal(portal)

def auth_logout():
    _auth_manager.logout()
    st.rerun()


def get_rentflow_user_guide_bytes():
    """Load the V66 Owner User Guide placed beside streamlit_app.py."""
    candidates = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "rentflow_user_guide_v66.pdf"),
        os.path.join(os.getcwd(), "rentflow_user_guide_v66.pdf"),
        "/mnt/data/rentflow_user_guide_v66.pdf",
    ]
    for candidate in candidates:
        try:
            if os.path.exists(candidate):
                with open(candidate, "rb") as guide_file:
                    return guide_file.read()
        except Exception:
            pass
    return None


def render_rentflow_user_guide_download(key, use_container_width=True):
    guide_bytes = get_rentflow_user_guide_bytes()
    if not guide_bytes:
        st.caption("Owner User Guide will be available here when deployed.")
        return False
    st.download_button(
        "📘 Download Owner User Guide",
        data=guide_bytes,
        file_name="RentFlow_Owner_User_Guide.pdf",
        mime="application/pdf",
        use_container_width=use_container_width,
        key=key,
    )
    return True


def get_rentflow_app_url():
    """
    Optional production/public URL used by Supabase recovery emails.

    Add RENTFLOW_APP_URL to .streamlit/secrets.toml when you have a stable URL.
    If it is not configured, Supabase falls back to the project's Site URL.
    """
    try:
        value = rentflow_secret_get("RENTFLOW_APP_URL")
        return str(value).rstrip("/") if value else None
    except Exception:
        return None


def get_recovery_redirect_url(origin="owner"):
    """Return RentFlow recovery callback URL while preserving portal origin."""
    app_url = get_rentflow_app_url()
    if not app_url:
        return None

    separator = "&" if "?" in app_url else "?"
    return f"{app_url}{separator}rf_recovery={origin}"


def show_forgot_password_page():

    recovery_left, recovery_center, recovery_right = st.columns([1, 2, 1])
    with recovery_center:
        st.markdown("### 🔑 Reset Your Password")
        st.caption(
            "Enter the email associated with your RentFlow account. "
            "For security, RentFlow will not confirm whether an account exists."
        )

        with st.form("rentflow_forgot_password", clear_on_submit=False):
            recovery_email = st.text_input(
                "Account Email",
                key="forgot_password_email"
            )
            send_reset = st.form_submit_button(
                "Send Reset Link",
                type="primary",
                use_container_width=True
            )

        if send_reset:
            if not recovery_email.strip():
                st.error("Enter your email address.")
            else:
                try:
                    recovery_url = get_recovery_redirect_url("owner")

                    if recovery_url:
                        supabase.auth.reset_password_for_email(
                            recovery_email.strip(),
                            {"redirect_to": recovery_url}
                        )
                    else:
                        supabase.auth.reset_password_for_email(
                            recovery_email.strip()
                        )

                    st.success(
                        "If an account exists for that email, password-reset "
                        "instructions have been sent."
                    )
                    st.info(
                        "Open the RentFlow password-reset email and follow the "
                        "secure link to choose a new password."
                    )
                except Exception:
                    # Keep the response generic to avoid leaking whether
                    # an email address is registered.
                    st.success(
                        "If an account exists for that email, password-reset "
                        "instructions have been sent."
                    )

        if st.button(
            "← Back to Sign In",
            use_container_width=True,
            key="forgot_password_back"
        ):
            st.session_state.pop("auth_recovery_mode", None)
            st.rerun()

def show_forgot_email_page():
    st.markdown("### 📧 Forgot Your Email?")
    st.warning(
        "For your security, RentFlow does not reveal account email "
        "addresses from the public sign-in screen."
    )

    st.markdown(
        """
        Try these steps:

        - Try the email address you normally use for your rental or property business.
        - Search your inboxes for **RentFlow**, account-verification, or password-reset messages.
        - Check saved passwords in your browser or password manager.
        - If you still cannot identify the account email, contact RentFlow support or your account administrator after identity verification.
        """
    )

    try:
        support_email = rentflow_secret_get("RENTFLOW_SUPPORT_EMAIL")
    except Exception:
        support_email = None

    if support_email:
        st.info(f"RentFlow Support: **{support_email}**")
    else:
        pass

    if st.button(
        "← Back to Sign In",
        key="forgot_email_back"
    ):
        st.session_state.pop("forgot_email_mode", None)
        st.rerun()


def show_reset_password_page():
    st.markdown(
        """
        <div style="max-width:680px;margin:3rem auto 1.5rem auto;text-align:center;">
            <div style="font-size:3rem;">🔐</div>
            <h1 style="margin-bottom:.25rem;">Choose a New Password</h1>
            <p style="opacity:.7;font-size:1.05rem;">
                Your recovery link has been verified.
            </p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    left, center, right = st.columns([0.7, 2.6, 0.7])

    with center:
        with st.form("rentflow_set_new_password"):
            new_password = st.text_input(
                "New Password",
                type="password",
                key="recovery_new_password"
            )
            confirm_password = st.text_input(
                "Confirm New Password",
                type="password",
                key="recovery_confirm_password"
            )
            update_password = st.form_submit_button(
                "Update Password",
                type="primary",
                use_container_width=True
            )

        if update_password:
            if len(new_password) < 6:
                st.error("Password must be at least 6 characters.")
            elif new_password != confirm_password:
                st.error("Passwords do not match.")
            else:
                try:
                    # RC2 launch-blocking recovery hardening:
                    # 1) Re-establish the verified recovery session on this client.
                    # 2) Update the password and validate the returned user.
                    # 3) Prove the new password works with a fresh Supabase client.
                    # 4) Only then clear recovery state and return to Sign In.
                    recovery_session = _auth_manager.current_session()
                    if not recovery_session:
                        raise RuntimeError(
                            "Your recovery session is no longer available. "
                            "Please request a new password-reset email."
                        )

                    recovery_user = getattr(recovery_session, "user", None)
                    if recovery_user is None:
                        current_user_response = supabase.auth.get_user()
                        recovery_user = getattr(
                            current_user_response,
                            "user",
                            None,
                        )

                    recovery_email = str(
                        getattr(recovery_user, "email", "") or ""
                    ).strip()

                    if not recovery_user or not recovery_email:
                        raise RuntimeError(
                            "RentFlow could not verify the recovery account. "
                            "Please request a new password-reset email."
                        )

                    update_response = supabase.auth.update_user({
                        "password": new_password
                    })

                    updated_user = getattr(update_response, "user", None)
                    if updated_user is None:
                        raise RuntimeError(
                            "Supabase did not confirm the password update."
                        )

                    # Verify with a completely fresh anon-key client so a stale
                    # recovery session cannot create a false-success screen.
                    verification_client = create_client(
                        rentflow_secret_required("SUPABASE_URL"),
                        validate_streamlit_supabase_key(
                            rentflow_secret_required("SUPABASE_KEY")
                        ),
                    )

                    verification_response = (
                        verification_client.auth.sign_in_with_password({
                            "email": recovery_email,
                            "password": new_password,
                        })
                    )

                    verification_session = getattr(
                        verification_response,
                        "session",
                        None,
                    )
                    verification_user = getattr(
                        verification_response,
                        "user",
                        None,
                    )

                    if not verification_session or not verification_user:
                        raise RuntimeError(
                            "The password update could not be verified. "
                            "Please try again or request a new reset link."
                        )

                    try:
                        verification_client.auth.sign_out()
                    except Exception:
                        pass

                    # End the recovery session through the one centralized auth layer.
                    recovery_origin = st.session_state.get("password_recovery_origin")
                    _auth_manager.logout()
                    st.session_state["show_auth_screen"] = True
                    st.session_state["password_reset_success"] = True

                    if recovery_origin == "tenant":
                        st.session_state["tenant_auth_mode"] = True

                    st.rerun()

                except Exception as e:
                    st.error(
                        "Unable to update and verify your password. "
                        "Please try again or request a new reset link."
                    )
                    show_debug_exception(e)




def send_tenant_portal_invite_email(
    tenant_name,
    tenant_email,
    invite_code,
):
    """
    Send a Tenant Portal invitation using SMTP credentials stored
    only in Streamlit secrets.

    P1 uses Resend SMTP.
    Required secrets:
        SMTP_HOST = "smtp.resend.com"
        SMTP_PORT = 587
        SMTP_USERNAME = "resend"
        SMTP_PASSWORD = Resend API key
        SMTP_FROM_EMAIL = sender on a verified domain

    Optional:
        SMTP_FROM_NAME
        RENTFLOW_APP_URL
    """

    required = [
        "SMTP_HOST",
        "SMTP_PORT",
        "SMTP_USERNAME",
        "SMTP_PASSWORD",
        "SMTP_FROM_EMAIL",
    ]

    missing = []

    for key in required:
        try:
            value = rentflow_secret_get(key)
        except Exception:
            value = None

        if not value:
            missing.append(key)

    if missing:
        return False, (
            "Email is not configured yet. Missing Streamlit secrets: "
            + ", ".join(missing)
        )

    smtp_host = str(rentflow_secret_required("SMTP_HOST"))
    smtp_port = int(rentflow_secret_required("SMTP_PORT"))
    smtp_username = str(rentflow_secret_required("SMTP_USERNAME"))
    smtp_password = str(rentflow_secret_required("SMTP_PASSWORD"))
    smtp_from_email = str(rentflow_secret_required("SMTP_FROM_EMAIL"))
    smtp_from_name = str(
        rentflow_secret_get(
            "SMTP_FROM_NAME",
            "RentFlow"
        )
    )

    app_url = get_rentflow_app_url()

    if not app_url:
        try:
            app_url = str(
                rentflow_secret_get(
                    "RENTFLOW_APP_URL",
                    ""
                )
            ).strip()
        except Exception:
            app_url = ""

    msg = EmailMessage()

    msg["Subject"] = "Your RentFlow Tenant Portal Invitation"
    msg["From"] = (
        f"{smtp_from_name} <{smtp_from_email}>"
    )
    msg["To"] = tenant_email

    activation_url_text = (
        app_url
        if app_url
        else "Open your RentFlow application"
    )

    body = f"""Hello {tenant_name},

Your property owner has enabled secure access to the RentFlow Tenant Portal.

To activate your account:

1. Open RentFlow:
   {activation_url_text}

2. Choose:
   Tenant Portal → Activate Portal

3. Use this email:
   {tenant_email}

4. Enter this one-time invitation code:
   {invite_code}

5. Create your password and complete activation.

For your security, do not share this invitation code with anyone.

Once activated, you will be able to view your rent, payment history,
lease information, property, and unit details.

RentFlow
Property Management & Owner Intelligence
"""

    msg.set_content(body)

    try:
        if smtp_port == 465:
            with smtplib.SMTP_SSL(
                smtp_host,
                smtp_port,
                timeout=20
            ) as server:
                server.login(
                    smtp_username,
                    smtp_password
                )
                server.send_message(msg)
        else:
            with smtplib.SMTP(
                smtp_host,
                smtp_port,
                timeout=20
            ) as server:
                server.ehlo()
                server.starttls()
                server.ehlo()
                server.login(
                    smtp_username,
                    smtp_password
                )
                server.send_message(msg)

        return True, (
            f"Invitation email sent to {tenant_email}."
        )

    except Exception as e:
        return False, (
            "Unable to send invitation email: "
            + str(e)
        )




def send_rentflow_transactional_email(
    to_email,
    subject,
    body,
):
    """Send a RentFlow transactional email through configured SMTP/Resend."""
    required = [
        "SMTP_HOST",
        "SMTP_PORT",
        "SMTP_USERNAME",
        "SMTP_PASSWORD",
        "SMTP_FROM_EMAIL",
    ]

    missing = []
    for key in required:
        try:
            value = rentflow_secret_get(key)
        except Exception:
            value = None
        if not value:
            missing.append(key)

    if missing:
        return False, (
            "Transactional email is not configured. Missing: "
            + ", ".join(missing)
        )

    msg = EmailMessage()
    msg["Subject"] = subject
    msg["From"] = (
        f"{rentflow_secret_get('SMTP_FROM_NAME', 'RentFlow')} "
        f"<{rentflow_secret_required('SMTP_FROM_EMAIL')}>"
    )
    msg["To"] = to_email
    msg.set_content(body)

    host = str(rentflow_secret_required("SMTP_HOST"))
    port = int(rentflow_secret_required("SMTP_PORT"))
    username = str(rentflow_secret_required("SMTP_USERNAME"))
    password = str(rentflow_secret_required("SMTP_PASSWORD"))

    try:
        if port == 465:
            with smtplib.SMTP_SSL(
                host,
                port,
                timeout=20
            ) as server:
                server.login(username, password)
                server.send_message(msg)
        else:
            with smtplib.SMTP(
                host,
                port,
                timeout=20
            ) as server:
                server.ehlo()
                server.starttls()
                server.ehlo()
                server.login(username, password)
                server.send_message(msg)

        return True, f"Email sent to {to_email}."

    except Exception as e:
        return False, f"Unable to send email: {e}"


def get_stripe_secret_key():
    try:
        value = rentflow_secret_get("STRIPE_SECRET_KEY")
        return str(value).strip() if value else None
    except Exception:
        return None


def get_stripe_publishable_key():
    try:
        value = rentflow_secret_get("STRIPE_PUBLISHABLE_KEY")
        return str(value).strip() if value else None
    except Exception:
        return None



# =========================================================
# V65 - OWNER STRIPE CONNECT FOR TENANT RENT PAYMENTS
# =========================================================

def get_owner_payment_settings(owner_id):
    """Return the owner's tenant-payment setup row."""
    try:
        rows = (
            supabase
            .table("owner_payment_settings")
            .select(
                "owner_id,stripe_connect_account_id,onboarding_status,"
                "details_submitted,charges_enabled,payouts_enabled,"
                "tenant_payments_enabled,tenant_payments_not_required,"
                "last_synced_at"
            )
            .eq("owner_id", str(owner_id))
            .limit(1)
            .execute()
            .data
            or []
        )
        return rows[0] if rows else None
    except Exception:
        return None


def upsert_owner_payment_settings(owner_id, payload=None):
    """Create/update the owner's tenant-payment configuration."""
    data = {"owner_id": str(owner_id)}
    if payload:
        data.update(payload)

    return (
        supabase
        .table("owner_payment_settings")
        .upsert(data, on_conflict="owner_id")
        .execute()
    )


def _stripe_plain_dict(value):
    """Convert StripeObject/dict-like API values into a real Python dict."""
    if value is None:
        return {}
    if isinstance(value, dict):
        return value

    # Stripe SDK objects expose one or both of these depending on version.
    for method_name in ("to_dict_recursive", "to_dict"):
        try:
            method = getattr(value, method_name, None)
            if callable(method):
                converted = method()
                if isinstance(converted, dict):
                    return converted
                try:
                    return dict(converted)
                except Exception:
                    pass
        except Exception:
            pass

    # StripeObject normally exposes its underlying values as mapping items.
    try:
        return {k: value[k] for k in value.keys()}
    except Exception:
        pass

    try:
        return dict(value)
    except Exception:
        return {}



def _stripe_connect_status_from_account(account):
    """
    Legacy Accounts v1 compatibility parser.

    V67C keeps this only as a fallback for older connected accounts. New
    Accounts v2 connected accounts are synchronized by
    _stripe_connect_status_from_v2_account().
    """
    details_submitted = bool(getattr(account, "details_submitted", False))
    charges_enabled = bool(getattr(account, "charges_enabled", False))
    payouts_enabled = bool(getattr(account, "payouts_enabled", False))

    if charges_enabled:
        onboarding_status = "Connected"
    elif details_submitted:
        onboarding_status = "Action Required"
    else:
        onboarding_status = "Onboarding Started"

    return {
        "onboarding_status": onboarding_status,
        "details_submitted": details_submitted,
        "charges_enabled": charges_enabled,
        "payouts_enabled": payouts_enabled,
        "tenant_payments_enabled": charges_enabled,
        "tenant_payments_not_required": False,
        "last_synced_at": datetime.now(timezone.utc).isoformat(),
    }


def _stripe_v2_status_detail_codes(capability):
    if not isinstance(capability, dict):
        return set()
    codes = set()
    for detail in capability.get("status_details") or []:
        if isinstance(detail, dict) and detail.get("code"):
            codes.add(str(detail.get("code")))
    return codes


def _stripe_v2_has_blocking_requirements(requirements):
    """Return True when Accounts v2 says owner action is currently due."""
    if not isinstance(requirements, dict):
        return False

    summary = requirements.get("summary") or {}
    minimum_deadline = summary.get("minimum_deadline") or {}
    if minimum_deadline.get("status") in {"currently_due", "past_due"}:
        return True

    for entry in requirements.get("entries") or []:
        if not isinstance(entry, dict):
            continue
        deadline = entry.get("minimum_deadline") or {}
        if deadline.get("status") in {"currently_due", "past_due"}:
            return True
        impact = entry.get("impact") or {}
        restricts = impact.get("restricts_capabilities") or {}
        impact_deadline = restricts.get("deadline") or {}
        if impact_deadline.get("status") in {"currently_due", "past_due"}:
            return True
    return False


def _stripe_connect_status_from_v2_account(account):
    """
    V67C: derive RentFlow readiness directly from Stripe Accounts v2.

    Stripe Accounts v2 exposes merchant capability status under
    configuration.merchant.capabilities instead of the v1 top-level
    charges_enabled / payouts_enabled fields.
    """
    if not isinstance(account, dict):
        raise RuntimeError("Stripe Accounts v2 returned an invalid account object.")

    configuration = account.get("configuration") or {}
    merchant = configuration.get("merchant") or {}
    capabilities = merchant.get("capabilities") or {}

    card_payments = capabilities.get("card_payments") or {}
    stripe_balance = capabilities.get("stripe_balance") or {}
    payouts = stripe_balance.get("payouts") or {}

    card_status = str(card_payments.get("status") or "").lower()
    payout_status = str(payouts.get("status") or "").lower()

    # Stripe Accounts v2 capability representations have evolved across
    # preview versions. Treat only explicit positive states as enabled; never
    # infer readiness merely from onboarding completion.
    positive_statuses = {"active", "enabled", "available"}
    charges_enabled = card_status in positive_statuses
    payouts_enabled = payout_status in positive_statuses
    if isinstance(card_payments, dict):
        charges_enabled = charges_enabled or bool(card_payments.get("active"))
    elif card_payments is True:
        charges_enabled = True
    if isinstance(payouts, dict):
        payouts_enabled = payouts_enabled or bool(payouts.get("active"))
    elif payouts is True:
        payouts_enabled = True

    card_codes = _stripe_v2_status_detail_codes(card_payments)
    payout_codes = _stripe_v2_status_detail_codes(payouts)
    status_codes = card_codes | payout_codes
    requirements = account.get("requirements") or {}

    action_required = (
        _stripe_v2_has_blocking_requirements(requirements)
        or "requirements_past_due" in status_codes
        or any(
            isinstance(detail, dict) and detail.get("resolution") == "provide_info"
            for capability in (card_payments, payouts)
            for detail in (capability.get("status_details") or [])
        )
    )
    pending_verification = bool(
        {"requirements_pending_verification", "determining_status"} & status_codes
    )

    applied = set(account.get("applied_configurations") or [])
    identity_present = bool(account.get("identity"))
    details_submitted = bool(
        charges_enabled
        or payouts_enabled
        or ("merchant" in applied and identity_present and not action_required)
    )

    if charges_enabled and payouts_enabled:
        onboarding_status = "Connected"
    elif charges_enabled:
        # Rent collection can proceed; payout availability may still be
        # activating or subject to a separate Stripe requirement.
        onboarding_status = "Connected"
    elif pending_verification:
        onboarding_status = "Pending Verification"
    elif action_required:
        onboarding_status = "Action Required"
    else:
        onboarding_status = "Onboarding Started"

    return {
        "onboarding_status": onboarding_status,
        "details_submitted": details_submitted,
        "charges_enabled": charges_enabled,
        "payouts_enabled": payouts_enabled,
        "tenant_payments_enabled": charges_enabled,
        # An actual connected account always overrides a stale Not Required flag.
        "tenant_payments_not_required": False,
        "last_synced_at": datetime.now(timezone.utc).isoformat(),
    }


def _stripe_v2_request(method, path, payload=None):
    """
    Call Stripe Accounts v2 with the platform secret key.

    V66C intentionally uses the standard library here so RentFlow does not
    depend on a particular stripe-python release exposing every v2 resource.
    """
    secret_key = get_stripe_secret_key()
    if not secret_key:
        raise RuntimeError(
            "STRIPE_SECRET_KEY is missing from .streamlit/secrets.toml"
        )

    url = f"https://api.stripe.com{path}"
    body = None
    headers = {
        "Authorization": f"Bearer {secret_key}",
        "Stripe-Version": "2026-08-26.preview",
        "Content-Type": "application/json",
    }

    if payload is not None:
        body = json.dumps(payload).encode("utf-8")

    request = urllib.request.Request(
        url,
        data=body,
        headers=headers,
        method=method.upper(),
    )

    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", errors="replace")
        try:
            parsed = json.loads(detail)
            error = parsed.get("error") or parsed
            message = (
                error.get("message")
                if isinstance(error, dict)
                else str(error)
            )
            code = (
                error.get("code")
                if isinstance(error, dict)
                else None
            )
            if code:
                message = f"{message} ({code})"
        except Exception:
            message = detail or str(e)

        raise RuntimeError(
            f"Stripe Accounts v2 returned HTTP {e.code}: {message}"
        ) from e
    except Exception as e:
        raise RuntimeError(
            f"Unable to reach Stripe Accounts v2: {e}"
        ) from e


def ensure_owner_connect_account(owner_id, owner_email=None):
    """
    Create a Stripe Accounts v2 connected merchant for tenant rent payments.

    V66C configuration:
      - Full Stripe Dashboard for the property owner.
      - Stripe collects direct-charge payment fees.
      - Stripe is responsible for connected-account negative balances.
      - Stripe-hosted onboarding collects KYC/payment requirements.

    RentFlow stores only the Stripe account ID and readiness/status fields.
    """
    if not STRIPE_AVAILABLE:
        raise RuntimeError(
            "Stripe package is not installed. Run: pip install stripe"
        )

    secret_key = get_stripe_secret_key()
    if not secret_key:
        raise RuntimeError(
            "STRIPE_SECRET_KEY is missing from .streamlit/secrets.toml"
        )

    settings = get_owner_payment_settings(owner_id) or {}
    account_id = settings.get("stripe_connect_account_id")

    if settings.get("tenant_payments_not_required"):
        upsert_owner_payment_settings(
            owner_id,
            {
                "tenant_payments_not_required": False,
                "tenant_payments_enabled": False,
                "onboarding_status": (
                    "Onboarding Started" if account_id else "Not Started"
                ),
            },
        )

    # Accounts v2 IDs can also be read through the v1 Account retrieve API.
    # Reuse a stored account rather than ever creating a duplicate.
    if account_id:
        try:
            stripe.api_key = secret_key
            stripe.Account.retrieve(account_id)
            return str(account_id)
        except Exception as e:
            raise RuntimeError(
                f"Existing Stripe connected account {account_id} "
                f"could not be retrieved: {e}"
            ) from e

    email = str(owner_email or "").strip()
    if not email:
        raise RuntimeError(
            "The owner email is required before Stripe tenant-payment "
            "onboarding can begin."
        )

    display_name = email.split("@", 1)[0].strip() or "RentFlow Property Owner"

    payload = {
        "contact_email": email,
        "display_name": display_name,
        "dashboard": "full",
        "identity": {
            "country": "us",
        },
        "configuration": {
            "merchant": {
                "capabilities": {
                    "card_payments": {
                        "requested": True,
                    },
                },
            },
        },
        "defaults": {
            "currency": "usd",
            "responsibilities": {
                "fees_collector": "stripe",
                "losses_collector": "stripe",
            },
        },
        "metadata": {
            "rentflow_owner_id": str(owner_id),
            "purpose": "tenant_rent_payments",
        },
        "include": [
            "configuration.merchant",
            "identity",
            "requirements",
        ],
    }

    try:
        account = _stripe_v2_request(
            "POST",
            "/v2/core/accounts",
            payload,
        )
    except Exception as e:
        raise RuntimeError(
            "Stripe could not create the owner's Accounts v2 connected "
            f"account. Stripe detail: {e}"
        ) from e

    account_id = str(account.get("id") or "").strip()
    if not account_id:
        raise RuntimeError(
            "Stripe created an Accounts v2 response without an account ID."
        )

    upsert_owner_payment_settings(
        owner_id,
        {
            "stripe_connect_account_id": account_id,
            "onboarding_status": "Onboarding Started",
            "details_submitted": False,
            "charges_enabled": False,
            "payouts_enabled": False,
            "tenant_payments_enabled": False,
            "tenant_payments_not_required": False,
        },
    )

    return account_id


def sync_owner_connect_account(owner_id):
    """
    V67C: Refresh Stripe Connect status into RentFlow from Accounts v2.

    The previous implementation retrieved a newly-created Accounts v2 account
    through the v1 Account API. That compatibility object can leave the v1
    charges_enabled / payouts_enabled fields false even after hosted onboarding
    is complete. V67C reads the v2 merchant capabilities directly.
    """
    if not get_stripe_secret_key():
        return get_owner_payment_settings(owner_id)

    settings = get_owner_payment_settings(owner_id) or {}
    account_id = str(settings.get("stripe_connect_account_id") or "").strip()

    if not account_id:
        return settings

    # Any real Stripe account means the owner elected to use online payments.
    # Clear a stale Not Required flag even if Stripe retrieval temporarily fails.
    if settings.get("tenant_payments_not_required"):
        upsert_owner_payment_settings(
            owner_id,
            {
                "stripe_connect_account_id": account_id,
                "tenant_payments_not_required": False,
                "onboarding_status": settings.get("onboarding_status") or "Onboarding Started",
            },
        )
        settings["tenant_payments_not_required"] = False

    # V67C payment-readiness reconciliation:
    # Query both Stripe Accounts v2 and the connected-account compatibility
    # endpoint when possible. A positive charge-enabled result from either
    # Stripe representation is authoritative. A negative/unknown result from
    # one representation must not overwrite a positive result from the other.
    v2_payload = None
    legacy_payload = None

    try:
        include_query = (
            "?include%5B0%5D=configuration.merchant"
            "&include%5B1%5D=requirements"
            "&include%5B2%5D=identity"
            "&include%5B3%5D=defaults"
        )
        account = _stripe_v2_request(
            "GET",
            f"/v2/core/accounts/{account_id}{include_query}",
        )
        v2_payload = _stripe_connect_status_from_v2_account(account)
    except Exception:
        v2_payload = None

    if STRIPE_AVAILABLE:
        try:
            stripe.api_key = get_stripe_secret_key()
            legacy_account = stripe.Account.retrieve(account_id)
            legacy_payload = _stripe_connect_status_from_account(legacy_account)
        except Exception:
            legacy_payload = None

    if not v2_payload and not legacy_payload:
        # Preserve stored state if Stripe cannot be reached. Never create a
        # duplicate account and never disable a previously working connection
        # just because a transient status refresh failed.
        return settings

    payload = dict(v2_payload or legacy_payload or {})

    if v2_payload and legacy_payload:
        combined_charges = bool(
            v2_payload.get("charges_enabled")
            or legacy_payload.get("charges_enabled")
        )
        combined_payouts = bool(
            v2_payload.get("payouts_enabled")
            or legacy_payload.get("payouts_enabled")
        )
        combined_details = bool(
            v2_payload.get("details_submitted")
            or legacy_payload.get("details_submitted")
        )

        payload["charges_enabled"] = combined_charges
        payload["payouts_enabled"] = combined_payouts
        payload["details_submitted"] = combined_details
        payload["tenant_payments_enabled"] = combined_charges
        payload["tenant_payments_not_required"] = False

        if combined_charges:
            payload["onboarding_status"] = "Connected"
        elif v2_payload.get("onboarding_status") in {
            "Action Required", "Pending Verification"
        }:
            payload["onboarding_status"] = v2_payload.get("onboarding_status")
        else:
            payload["onboarding_status"] = (
                v2_payload.get("onboarding_status")
                or legacy_payload.get("onboarding_status")
                or "Onboarding Started"
            )

    payload["stripe_connect_account_id"] = account_id
    upsert_owner_payment_settings(owner_id, payload)

    refreshed = get_owner_payment_settings(owner_id) or {}
    refreshed.update(payload)
    return refreshed


def create_owner_connect_onboarding_link(owner_id, owner_email=None):
    """Create a short-lived Stripe Accounts v2 hosted onboarding link."""
    account_id = ensure_owner_connect_account(
        owner_id,
        owner_email,
    )

    app_url = get_rentflow_app_url()
    if not app_url:
        raise RuntimeError(
            "RENTFLOW_APP_URL is missing from .streamlit/secrets.toml"
        )

    payload = {
        "account": account_id,
        "use_case": {
            "type": "account_onboarding",
            "account_onboarding": {
                "configurations": ["merchant"],
                "collection_options": {
                    "fields": "eventually_due",
                    "future_requirements": "include",
                },
                "refresh_url": f"{app_url}?stripe_connect=refresh",
                "return_url": f"{app_url}?stripe_connect=return",
            },
        },
    }

    try:
        account_link = _stripe_v2_request(
            "POST",
            "/v2/core/account_links",
            payload,
        )
    except Exception as e:
        raise RuntimeError(
            "Stripe connected account exists, but RentFlow could not create "
            f"the Accounts v2 onboarding link. Stripe detail: {e}"
        ) from e

    url = str(account_link.get("url") or "").strip()
    if not url:
        raise RuntimeError(
            "Stripe created an Accounts v2 onboarding response without a URL."
        )

    # Existing RentFlow UI expects account_link.url.
    class _AccountLinkResult:
        def __init__(self, value):
            self.url = value

    return _AccountLinkResult(url)


def create_owner_connect_dashboard_link(owner_id):
    """
    V66C uses Stripe's full Dashboard for connected owners.

    Full-Dashboard Accounts v2 accounts do not use Express login links.
    Return Stripe's normal Dashboard URL; the owner signs in to the Stripe
    account they completed during hosted onboarding.
    """
    settings = sync_owner_connect_account(owner_id) or {}
    account_id = settings.get("stripe_connect_account_id")
    if not account_id:
        raise RuntimeError("Stripe tenant payments are not connected yet.")

    return "https://dashboard.stripe.com/"





def get_tenant_payment_config_via_rpc():
    """
    V67C - Read the signed-in tenant's owner payment readiness through
    a SECURITY DEFINER Supabase RPC.

    The RPC derives the owner from auth.uid(); the tenant does not supply
    an owner_id and does not need direct SELECT access to
    owner_payment_settings.
    """
    try:
        response = (
            supabase
            .rpc("get_my_tenant_payment_config")
            .execute()
        )
        rows = response.data or []

        if isinstance(rows, dict):
            row = rows
        elif isinstance(rows, list) and rows:
            row = rows[0] or {}
        else:
            row = {}

        return {
            "stripe_connect_account_id": row.get("stripe_connect_account_id"),
            "tenant_payments_enabled": bool(
                row.get("tenant_payments_enabled")
            ),
            "charges_enabled": bool(row.get("charges_enabled")),
            "payouts_enabled": bool(row.get("payouts_enabled")),
            "onboarding_status": row.get("onboarding_status"),
        }
    except Exception:
        return {}


def resolve_owner_connect_for_tenant(owner_id):
    """
    V67C tenant-safe Stripe readiness resolver.

    Tenant RLS may intentionally prevent a tenant session from reading
    owner_payment_settings. When that happens, verify the owner's connected
    account server-side with the platform Stripe secret instead of treating
    the missing owner-only row as "payments disabled". No owner Stripe
    credentials or account settings are exposed to the tenant UI.
    """
    owner_id = str(owner_id or "").strip()
    if not owner_id:
        return {}

    # Fast path: owner_payment_settings is readable in this session.
    settings = get_owner_payment_settings(owner_id) or {}
    if (
        settings.get("stripe_connect_account_id")
        and settings.get("tenant_payments_enabled")
    ):
        return settings

    if not STRIPE_AVAILABLE or not get_stripe_secret_key():
        return settings

    # Tenant sessions may be blocked by RLS from owner_payment_settings.
    # Discover only this owner's connected account by the metadata RentFlow
    # wrote when onboarding was created, then verify its Stripe capability.
    try:
        stripe.api_key = get_stripe_secret_key()
        matched_account_id = None

        accounts = stripe.Account.list(limit=100)
        for account in getattr(accounts, "data", []) or []:
            metadata = _stripe_plain_dict(
                getattr(account, "metadata", None)
            )
            if (
                str(metadata.get("rentflow_owner_id") or "") == owner_id
                and str(metadata.get("purpose") or "") == "tenant_rent_payments"
            ):
                matched_account_id = str(getattr(account, "id", "") or "")
                break

        if not matched_account_id:
            return settings

        v2_payload = None
        legacy_payload = None

        try:
            include_query = (
                "?include%5B0%5D=configuration.merchant"
                "&include%5B1%5D=requirements"
                "&include%5B2%5D=identity"
                "&include%5B3%5D=defaults"
            )
            account_v2 = _stripe_v2_request(
                "GET",
                f"/v2/core/accounts/{matched_account_id}{include_query}",
            )
            v2_payload = _stripe_connect_status_from_v2_account(account_v2)
        except Exception:
            pass

        try:
            legacy_account = stripe.Account.retrieve(matched_account_id)
            legacy_payload = _stripe_connect_status_from_account(legacy_account)
        except Exception:
            pass

        if not v2_payload and not legacy_payload:
            return settings

        charges_enabled = bool(
            (v2_payload or {}).get("charges_enabled")
            or (legacy_payload or {}).get("charges_enabled")
        )
        payouts_enabled = bool(
            (v2_payload or {}).get("payouts_enabled")
            or (legacy_payload or {}).get("payouts_enabled")
        )

        # Return an ephemeral server-side result. Do not require a tenant
        # session to update/read the owner-only Supabase settings row.
        return {
            "owner_id": owner_id,
            "stripe_connect_account_id": matched_account_id,
            "charges_enabled": charges_enabled,
            "payouts_enabled": payouts_enabled,
            "tenant_payments_enabled": charges_enabled,
            "onboarding_status": "Connected" if charges_enabled else "Action Required",
        }
    except Exception:
        return settings

def owner_tenant_payments_ready(owner_id):
    settings = sync_owner_connect_account(owner_id) or {}
    return bool(
        settings.get("tenant_payments_enabled")
        and settings.get("stripe_connect_account_id")
    )


def reconcile_paid_stripe_sessions_for_tenant(tenant_profile, max_sessions=100):
    """
    Recover paid Stripe Checkout Sessions that were not written to Supabase.

    This is intentionally scoped to the currently authenticated tenant and
    the owner's connected Stripe account. It makes the tenant portal resilient
    when Stripe redirects back to a fresh Streamlit session/landing page.
    """
    if not tenant_profile or not STRIPE_AVAILABLE:
        return {"recorded": 0, "already_recorded": 0, "checked": 0}

    secret_key = get_stripe_secret_key()
    if not secret_key:
        return {"recorded": 0, "already_recorded": 0, "checked": 0}

    tenant_id = str(tenant_profile.get("tenant_id") or "")
    owner_id = str(tenant_profile.get("owner_id") or "")
    if not tenant_id or not owner_id:
        return {"recorded": 0, "already_recorded": 0, "checked": 0}

    payment_settings = get_tenant_payment_config_via_rpc() or {}
    connected_account_id = str(
        payment_settings.get("stripe_connect_account_id") or ""
    )
    if not (
        connected_account_id
        and payment_settings.get("tenant_payments_enabled")
        and payment_settings.get("charges_enabled")
    ):
        return {"recorded": 0, "already_recorded": 0, "checked": 0}

    stripe.api_key = secret_key
    server_supabase = get_supabase_server_client()

    result = {
        "recorded": 0,
        "already_recorded": 0,
        "checked": 0,
    }

    sessions = stripe.checkout.Session.list(
        limit=min(int(max_sessions or 100), 100),
        stripe_account=connected_account_id,
    )

    for session in list(getattr(sessions, "data", []) or []):
        result["checked"] += 1

        if str(getattr(session, "payment_status", "") or "") != "paid":
            continue

        metadata = _stripe_plain_dict(
            getattr(session, "metadata", None)
        )

        if str(metadata.get("payment_kind") or "") != "tenant_rent":
            continue
        if str(metadata.get("tenant_id") or "") != tenant_id:
            continue
        if str(metadata.get("owner_id") or "") != owner_id:
            continue

        session_id = str(getattr(session, "id", "") or "")
        unit_id = str(metadata.get("unit_id") or "")
        rent_month = str(metadata.get("rent_month") or "")
        if not session_id or not unit_id or not rent_month:
            continue

        amount_paid = float(getattr(session, "amount_total", 0) or 0) / 100.0
        if amount_paid <= 0:
            continue

        # Preferred idempotency check.
        tracking_supported = True
        try:
            existing = (
                server_supabase
                .table("payments")
                .select("payment_id")
                .eq("stripe_session_id", session_id)
                .limit(1)
                .execute()
            )
            if existing.data:
                result["already_recorded"] += 1
                continue
        except Exception:
            tracking_supported = False

        # Schema-compatible fallback.
        if not tracking_supported:
            existing_rows = (
                server_supabase
                .table("payments")
                .select("payment_id,amount_paid,payment_method,notes")
                .eq("tenant_id", tenant_id)
                .eq("unit_id", unit_id)
                .eq("rent_month", rent_month)
                .execute()
            )
            duplicate = False
            for row in (existing_rows.data or []):
                if (
                    str(row.get("payment_method") or "").lower() == "stripe"
                    and abs(float(row.get("amount_paid") or 0) - amount_paid) < 0.005
                    and session_id in str(row.get("notes") or "")
                ):
                    duplicate = True
                    break
            if duplicate:
                result["already_recorded"] += 1
                continue

        payment_record = {
            "owner_id": owner_id,
            "tenant_id": tenant_id,
            "unit_id": unit_id,
            "rent_month": rent_month,
            "payment_date": date.today().isoformat(),
            "amount_paid": amount_paid,
            "payment_method": "Stripe",
            "notes": (
                "Online Tenant Portal payment"
                if tracking_supported
                else f"Online Tenant Portal payment | Stripe session: {session_id}"
            ),
        }

        if tracking_supported:
            payment_record["stripe_session_id"] = session_id
            payment_record["stripe_payment_intent_id"] = (
                str(getattr(session, "payment_intent", "") or "") or None
            )

        server_supabase.table("payments").insert(payment_record).execute()
        result["recorded"] += 1

    return result




def create_rent_checkout_session(
    tenant_profile,
    unit_info,
    amount_due,
    rent_month,
):
    """
    Create a Stripe Checkout Session for the tenant's current rent balance.
    Test mode is used automatically when STRIPE_SECRET_KEY begins with sk_test_.
    """
    if not STRIPE_AVAILABLE:
        raise RuntimeError(
            "Stripe package is not installed. Run: pip install stripe"
        )

    secret_key = get_stripe_secret_key()
    if not secret_key:
        raise RuntimeError(
            "STRIPE_SECRET_KEY is missing from .streamlit/secrets.toml"
        )

    app_url = get_rentflow_app_url()
    if not app_url:
        raise RuntimeError(
            "RENTFLOW_APP_URL is missing from .streamlit/secrets.toml"
        )

    stripe.api_key = secret_key

    # V67C: the tenant payment path uses a SECURITY DEFINER RPC.
    # The RPC derives the owner from auth.uid(), so tenant RLS never needs
    # direct access to owner_payment_settings.
    payment_settings = get_tenant_payment_config_via_rpc() or {}
    connected_account_id = payment_settings.get(
        "stripe_connect_account_id"
    )

    if not (
        connected_account_id
        and payment_settings.get("tenant_payments_enabled")
        and payment_settings.get("charges_enabled")
    ):
        raise RuntimeError(
            "Online tenant payments are not enabled by this property owner."
        )

    amount_cents = int(round(float(amount_due) * 100))
    if amount_cents <= 0:
        raise RuntimeError("Payment amount must be greater than zero.")

    tenant_id = str(tenant_profile.get("tenant_id"))
    tenant_email = tenant_profile.get("email") or None
    owner_id = str(tenant_profile.get("owner_id") or "")
    unit_id = str(unit_info.get("unit_id") or "")
    unit_number = str(unit_info.get("unit_number") or "")

    if not owner_id:
        raise RuntimeError(
            "The active tenant record is missing owner_id, so Stripe Checkout "
            "cannot be created."
        )

    session = stripe.checkout.Session.create(
        mode="payment",
        customer_email=tenant_email,
        line_items=[
            {
                "price_data": {
                    "currency": "usd",
                    "product_data": {
                        "name": f"Rent Payment - Unit {unit_number}",
                        "description": f"Rent for {rent_month}",
                    },
                    "unit_amount": amount_cents,
                },
                "quantity": 1,
            }
        ],
        metadata={
            "payment_kind": "tenant_rent",
            "tenant_id": tenant_id,
            "unit_id": unit_id,
            "owner_id": owner_id,
            "rent_month": rent_month,
        },
        success_url=(
            f"{app_url}?tenant_payment=success"
            f"&connected_account={connected_account_id}"
            f"&session_id={{CHECKOUT_SESSION_ID}}"
        ),
        cancel_url=f"{app_url}?tenant_payment=cancelled",
        stripe_account=connected_account_id,
    )

    return session


def create_move_out_balance_checkout_session(
    owner_id,
    tenant_id,
    tenant_email,
    unit_id,
    unit_number,
    amount_due,
):
    """
    V74B - Owner-created Stripe Checkout for a moved-out tenant's
    final settlement balance. This uses the owner's existing connected
    Stripe account and does not require the moved-out tenant to be
    currently signed in to RentFlow.
    """
    if not STRIPE_AVAILABLE:
        raise RuntimeError(
            "Stripe package is not installed. Run: pip install stripe"
        )

    secret_key = get_stripe_secret_key()
    if not secret_key:
        raise RuntimeError(
            "STRIPE_SECRET_KEY is missing from .streamlit/secrets.toml"
        )

    app_url = get_rentflow_app_url()
    if not app_url:
        raise RuntimeError(
            "RENTFLOW_APP_URL is missing from .streamlit/secrets.toml"
        )

    payment_settings = get_owner_payment_settings(owner_id) or {}
    connected_account_id = str(
        payment_settings.get("stripe_connect_account_id") or ""
    ).strip()

    if not (
        connected_account_id
        and payment_settings.get("tenant_payments_enabled")
        and payment_settings.get("charges_enabled")
    ):
        raise RuntimeError(
            "Online tenant payments are not enabled for this owner."
        )

    amount_cents = int(round(float(amount_due) * 100))
    if amount_cents <= 0:
        raise RuntimeError(
            "Final move-out balance must be greater than zero."
        )

    stripe.api_key = secret_key

    session = stripe.checkout.Session.create(
        mode="payment",
        customer_email=(tenant_email or None),
        line_items=[
            {
                "price_data": {
                    "currency": "usd",
                    "product_data": {
                        "name": (
                            f"Final Move-Out Balance - Unit "
                            f"{unit_number or '—'}"
                        ),
                        "description": (
                            "RentFlow final tenant move-out settlement balance"
                        ),
                    },
                    "unit_amount": amount_cents,
                },
                "quantity": 1,
            }
        ],
        metadata={
            "payment_kind": "move_out_balance",
            "owner_id": str(owner_id),
            "tenant_id": str(tenant_id),
            "unit_id": str(unit_id),
        },
        success_url=(
            f"{app_url}?move_out_payment=success"
            f"&connected_account={connected_account_id}"
            f"&session_id={{CHECKOUT_SESSION_ID}}"
        ),
        cancel_url=f"{app_url}?move_out_payment=cancelled",
        stripe_account=connected_account_id,
    )

    return session, connected_account_id



def finalize_stripe_payment_if_needed():
    """
    Verify a returned Stripe Checkout Session as a browser-return fallback.

    V67 records connected-account tenant payments primarily through the
    FastAPI Stripe webhook. If the webhook already recorded this Checkout
    Session, this function simply confirms the existing payment. If the
    webhook has not arrived yet, the unique stripe_session_id constraint
    keeps this fallback idempotent.
    """
    payment_state = st.query_params.get("tenant_payment")
    session_id = st.query_params.get("session_id")
    connected_account_id = st.query_params.get("connected_account")

    if payment_state == "cancelled":
        st.warning("Rent payment was cancelled.")
        st.query_params.clear()
        return

    if payment_state != "success" or not session_id:
        return

    if not STRIPE_AVAILABLE:
        st.error("Stripe package is not installed.")
        return

    secret_key = get_stripe_secret_key()
    if not secret_key:
        st.error("Stripe is not configured.")
        return

    stripe.api_key = secret_key

    try:
        if not connected_account_id:
            st.error("Stripe connected-account information is missing.")
            return

        session = stripe.checkout.Session.retrieve(
            session_id,
            stripe_account=connected_account_id
        )

        if session.payment_status != "paid":
            st.warning("Stripe has not marked this payment as paid yet.")
            return

        metadata = _stripe_plain_dict(
            getattr(session, "metadata", None)
        )
        tenant_id = metadata.get("tenant_id")
        unit_id = metadata.get("unit_id")
        owner_id = metadata.get("owner_id")
        rent_month = metadata.get("rent_month")

        if not tenant_id or not unit_id or not owner_id or not rent_month:
            st.error("Stripe payment metadata is incomplete.")
            return

        # Security check: the paid Stripe session must belong to the tenant
        # who is currently authenticated in RentFlow.
        auth_user = st.session_state.get("auth_user")
        active_tenant = resolve_tenant_profile(auth_user) if auth_user else None

        if not active_tenant:
            st.error("Your tenant session could not be verified.")
            return

        if str(active_tenant.get("tenant_id") or "") != str(tenant_id):
            st.error("Stripe payment does not belong to the signed-in tenant.")
            return

        if str(active_tenant.get("owner_id") or "") != str(owner_id):
            st.error("Stripe payment owner does not match the signed-in tenant.")
            return

        # The Stripe session is already verified as paid. Use a separate
        # server-only Supabase client for the owner/private write so RLS on
        # the tenant session cannot prevent legitimate payment recording.
        server_supabase = get_supabase_server_client()

        owner_settings_result = (
            server_supabase
            .table("owner_payment_settings")
            .select(
                "owner_id,stripe_connect_account_id,"
                "tenant_payments_enabled,charges_enabled"
            )
            .eq("owner_id", owner_id)
            .limit(1)
            .execute()
        )
        owner_payment_settings = (
            owner_settings_result.data[0]
            if owner_settings_result.data
            else {}
        )

        if str(
            owner_payment_settings.get("stripe_connect_account_id") or ""
        ) != str(connected_account_id):
            st.error("Stripe payment account does not match this owner.")
            return

        if not bool(owner_payment_settings.get("tenant_payments_enabled")):
            st.error("Tenant payments are not enabled for this owner.")
            return

        amount_paid = float(session.amount_total or 0) / 100.0
        if amount_paid <= 0:
            st.error("Stripe returned an invalid payment amount.")
            return

        # Prefer Stripe-session idempotency when the tracking columns exist.
        stripe_tracking_supported = True
        try:
            existing = (
                server_supabase
                .table("payments")
                .select("payment_id")
                .eq("stripe_session_id", session_id)
                .limit(1)
                .execute()
            )
            if existing.data:
                st.success(
                    "✅ Payment confirmed. RentFlow already recorded it through Stripe."
                )
                st.query_params.clear()
                return
        except Exception:
            stripe_tracking_supported = False

        # Compatibility idempotency fallback for databases created before
        # Stripe tracking columns were added.
        if not stripe_tracking_supported:
            existing_payment = (
                server_supabase
                .table("payments")
                .select("payment_id,amount_paid,payment_method,notes")
                .eq("tenant_id", tenant_id)
                .eq("unit_id", unit_id)
                .eq("rent_month", rent_month)
                .execute()
            )
            for payment_row in (existing_payment.data or []):
                if (
                    str(payment_row.get("payment_method") or "").lower() == "stripe"
                    and abs(float(payment_row.get("amount_paid") or 0) - amount_paid) < 0.005
                    and session_id in str(payment_row.get("notes") or "")
                ):
                    st.success(
                        "✅ Payment confirmed. RentFlow already recorded it through Stripe."
                    )
                    st.query_params.clear()
                    return

        payment_record = {
            "owner_id": owner_id,
            "tenant_id": tenant_id,
            "unit_id": unit_id,
            "rent_month": rent_month,
            "payment_date": date.today().isoformat(),
            "amount_paid": amount_paid,
            "payment_method": "Stripe",
            "notes": (
                "Online Tenant Portal payment"
                if stripe_tracking_supported
                else f"Online Tenant Portal payment | Stripe session: {session_id}"
            ),
        }

        if stripe_tracking_supported:
            payment_record["stripe_session_id"] = session_id
            payment_record["stripe_payment_intent_id"] = (
                str(session.payment_intent)
                if session.payment_intent
                else None
            )

        server_supabase.table("payments").insert(payment_record).execute()

        st.success(
            f"✅ Payment of ${amount_paid:,.2f} was received and recorded."
        )
        st.query_params.clear()

    except Exception as e:
        st.error("Unable to verify or record the Stripe payment.")
        safe_message = str(e)
        for secret_name in (
            "STRIPE_SECRET_KEY",
            "SUPABASE_SERVICE_ROLE_KEY",
            "SUPABASE_SECRET_KEY",
            "SUPABASE_KEY",
        ):
            try:
                secret_value = str(rentflow_secret_get(secret_name) or "")
                if secret_value:
                    safe_message = safe_message.replace(secret_value, "[REDACTED]")
            except Exception:
                pass
        st.caption(
            f"Payment recording error: {type(e).__name__}: {safe_message}"
        )
        show_debug_exception(e)



# =========================================================
# P2 - OWNER STRIPE SUBSCRIPTIONS
# =========================================================

def get_stripe_price_id(plan_name):
    key_map = {
        "Starter": "STRIPE_PRICE_STARTER",
        "Professional": "STRIPE_PRICE_PROFESSIONAL",
        "Portfolio": "STRIPE_PRICE_PORTFOLIO",
    }
    secret_name = key_map.get(plan_name)
    if not secret_name:
        return None
    try:
        value = rentflow_secret_get(secret_name)
        return str(value).strip() if value else None
    except Exception:
        return None


def get_owner_profile(user_id):
    try:
        result = (
            supabase.table("owner_profiles")
            .select(
                "user_id,plan,subscription_status,trial_start,trial_end,"
                "stripe_customer_id,stripe_subscription_id,"
                "cancel_at_period_end,current_period_end"
            )
            .eq("user_id", str(user_id))
            .limit(1)
            .execute()
        )
        if result.data:
            return result.data[0]
    except Exception:
        pass
    return {}


def create_owner_subscription_checkout(user_id, email, plan_name):
    """Create a new owner subscription checkout safely.

    RC13E billing cleanup:
    - validates the configured Price against the active Stripe account/mode
    - treats a stale/migrated stripe_customer_id as recoverable
    - never lets an old customer reference block a fresh Checkout
    - keeps Stripe as the source of truth; the verified return sync writes the
      newly-created customer/subscription IDs back to owner_profiles
    """
    if not STRIPE_AVAILABLE:
        raise RuntimeError("Stripe package is not installed. Run: pip install stripe")

    secret_key = get_stripe_secret_key()
    price_id = get_stripe_price_id(plan_name)
    app_url = get_rentflow_app_url()

    if not secret_key:
        raise RuntimeError("STRIPE_SECRET_KEY is missing.")
    if not price_id:
        raise RuntimeError(f"Stripe price is not configured for {plan_name}.")
    if not app_url:
        raise RuntimeError("RENTFLOW_APP_URL is missing.")

    stripe.api_key = secret_key

    # Fail early with a useful error when a Render Price ID belongs to a
    # different Stripe account/mode or is otherwise invalid.
    try:
        configured_price = stripe.Price.retrieve(str(price_id))
    except Exception as exc:
        raise RuntimeError(
            f"The configured Stripe Price for {plan_name} is not available "
            "to the current Stripe account/mode. Verify the Render "
            f"STRIPE_PRICE_{plan_name.upper()} value."
        ) from exc

    if not bool(getattr(configured_price, "active", True)):
        raise RuntimeError(f"The configured Stripe Price for {plan_name} is inactive.")

    profile = get_owner_profile(user_id)
    existing_customer = str(profile.get("stripe_customer_id") or "").strip()
    usable_customer = None

    # Production/test migrations can leave a cus_ ID in Supabase that does not
    # exist under the Stripe key currently configured in Render. Do not pass
    # that stale ID to Checkout. Stripe will create a new customer from email,
    # and the verified checkout-return sync will persist the new IDs.
    if existing_customer:
        try:
            customer = stripe.Customer.retrieve(existing_customer)
            if not bool(getattr(customer, "deleted", False)):
                usable_customer = existing_customer
        except Exception:
            usable_customer = None

    args = {
        "mode": "subscription",
        "line_items": [{"price": str(price_id), "quantity": 1}],
        "success_url": f"{app_url}?owner_subscription=success&session_id={{CHECKOUT_SESSION_ID}}",
        "cancel_url": f"{app_url}?owner_subscription=cancelled",
        "metadata": {"user_id": str(user_id), "plan": plan_name},
        "subscription_data": {
            "metadata": {"user_id": str(user_id), "plan": plan_name}
        },
    }

    if usable_customer:
        args["customer"] = usable_customer
    else:
        clean_email = str(email or "").strip()
        if not clean_email:
            raise RuntimeError("A verified owner email is required for Stripe Checkout.")
        args["customer_email"] = clean_email

    return stripe.checkout.Session.create(**args)


def sync_owner_subscription_from_checkout(auth_user):
    state = st.query_params.get("owner_subscription")
    session_id = st.query_params.get("session_id")

    if state == "cancelled":
        st.warning("Subscription checkout was cancelled.")
        st.query_params.clear()
        return

    if state != "success" or not session_id:
        return

    if not STRIPE_AVAILABLE or not get_stripe_secret_key():
        st.error("Stripe is not configured.")
        return

    user_id = getattr(auth_user, "id", None)
    if not user_id and isinstance(auth_user, dict):
        user_id = auth_user.get("id")
    if not user_id:
        return

    try:
        stripe.api_key = get_stripe_secret_key()
        session = stripe.checkout.Session.retrieve(
            session_id,
            expand=["subscription"]
        )
        # Stripe metadata is a StripeObject, not a normal Python dict.
        # Convert it before using dictionary methods.
        session_metadata = _stripe_plain_dict(
            getattr(session, "metadata", None)
        )

        if str(session_metadata.get("user_id")) != str(user_id):
            st.error("Subscription checkout does not belong to this account.")
            return

        subscription = session.subscription
        if isinstance(subscription, str):
            subscription = stripe.Subscription.retrieve(subscription)

        payload = {
            "user_id": str(user_id),
            "plan": session_metadata.get("plan") or "Starter",
            "subscription_status": getattr(subscription, "status", "active"),
            "stripe_customer_id": str(session.customer) if session.customer else None,
            "stripe_subscription_id": str(subscription.id) if subscription else None,
        }

        if subscription and getattr(subscription, "trial_end", None):
            payload["trial_end"] = pd.to_datetime(
                subscription.trial_end,
                unit="s",
                utc=True
            ).isoformat()

        # Update the existing owner profile first. Most RentFlow users
        # already have a Starter/trial row, so a generic upsert can fail
        # or leave the original row unchanged if user_id is not the table's
        # primary/unique conflict key.
        existing_profile = (
            supabase
            .table("owner_profiles")
            .select("user_id")
            .eq("user_id", str(user_id))
            .limit(1)
            .execute()
        )

        if existing_profile.data:
            (
                supabase
                .table("owner_profiles")
                .update({
                    "plan": payload["plan"],
                    "subscription_status": payload["subscription_status"],
                    "stripe_customer_id": payload["stripe_customer_id"],
                    "stripe_subscription_id": payload["stripe_subscription_id"],
                    **(
                        {"trial_end": payload["trial_end"]}
                        if payload.get("trial_end")
                        else {}
                    ),
                })
                .eq("user_id", str(user_id))
                .execute()
            )
        else:
            (
                supabase
                .table("owner_profiles")
                .insert(payload)
                .execute()
            )

        # Read it back so we know Supabase actually persisted the upgrade.
        verified_profile = (
            supabase
            .table("owner_profiles")
            .select(
                "plan,subscription_status,stripe_customer_id,"
                "stripe_subscription_id,trial_end"
            )
            .eq("user_id", str(user_id))
            .limit(1)
            .execute()
        )

        if not verified_profile.data:
            raise RuntimeError(
                "Stripe checkout succeeded, but RentFlow could not "
                "read the updated owner subscription from Supabase."
            )

        verified = verified_profile.data[0]

        if verified.get("plan") != payload["plan"]:
            raise RuntimeError(
                "Stripe checkout succeeded, but the RentFlow plan "
                "did not update in owner_profiles."
            )

        st.session_state["subscription_sync_success"] = True
        st.session_state["subscription_sync_plan"] = payload["plan"]
        st.session_state["subscription_sync_status"] = payload["subscription_status"]

        # Clear stale checkout links so the old checkout is not reused.
        st.session_state.pop("owner_subscription_checkout_url", None)
        st.session_state.pop("owner_subscription_target_plan", None)

        st.query_params.clear()
        st.rerun()

    except Exception as e:
        st.error(
            "Stripe processed the checkout, but RentFlow could not "
            "synchronize the subscription."
        )
        show_debug_exception(e)


def create_owner_billing_portal(customer_id):
    if not STRIPE_AVAILABLE:
        raise RuntimeError("Stripe package is not installed.")
    if not get_stripe_secret_key():
        raise RuntimeError("Stripe is not configured.")
    if not get_rentflow_app_url():
        raise RuntimeError("RENTFLOW_APP_URL is not configured.")

    stripe.api_key = get_stripe_secret_key()

    session = stripe.billing_portal.Session.create(
        customer=customer_id,
        return_url=get_rentflow_app_url(),
    )
    return session.url



# =========================================================
# P2B - STRIPE SUBSCRIPTION LIFECYCLE
# =========================================================

def stripe_price_to_plan(price_id):
    """Map a Stripe recurring Price ID back to a RentFlow plan."""
    if not price_id:
        return None

    price_map = {
        get_stripe_price_id("Starter"): "Starter",
        get_stripe_price_id("Professional"): "Professional",
        get_stripe_price_id("Portfolio"): "Portfolio",
    }

    return price_map.get(str(price_id))


def sync_owner_subscription_from_stripe(user_id):
    """
    Pull the latest subscription state directly from Stripe and persist it
    to owner_profiles. This provides an immediate safety net even before
    webhooks are deployed.
    """
    if not user_id:
        return None

    profile = get_owner_profile(user_id)
    subscription_id = profile.get("stripe_subscription_id")

    if not subscription_id:
        return profile

    if not STRIPE_AVAILABLE:
        raise RuntimeError("Stripe package is not installed.")

    secret_key = get_stripe_secret_key()
    if not secret_key:
        raise RuntimeError("STRIPE_SECRET_KEY is not configured.")

    stripe.api_key = secret_key

    subscription = stripe.Subscription.retrieve(
        subscription_id,
        expand=["items.data.price"]
    )

    status = getattr(subscription, "status", None) or "unknown"
    cancel_at_period_end = bool(
        getattr(subscription, "cancel_at_period_end", False)
    )

    current_period_end = getattr(
        subscription,
        "current_period_end",
        None
    )

    trial_end = getattr(
        subscription,
        "trial_end",
        None
    )

    plan_name = profile.get("plan") or "Starter"

    try:
        item = subscription["items"]["data"][0]
        price = item["price"]
        price_id = getattr(price, "id", None) or price["id"]
        mapped_plan = stripe_price_to_plan(price_id)
        if mapped_plan:
            plan_name = mapped_plan
    except Exception:
        pass

    update_payload = {
        "plan": plan_name,
        "subscription_status": status,
        "cancel_at_period_end": cancel_at_period_end,
    }

    if current_period_end:
        update_payload["current_period_end"] = pd.to_datetime(
            current_period_end,
            unit="s",
            utc=True
        ).isoformat()

    if trial_end:
        update_payload["trial_end"] = pd.to_datetime(
            trial_end,
            unit="s",
            utc=True
        ).isoformat()

    (
        supabase
        .table("owner_profiles")
        .update(update_payload)
        .eq("user_id", str(user_id))
        .execute()
    )

    return get_owner_profile(user_id)


def change_existing_subscription_plan(
    user_id,
    target_plan,
):
    """
    Upgrade/downgrade the EXISTING Stripe subscription instead of creating
    a second subscription. Stripe handles the proration.
    """
    profile = get_owner_profile(user_id)
    subscription_id = profile.get("stripe_subscription_id")

    if not subscription_id:
        raise RuntimeError(
            "No existing Stripe subscription was found for this account."
        )

    if not STRIPE_AVAILABLE:
        raise RuntimeError("Stripe package is not installed.")

    target_price = get_stripe_price_id(target_plan)

    if not target_price:
        raise RuntimeError(
            f"Stripe price is not configured for {target_plan}."
        )

    stripe.api_key = get_stripe_secret_key()

    subscription = stripe.Subscription.retrieve(
        subscription_id
    )

    items = subscription["items"]["data"]

    if not items:
        raise RuntimeError(
            "The Stripe subscription does not contain a subscription item."
        )

    subscription_item_id = items[0]["id"]

    updated = stripe.Subscription.modify(
        subscription_id,
        items=[
            {
                "id": subscription_item_id,
                "price": target_price,
            }
        ],
        proration_behavior="create_prorations",
        metadata={
            "user_id": str(user_id),
            "plan": target_plan,
        },
    )

    (
        supabase
        .table("owner_profiles")
        .update({
            "plan": target_plan,
            "subscription_status": getattr(
                updated,
                "status",
                "active"
            ),
        })
        .eq("user_id", str(user_id))
        .execute()
    )

    return updated



# =========================================================
# P3 - PRODUCTION BILLING & ACCESS ENFORCEMENT
# =========================================================

P3_PLAN_CONFIG = {
    "Starter": {
        "properties": 1,
        "units": 10,
        "tenants": 10,
        "ask_rentflow": False,
        "advanced_reports": False,
    },
    "Professional": {
        "properties": 10,
        "units": 100,
        "tenants": 100,
        "ask_rentflow": True,
        "advanced_reports": True,
    },
    "Portfolio": {
        "properties": 999999,
        "units": 999999,
        "tenants": 999999,
        "ask_rentflow": True,
        "advanced_reports": True,
    },
}

P3_ACCESS_STATUSES = {
    "active",
    "trialing",
    "past_due",  # grace access; billing warning is shown
}


def get_owner_entitlements(user_id):
    profile = get_owner_profile(user_id) if user_id else {}
    plan_name = profile.get("plan") or "Starter"
    status = str(
        profile.get("subscription_status")
        or "trialing"
    ).lower()

    if plan_name not in P3_PLAN_CONFIG:
        plan_name = "Starter"

    config = P3_PLAN_CONFIG[plan_name]

    return {
        "profile": profile,
        "plan": plan_name,
        "status": status,
        "access_allowed": status in P3_ACCESS_STATUSES,
        "ask_rentflow": (
            status in P3_ACCESS_STATUSES
            and config["ask_rentflow"]
        ),
        "advanced_reports": (
            status in P3_ACCESS_STATUSES
            and config["advanced_reports"]
        ),
        "limits": config,
    }


def p3_count_rows(table_name):
    try:
        result = (
            supabase
            .table(table_name)
            .select("*", count="exact")
            .limit(1)
            .execute()
        )
        return int(result.count or 0)
    except Exception:
        return 0


def p3_resource_limit_state(user_id, resource_name):
    entitlements = get_owner_entitlements(user_id)

    table_map = {
        "properties": "properties",
        "units": "units",
        "tenants": "tenants",
    }

    table_name = table_map[resource_name]
    current_count = p3_count_rows(table_name)
    limit_value = entitlements["limits"][resource_name]

    at_limit = (
        limit_value < 999999
        and current_count >= limit_value
    )

    return {
        "entitlements": entitlements,
        "current": current_count,
        "limit": limit_value,
        "at_limit": at_limit,
        "blocked": (
            not entitlements["access_allowed"]
            or at_limit
        ),
    }


def show_p3_subscription_notice(user_id):
    """Reusable billing-health message."""
    entitlements = get_owner_entitlements(user_id)
    profile = entitlements["profile"]
    status = entitlements["status"]

    if status == "past_due":
        st.warning(
            "⚠️ Your RentFlow subscription is past due. "
            "Core access remains available temporarily, but please update "
            "your payment method in Plans & Usage."
        )

    elif status in {"unpaid", "canceled", "incomplete_expired"}:
        st.error(
            "🔒 Your RentFlow subscription is not active. "
            "You can review your portfolio, but paid actions and premium "
            "features are restricted until billing is restored."
        )

    elif profile.get("cancel_at_period_end"):
        end_date = str(
            profile.get("current_period_end") or ""
        )[:10]
        st.warning(
            "Your subscription is scheduled to cancel"
            + (f" on {end_date}." if end_date else " at period end.")
        )


def list_owner_stripe_invoices(customer_id, limit=10):
    if not customer_id:
        return []

    if not STRIPE_AVAILABLE:
        raise RuntimeError("Stripe package is not installed.")

    stripe.api_key = get_stripe_secret_key()

    invoices = stripe.Invoice.list(
        customer=customer_id,
        limit=limit,
    )

    rows = []

    for invoice in invoices.data:
        rows.append({
            "Date": (
                pd.to_datetime(
                    invoice.created,
                    unit="s"
                ).strftime("%Y-%m-%d")
                if getattr(invoice, "created", None)
                else ""
            ),
            "Invoice": getattr(invoice, "number", None) or invoice.id,
            "Status": getattr(invoice, "status", None),
            "Amount": float(
                getattr(invoice, "amount_paid", 0) or 0
            ) / 100.0,
            "Currency": str(
                getattr(invoice, "currency", "usd")
            ).upper(),
            "Invoice URL": getattr(
                invoice,
                "hosted_invoice_url",
                None
            ),
        })

    return rows


def set_subscription_cancellation(
    user_id,
    cancel_at_period_end,
):
    profile = get_owner_profile(user_id)
    subscription_id = profile.get("stripe_subscription_id")

    if not subscription_id:
        raise RuntimeError(
            "No Stripe subscription is linked to this account."
        )

    stripe.api_key = get_stripe_secret_key()

    updated = stripe.Subscription.modify(
        subscription_id,
        cancel_at_period_end=bool(cancel_at_period_end),
    )

    (
        supabase
        .table("owner_profiles")
        .update({
            "cancel_at_period_end": bool(
                getattr(
                    updated,
                    "cancel_at_period_end",
                    cancel_at_period_end
                )
            ),
            "subscription_status": getattr(
                updated,
                "status",
                profile.get("subscription_status")
            ),
        })
        .eq("user_id", str(user_id))
        .execute()
    )

    return updated



def show_tenant_forgot_password_page():

    recovery_left, recovery_center, recovery_right = st.columns([1, 2, 1])
    with recovery_center:
        st.markdown("### 🔑 Reset Tenant Password")
        st.caption(
            "Enter the email you use for the RentFlow Tenant Portal."
        )

        with st.form(
            "tenant_forgot_password_form",
            clear_on_submit=False
        ):
            recovery_email = st.text_input(
                "Tenant Portal Email",
                key="tenant_forgot_password_email"
            )
            send_reset = st.form_submit_button(
                "Send Reset Link",
                type="primary",
                use_container_width=True
            )

        if send_reset:
            if not recovery_email.strip():
                st.error("Enter your email address.")
            else:
                try:
                    # Preserve the intended destination for the current browser.
                    st.session_state[
                        "password_recovery_origin"
                    ] = "tenant"

                    recovery_url = get_recovery_redirect_url("tenant")

                    if recovery_url:
                        supabase.auth.reset_password_for_email(
                            recovery_email.strip(),
                            {"redirect_to": recovery_url}
                        )
                    else:
                        supabase.auth.reset_password_for_email(
                            recovery_email.strip()
                        )

                except Exception:
                    # Keep the public response generic so RentFlow does not
                    # reveal whether a Tenant Portal account exists.
                    pass

                st.success(
                    "If a Tenant Portal account exists for that email, "
                    "password-reset instructions have been sent."
                )
                st.info(
                    "Open the RentFlow password-reset email, choose a new "
                    "password, then return to Tenant Portal Sign In."
                )

        if st.button(
            "← Back to Tenant Sign In",
            use_container_width=True,
            key="tenant_forgot_password_back"
        ):
            st.session_state.pop(
                "tenant_password_recovery_mode",
                None
            )
            st.rerun()

