# =========================================================
# ACCOUNT RECOVERY BROWSER BRIDGE
# =========================================================
# Supabase may return recovery credentials in the browser URL fragment.
# URL fragments are not visible to Streamlit's Python server. This tiny
# zero-height component converts ONLY recovery fragments into temporary
# query parameters so RentFlow can establish the recovery session.
# =========================================================
components.html(
    """
    <script>
    (function () {
        try {
            const parentUrl = new URL(window.parent.location.href);
            const hash = parentUrl.hash ? parentUrl.hash.substring(1) : "";
            if (!hash) return;

            const fragment = new URLSearchParams(hash);
            if (fragment.get("type") !== "recovery") return;

            const accessToken = fragment.get("access_token");
            const refreshToken = fragment.get("refresh_token");
            if (!accessToken || !refreshToken) return;

            parentUrl.hash = "";
            parentUrl.searchParams.set("rf_access_token", accessToken);
            parentUrl.searchParams.set("rf_refresh_token", refreshToken);
            parentUrl.searchParams.set("type", "recovery");

            window.parent.location.replace(parentUrl.toString());
        } catch (e) {
            // Server-side token_hash recovery remains available as fallback.
        }
    })();
    </script>
    """,
    height=0,
    width=0
)


# =========================================================
# ACCOUNT RECOVERY CALLBACK
# =========================================================
# Streamlit is server-rendered, so RentFlow uses a token_hash query
# parameter from a customized Supabase Reset Password email template.
# The token is exchanged for a recovery session server-side.
# =========================================================

recovery_token_hash = st.query_params.get("token_hash")
recovery_type = st.query_params.get("type")
recovery_access_token = st.query_params.get("rf_access_token")
recovery_refresh_token = st.query_params.get("rf_refresh_token")
recovery_origin = st.query_params.get("rf_recovery") or "owner"

if (
    recovery_type == "recovery"
    and recovery_access_token
    and recovery_refresh_token
    and not st.session_state.get("password_recovery_verified")
):
    try:
        session_obj = _auth_manager.establish_session(
            recovery_access_token,
            recovery_refresh_token,
        )

        if session_obj:
            st.session_state["password_recovery_verified"] = True
            st.session_state["password_recovery_origin"] = recovery_origin
            st.query_params.clear()
            st.rerun()
        else:
            st.error(
                "The password recovery link is invalid or has expired."
            )
            st.stop()

    except Exception as e:
        st.error(
            "The password recovery link is invalid or has expired."
        )
        show_debug_exception(e)
        st.stop()


if (
    recovery_token_hash
    and recovery_type == "recovery"
    and not st.session_state.get("password_recovery_verified")
):
    try:
        recovery_response = supabase.auth.verify_otp({
            "token_hash": recovery_token_hash,
            "type": "recovery",
        })

        if recovery_response.session:
            save_auth_session(recovery_response.session)
            st.session_state["password_recovery_verified"] = True
            st.session_state["password_recovery_origin"] = recovery_origin
            st.query_params.clear()
            st.rerun()
        else:
            st.error(
                "The password recovery link is invalid or has expired."
            )

    except Exception as e:
        st.error(
            "The password recovery link is invalid or has expired."
        )
        show_debug_exception(e)
        st.stop()



# =========================================================
# RC3 - OWNER SUBSCRIPTION RETURN SYNC (PRE-AUTH)
# =========================================================
# Stripe Checkout returns to a new Streamlit browser request. In hosted
# environments such as Codespaces, the prior Streamlit/Supabase session may
# not survive that external round-trip. Therefore, a verified Stripe Checkout
# success must be synchronized server-side BEFORE the authentication gate.
#
# Security:
# - The Checkout Session is retrieved directly from Stripe using the server
#   secret key.
# - The owner id and requested plan come only from Stripe metadata that
#   RentFlow placed on the Checkout Session when it was created.
# - The database write uses the server-only Supabase service-role client.
# - No plan change is accepted from browser query parameters alone.
# =========================================================

def sync_owner_subscription_return_pre_auth():
    state = st.query_params.get("owner_subscription")
    session_id = st.query_params.get("session_id")

    if state == "cancelled":
        st.session_state["owner_subscription_return_notice"] = (
            "Subscription checkout was cancelled."
        )
        st.query_params.clear()
        return False

    if state != "success" or not session_id:
        return False

    if not STRIPE_AVAILABLE:
        st.session_state["owner_subscription_return_error"] = (
            "Stripe is not available, so the subscription return could not be verified."
        )
        return False

    secret_key = get_stripe_secret_key()
    if not secret_key:
        st.session_state["owner_subscription_return_error"] = (
            "Stripe is not configured, so the subscription return could not be verified."
        )
        return False

    try:
        stripe.api_key = secret_key

        session = stripe.checkout.Session.retrieve(
            str(session_id),
            expand=["subscription"],
        )

        if str(getattr(session, "mode", "")) != "subscription":
            raise RuntimeError(
                "The Stripe Checkout Session is not a subscription checkout."
            )

        if str(getattr(session, "status", "")) != "complete":
            raise RuntimeError(
                "The Stripe Checkout Session is not complete."
            )

        metadata = _stripe_plain_dict(
            getattr(session, "metadata", None)
        )

        owner_id = str(metadata.get("user_id") or "").strip()
        requested_plan = str(metadata.get("plan") or "").strip()

        if not owner_id:
            raise RuntimeError(
                "The verified Stripe Checkout Session is missing the RentFlow owner id."
            )

        if requested_plan not in {"Starter", "Professional", "Portfolio"}:
            raise RuntimeError(
                "The verified Stripe Checkout Session contains an invalid RentFlow plan."
            )

        subscription = getattr(session, "subscription", None)
        if isinstance(subscription, str):
            subscription = stripe.Subscription.retrieve(
                subscription,
                expand=["items.data.price"],
            )

        if not subscription:
            raise RuntimeError(
                "Stripe Checkout completed but no subscription was returned."
            )

        subscription_id = str(getattr(subscription, "id", "") or "").strip()
        customer_id = str(getattr(session, "customer", "") or "").strip()
        subscription_status = str(
            getattr(subscription, "status", "active") or "active"
        )

        # Prefer the actual Stripe price on the subscription over metadata.
        # This prevents RentFlow from storing a plan that does not match what
        # Stripe is actually billing.
        actual_plan = requested_plan
        try:
            item = subscription["items"]["data"][0]
            price = item["price"]
            price_id = getattr(price, "id", None) or price["id"]
            mapped_plan = stripe_price_to_plan(price_id)
            if mapped_plan:
                actual_plan = mapped_plan
        except Exception:
            pass

        payload = {
            "plan": actual_plan,
            "subscription_status": subscription_status,
            "stripe_customer_id": customer_id or None,
            "stripe_subscription_id": subscription_id or None,
            "cancel_at_period_end": bool(
                getattr(subscription, "cancel_at_period_end", False)
            ),
        }

        current_period_end = getattr(
            subscription,
            "current_period_end",
            None,
        )
        if current_period_end:
            payload["current_period_end"] = pd.to_datetime(
                current_period_end,
                unit="s",
                utc=True,
            ).isoformat()

        trial_end = getattr(subscription, "trial_end", None)
        if trial_end:
            payload["trial_end"] = pd.to_datetime(
                trial_end,
                unit="s",
                utc=True,
            ).isoformat()

        server_supabase = get_supabase_server_client()

        existing = (
            server_supabase
            .table("owner_profiles")
            .select("user_id")
            .eq("user_id", owner_id)
            .limit(1)
            .execute()
        )

        if existing.data:
            (
                server_supabase
                .table("owner_profiles")
                .update(payload)
                .eq("user_id", owner_id)
                .execute()
            )
        else:
            server_supabase.table("owner_profiles").insert({
                "user_id": owner_id,
                **payload,
            }).execute()

        verified = (
            server_supabase
            .table("owner_profiles")
            .select(
                "plan,subscription_status,stripe_customer_id,"
                "stripe_subscription_id,cancel_at_period_end,current_period_end"
            )
            .eq("user_id", owner_id)
            .limit(1)
            .execute()
        )

        if not verified.data:
            raise RuntimeError(
                "The Stripe subscription was verified but RentFlow could not "
                "read the updated owner profile."
            )

        row = verified.data[0]
        if str(row.get("stripe_subscription_id") or "") != subscription_id:
            raise RuntimeError(
                "RentFlow did not persist the verified Stripe subscription id."
            )

        if str(row.get("plan") or "") != actual_plan:
            raise RuntimeError(
                "RentFlow did not persist the verified Stripe plan."
            )

        st.session_state["owner_subscription_return_success"] = True
        st.session_state["owner_subscription_return_plan"] = actual_plan
        st.session_state["owner_subscription_return_status"] = subscription_status

        # The successful return has now been verified and persisted. Clear the
        # one-time Checkout parameters so refreshes cannot re-run the callback.
        st.query_params.clear()
        return True

    except Exception as e:
        safe_message = str(e)
        for secret_name in (
            "STRIPE_SECRET_KEY",
            "SUPABASE_SERVICE_ROLE_KEY",
            "SUPABASE_SECRET_KEY",
            "SUPABASE_KEY",
        ):
            try:
                secret_value = str(rentflow_secret_get(secret_name) or "")
                if secret_value:
                    safe_message = safe_message.replace(
                        secret_value,
                        "[REDACTED]",
                    )
            except Exception:
                pass

        st.session_state["owner_subscription_return_error"] = (
            f"{type(e).__name__}: {safe_message}"
        )
        return False


# Run the verified Stripe return sync before the authentication gate.
