# =========================================================
# UNIFIED RENTFLOW AI - EMBEDDED ASK RENTFLOW
# =========================================================
def render_ask_rentflow_dashboard():

    p3_ai_access = get_owner_entitlements(
        auth_user.id
    )

    if not p3_ai_access["ask_rentflow"]:
        st.subheader("💬 Ask RentFlow")
        st.warning(
            "Ask RentFlow is available on Professional and Portfolio plans "
            "with an active subscription."
        )
        st.info(
            "Go to **Plan & Admin** to upgrade or restore billing access."
        )
        return

    # =========================================================
    # ASK RENTFLOW - OWNER ASSISTANT
    # =========================================================
    st.subheader("💬 Ask RentFlow")
    st.caption(
        "Ask questions about your portfolio using live information "
        "from RentFlow."
    )

    # Load live portfolio data for the embedded Ask RentFlow assistant.
    today = date.today()
    current_month = date(today.year, today.month, 1)
    next_month = (
        date(today.year + 1, 1, 1)
        if today.month == 12
        else date(today.year, today.month + 1, 1)
    )

    def _safe_float(value):
        try:
            return float(value or 0)
        except (TypeError, ValueError):
            return 0.0

    def _money(value):
        return f"${_safe_float(value):,.2f}"

    try:
        properties_data = (
            supabase.table("properties")
            .select("property_id,property_name")
            .execute().data or []
        )
        units_data = (
            supabase.table("units")
            .select(
                "unit_id,unit_number,monthly_rent,status,property_id"
            )
            .execute().data or []
        )
        tenants_data = (
            supabase.table("tenants")
            .select(
                "tenant_id,tenant_name,unit_id,lease_end,status"
            )
            .execute().data or []
        )
        rent_data = (
            supabase.table("rent_charges")
            .select(
                "tenant_id,unit_id,rent_month,due_date,amount_due"
            )
            .gte("rent_month", current_month.isoformat())
            .lt("rent_month", next_month.isoformat())
            .execute().data or []
        )
        payments_data = (
            supabase.table("payments")
            .select(
                "tenant_id,unit_id,rent_month,amount_paid"
            )
            .gte("rent_month", current_month.isoformat())
            .lt("rent_month", next_month.isoformat())
            .execute().data or []
        )
        expense_data = (
            supabase.table("expenses")
            .select("expense_date,category,amount,property_id,unit_id")
            .gte("expense_date", current_month.isoformat())
            .lt("expense_date", next_month.isoformat())
            .execute().data or []
        )
        maintenance_data = (
            supabase.table("maintenance_requests")
            .select(
                "request_id,request_date,tenant_id,property_id,unit_id,"
                "category,description,priority,status"
            )
            .execute().data or []
        )
    except Exception as e:
        st.error("Unable to load portfolio information for Ask RentFlow.")
        show_debug_exception(e)
        st.stop()

    properties_lookup = {
        p.get("property_id"): p.get("property_name", "Unknown")
        for p in properties_data
    }
    units_lookup = {
        u.get("unit_id"): u
        for u in units_data
    }
    tenants_lookup = {
        t.get("tenant_id"): t
        for t in tenants_data
    }

    # Rent/payment summary
    payment_lookup = {}
    for row in payments_data:
        key = (row.get("tenant_id"), row.get("unit_id"))
        payment_lookup[key] = (
            payment_lookup.get(key, 0.0)
            + _safe_float(row.get("amount_paid"))
        )

    attention_rows = []
    total_due = 0.0
    total_paid = 0.0
    total_outstanding = 0.0
    overdue_count = 0
    overdue_amount = 0.0
    partial_count = 0
    partial_amount = 0.0

    for row in rent_data:
        due = _safe_float(row.get("amount_due"))
        key = (row.get("tenant_id"), row.get("unit_id"))
        paid = payment_lookup.get(key, 0.0)
        balance = max(due - paid, 0.0)

        total_due += due
        total_paid += paid
        total_outstanding += balance

        due_date = row.get("due_date")
        overdue = False
        if balance > 0 and due_date:
            try:
                overdue = pd.to_datetime(due_date).date() < today
            except Exception:
                overdue = False

        status = "PAID" if balance <= 0 else (
            "OVERDUE" if overdue else "PARTIAL" if paid > 0 else "CURRENT"
        )

        tenant = tenants_lookup.get(row.get("tenant_id"), {})
        unit = units_lookup.get(row.get("unit_id"), {})

        if balance > 0:
            attention_rows.append({
                "Tenant": tenant.get("tenant_name", "Unknown"),
                "Property": properties_lookup.get(
                    unit.get("property_id"), "Unknown"
                ),
                "Unit": unit.get("unit_number", ""),
                "Balance": balance,
                "Status": status
            })

        if overdue:
            overdue_count += 1
            overdue_amount += balance
        elif paid > 0 and balance > 0:
            partial_count += 1
            partial_amount += balance

    vacant_rows = []
    vacant_rent = 0.0
    for unit in units_data:
        if str(unit.get("status", "")).lower() == "vacant":
            rent = _safe_float(unit.get("monthly_rent"))
            vacant_rent += rent
            vacant_rows.append({
                "Property": properties_lookup.get(
                    unit.get("property_id"), "Unknown"
                ),
                "Unit": unit.get("unit_number", ""),
                "Monthly Rent": rent
            })

    vacant_units = len(vacant_rows)

    # Expense summary
    total_expenses = sum(
        _safe_float(row.get("amount"))
        for row in expense_data
    )

    expense_by_category = {}
    for row in expense_data:
        category = row.get("category") or "Other"
        expense_by_category[category] = (
            expense_by_category.get(category, 0.0)
            + _safe_float(row.get("amount"))
        )

    # Basic 5C-style property performance for the assistant.
    ranking_rows = []
    for prop in properties_data:
        pid = prop.get("property_id")
        prop_units = [
            u for u in units_data if u.get("property_id") == pid
        ]
        prop_unit_ids = {u.get("unit_id") for u in prop_units}

        occupied = sum(
            1 for u in prop_units
            if str(u.get("status", "")).lower() == "occupied"
        )
        occupancy = (
            occupied / len(prop_units) * 100
            if prop_units else 0
        )

        prop_due = sum(
            _safe_float(r.get("amount_due"))
            for r in rent_data
            if r.get("unit_id") in prop_unit_ids
        )
        prop_paid = sum(
            payment_lookup.get(
                (r.get("tenant_id"), r.get("unit_id")), 0.0
            )
            for r in rent_data
            if r.get("unit_id") in prop_unit_ids
        )
        collection = (
            prop_paid / prop_due * 100
            if prop_due > 0 else 100
        )

        prop_expenses = sum(
            _safe_float(e.get("amount"))
            for e in expense_data
            if e.get("property_id") == pid
        )
        net_income = prop_paid - prop_expenses
        noi_margin = (
            net_income / prop_paid * 100
            if prop_paid > 0 else 0
        )
        outstanding = max(prop_due - prop_paid, 0)

        # Same management-score concept as 5C.
        occupancy_score = min(max(occupancy, 0), 100)
        collection_score = min(max(collection, 0), 100)
        noi_score = min(max(noi_margin, 0), 100)
        outstanding_score = (
            max(0, 100 - (outstanding / prop_due * 100))
            if prop_due > 0 else 100
        )

        score = (
            occupancy_score * 0.30
            + collection_score * 0.30
            + noi_score * 0.25
            + outstanding_score * 0.15
        )

        ranking_rows.append({
            "Property": prop.get("property_name", "Unknown"),
            "Score": score,
            "Occupancy": occupancy,
            "Collection": collection,
            "NOI Margin": noi_margin,
            "Outstanding": outstanding,
            "Net Income": net_income
        })

    ranking_df = pd.DataFrame(ranking_rows)
    if not ranking_df.empty:
        ranking_df = ranking_df.sort_values(
            "Score", ascending=False
        ).reset_index(drop=True)

    high_risk_count = sum(
        1 for row in attention_rows
        if row["Status"] == "OVERDUE"
        and row["Balance"] > 0
    )

    high_expense_count = 0
    if expense_by_category:
        average_expense = (
            total_expenses / len(expense_by_category)
        )
        high_expense_count = sum(
            1 for value in expense_by_category.values()
            if value > average_expense * 1.5
        )

    collection_rate = (
        total_paid / total_due * 100
        if total_due > 0 else 100
    )

    # ---------------------------------------------------------
    # Focused owner intelligence
    # ---------------------------------------------------------

    # Urgent / unresolved maintenance.
    urgent_maintenance_rows = []
    for row in maintenance_data:
        status_value = str(row.get("status") or "").strip().lower()
        priority_value = str(row.get("priority") or "").strip().lower()

        if (
            status_value in ("open", "in progress")
            and priority_value == "urgent"
        ):
            unit = units_lookup.get(row.get("unit_id"), {})
            tenant = tenants_lookup.get(row.get("tenant_id"), {})
            urgent_maintenance_rows.append({
                "Request Date": row.get("request_date"),
                "Tenant": tenant.get("tenant_name", "Unknown"),
                "Property": properties_lookup.get(
                    row.get("property_id")
                    or unit.get("property_id"),
                    "Unknown"
                ),
                "Unit": unit.get("unit_number", ""),
                "Category": row.get("category") or "Maintenance",
                "Description": row.get("description") or "",
                "Status": row.get("status") or "Open",
            })

    # Leases approaching expiration. Include already-expired active leases
    # separately so the owner can see anything that needs immediate follow-up.
    expiring_lease_rows = []
    expired_lease_rows = []

    for tenant in tenants_data:
        lease_end_value = tenant.get("lease_end")
        if not lease_end_value:
            continue

        try:
            lease_end_date = pd.to_datetime(lease_end_value).date()
        except Exception:
            continue

        unit = units_lookup.get(tenant.get("unit_id"), {})
        days_remaining = (lease_end_date - today).days

        lease_row = {
            "Tenant": tenant.get("tenant_name", "Unknown"),
            "Property": properties_lookup.get(
                unit.get("property_id"), "Unknown"
            ),
            "Unit": unit.get("unit_number", ""),
            "Lease End": lease_end_date,
            "Days": days_remaining,
        }

        if days_remaining < 0:
            expired_lease_rows.append(lease_row)
        elif days_remaining <= 60:
            expiring_lease_rows.append(lease_row)

    expiring_lease_rows = sorted(
        expiring_lease_rows,
        key=lambda x: x["Days"]
    )
    expired_lease_rows = sorted(
        expired_lease_rows,
        key=lambda x: x["Days"]
    )

    # Tenant risk: transparent owner-facing prioritization based on
    # current rent status/balance plus near-term lease timing.
    tenant_risk_rows = []

    for tenant in tenants_data:
        tenant_id = tenant.get("tenant_id")
        tenant_name = tenant.get("tenant_name", "Unknown")
        unit = units_lookup.get(tenant.get("unit_id"), {})

        tenant_attention = [
            row for row in attention_rows
            if row.get("Tenant") == tenant_name
            and row.get("Unit") == unit.get("unit_number", "")
        ]

        balance = sum(
            _safe_float(row.get("Balance"))
            for row in tenant_attention
        )

        has_overdue = any(
            row.get("Status") == "OVERDUE"
            for row in tenant_attention
        )
        has_partial = any(
            row.get("Status") == "PARTIAL"
            for row in tenant_attention
        )

        risk_score = 0
        reasons = []

        if has_overdue:
            risk_score += 60
            reasons.append("overdue rent")
        elif has_partial:
            risk_score += 30
            reasons.append("partial payment")

        if balance > 0:
            # Up to 25 additional points based on unpaid balance.
            risk_score += min(25, balance / 100)
            reasons.append(f"{_money(balance)} outstanding")

        lease_end_value = tenant.get("lease_end")
        if lease_end_value:
            try:
                lease_end_date = pd.to_datetime(lease_end_value).date()
                days_remaining = (lease_end_date - today).days

                if days_remaining < 0:
                    risk_score += 15
                    reasons.append("lease expired")
                elif days_remaining <= 30:
                    risk_score += 10
                    reasons.append(
                        f"lease expires in {days_remaining} days"
                    )
                elif days_remaining <= 60:
                    risk_score += 5
                    reasons.append(
                        f"lease expires in {days_remaining} days"
                    )
            except Exception:
                pass

        if risk_score > 0:
            tenant_risk_rows.append({
                "Tenant": tenant_name,
                "Property": properties_lookup.get(
                    unit.get("property_id"), "Unknown"
                ),
                "Unit": unit.get("unit_number", ""),
                "Risk Score": min(round(risk_score, 1), 100),
                "Outstanding": balance,
                "Reasons": reasons,
            })

    tenant_risk_rows = sorted(
        tenant_risk_rows,
        key=lambda x: (
            x["Risk Score"],
            x["Outstanding"]
        ),
        reverse=True
    )

    # ---------------------------------------------------------
    # Ask interface
    # ---------------------------------------------------------
    suggested_questions = [
        "What needs my attention today?",
        "Which maintenance requests are urgent?",
        "Which leases are expiring soon?",
        "Which properties are performing worst?",
        "Which tenants are highest risk?",
        "Who owes me rent?",
        "Which units are vacant?",
        "Where are my expenses high?",
        "What is my cash flow outlook?"
    ]

    question = st.selectbox(
        "Ask a question",
        suggested_questions,
        key="rentflow_ai_question_page"
    )

    custom_question = st.text_input(
        "Or type your own question",
        placeholder="Example: Which property should I focus on?",
        key="rentflow_ai_custom_question_page"
    )

    active_question = (
        custom_question.strip()
        if custom_question.strip()
        else question
    )

    def _ai_answer(user_question):
        q = " ".join(str(user_question or "").lower().strip().split())

        # -----------------------------------------------------
        # Focused Ask RentFlow routes
        # Keep these BEFORE the broad "attention" route so the
        # selected suggested questions always receive their own answer.
        # -----------------------------------------------------

        maintenance_question = (
            q == "which maintenance requests are urgent?"
            or (
                "maintenance" in q
                and any(term in q for term in [
                    "urgent", "priority", "need attention",
                    "needs attention", "open"
                ])
            )
        )

        lease_question = (
            q == "which leases are expiring soon?"
            or (
                "lease" in q
                and any(term in q for term in [
                    "expir", "ending", "renewal", "renew",
                    "soon", "next 30", "next 60"
                ])
            )
        )

        worst_property_question = (
            q == "which properties are performing worst?"
            or (
                any(term in q for term in ["property", "properties"])
                and any(term in q for term in [
                    "worst", "least performing", "lowest performing",
                    "underperform", "needs the most attention",
                    "need the most attention"
                ])
            )
        )

        tenant_risk_question = (
            q == "which tenants are highest risk?"
            or (
                "tenant" in q
                and any(term in q for term in [
                    "risk", "risky", "highest risk", "most risky",
                    "need attention", "needs attention"
                ])
            )
        )

        if maintenance_question:
            if urgent_maintenance_rows:
                lines = [
                    "### 🔧 Urgent Maintenance",
                    "",
                    f"**{len(urgent_maintenance_rows)} urgent open request(s)** "
                    "need owner attention.",
                    ""
                ]

                for row in urgent_maintenance_rows[:10]:
                    location = (
                        f"{row['Property']} / Unit {row['Unit']}"
                        if row["Unit"]
                        else row["Property"]
                    )
                    description = (
                        f" — {row['Description']}"
                        if row["Description"]
                        else ""
                    )
                    lines.append(
                        f"- **{row['Category']}** — {location} — "
                        f"{row['Tenant']}{description}"
                    )

                lines.append(
                    "\n**Recommendation:** Handle urgent requests first, "
                    "especially safety, water, electrical, heating/cooling, "
                    "or habitability issues."
                )
                return "\n".join(lines)

            # Still return a useful answer when nothing is marked urgent.
            open_rows = [
                row for row in maintenance_data
                if str(row.get("status") or "").strip().lower()
                in ("open", "in progress")
            ]
            if open_rows:
                return (
                    "### ✅ No maintenance is currently marked urgent\n\n"
                    f"There are **{len(open_rows)} open/in-progress maintenance "
                    "request(s)**, but none are currently marked urgent.\n\n"
                    "**Recommendation:** Review the open requests and raise the "
                    "priority of any safety or habitability issue."
                )

            return (
                "### ✅ No urgent maintenance\n\n"
                "There are no open maintenance requests currently marked urgent."
            )

        if lease_question:
            if expired_lease_rows or expiring_lease_rows:
                lines = ["### 📅 Lease Follow-Up", ""]

                if expired_lease_rows:
                    lines.append(
                        f"**{len(expired_lease_rows)} lease(s) appear expired:**"
                    )
                    for row in expired_lease_rows[:10]:
                        unit_text = (
                            f" / Unit {row['Unit']}"
                            if row["Unit"] else ""
                        )
                        lines.append(
                            f"- **{row['Tenant']}** — {row['Property']}"
                            f"{unit_text} — ended "
                            f"**{row['Lease End'].strftime('%b %d, %Y')}**"
                        )
                    lines.append("")

                if expiring_lease_rows:
                    lines.append(
                        f"**{len(expiring_lease_rows)} lease(s) expire within 60 days:**"
                    )
                    for row in expiring_lease_rows[:10]:
                        unit_text = (
                            f" / Unit {row['Unit']}"
                            if row["Unit"] else ""
                        )
                        lines.append(
                            f"- **{row['Tenant']}** — {row['Property']}"
                            f"{unit_text} — **{row['Days']} days** "
                            f"({row['Lease End'].strftime('%b %d, %Y')})"
                        )

                lines.append(
                    "\n**Recommendation:** Start with expired leases, then "
                    "contact the nearest-expiring tenants about renewal."
                )
                return "\n".join(lines)

            return (
                "### ✅ No near-term lease expirations\n\n"
                "I don't see expired leases or leases ending within the next 60 days."
            )

        if worst_property_question:
            if not ranking_df.empty:
                worst_rows = ranking_df.sort_values(
                    "Score", ascending=True
                ).head(5)

                lines = [
                    "### 📉 Lowest-Performing Properties",
                    "",
                    "Ranked using occupancy, rent collection, NOI margin, "
                    "and outstanding rent:",
                    ""
                ]

                for _, row in worst_rows.iterrows():
                    lines.append(
                        f"- **{row['Property']}** — Score "
                        f"**{float(row['Score']):.1f}/100** | "
                        f"Occupancy {float(row['Occupancy']):.1f}% | "
                        f"Collection {float(row['Collection']):.1f}% | "
                        f"NOI margin {float(row['NOI Margin']):.1f}% | "
                        f"Outstanding {_money(row['Outstanding'])}"
                    )

                lines.append(
                    "\n**Recommendation:** Review the lowest-scoring property "
                    "first and determine whether vacancy, collections, or expenses "
                    "are driving the weakness."
                )
                return "\n".join(lines)

            return (
                "### 📉 Property Performance\n\n"
                "There isn't enough property-performance data yet to rank "
                "the portfolio."
            )

        if tenant_risk_question:
            if tenant_risk_rows:
                lines = [
                    "### ⚠️ Highest-Risk Tenants",
                    "",
                    "Prioritized using current rent status, outstanding balance, "
                    "and lease timing:",
                    ""
                ]

                for row in tenant_risk_rows[:10]:
                    reason_text = ", ".join(row["Reasons"])
                    unit_text = (
                        f" / Unit {row['Unit']}"
                        if row["Unit"] else ""
                    )
                    lines.append(
                        f"- **{row['Tenant']}** — {row['Property']}"
                        f"{unit_text} — Risk **{row['Risk Score']:.1f}/100**"
                        f" — {reason_text}"
                    )

                lines.append(
                    "\n**Recommendation:** Start with tenants combining overdue "
                    "rent with an expired or near-term lease."
                )
                return "\n".join(lines)

            return (
                "### ✅ No elevated tenant risk\n\n"
                "I don't currently see tenants with overdue/partial rent or "
                "near-term lease risk."
            )

        # Broad portfolio-attention question comes after focused routes.
        if any(word in q for word in [
            "attention", "today", "urgent", "problem", "issue",
            "follow up", "follow-up", "action"
        ]):
            items = []

            if overdue_count > 0:
                items.append(
                    f"🔴 **Overdue rent:** {overdue_count} tenant(s) with "
                    f"{_money(overdue_amount)} outstanding."
                )

            if partial_count > 0:
                items.append(
                    f"🟠 **Partial payments:** {partial_count} tenant(s) with "
                    f"{_money(partial_amount)} still outstanding."
                )

            if vacant_units > 0:
                items.append(
                    f"🟠 **Vacancies:** {vacant_units} vacant unit(s), "
                    f"representing {_money(vacant_rent)} in monthly rent at risk."
                )

            if high_risk_count > 0:
                items.append(
                    f"🔴 **Tenant risk:** {high_risk_count} overdue tenant(s) "
                    "should be reviewed."
                )

            if high_expense_count > 0:
                items.append(
                    f"🟡 **Expenses:** {high_expense_count} expense "
                    "category area(s) are elevated."
                )

            if not items:
                return (
                    "### 🎉 Portfolio looks healthy\n\n"
                    "I don't see any major attention items based on "
                    "the current portfolio data."
                )

            return (
                "### 🎯 Recommended Focus\n\n"
                + "\n\n".join(items)
                + "\n\n**Recommendation:** Start with the highest-dollar "
                "overdue balance, then review vacancies and elevated expenses."
            )

        if any(word in q for word in [
            "best property", "top property", "best performing",
            "performing best", "strongest property"
        ]):
            if not ranking_df.empty:
                top = ranking_df.iloc[0]
                return (
                    "### 🏆 Best Performing Property\n\n"
                    f"**{top['Property']}** has the highest management score "
                    f"at **{float(top['Score']):.1f}/100**.\n\n"
                    f"- Occupancy: **{float(top['Occupancy']):.1f}%**\n"
                    f"- Collection: **{float(top['Collection']):.1f}%**\n"
                    f"- NOI Margin: **{float(top['NOI Margin']):.1f}%**\n"
                    f"- Outstanding: **{_money(top['Outstanding'])}**\n"
                    f"- Net Income: **{_money(top['Net Income'])}**"
                )
            return "I don't have enough property performance data yet."

        if any(word in q for word in [
            "who owes", "owe me", "owes rent", "outstanding rent",
            "rent owed", "rent balance", "late rent"
        ]):
            if attention_rows:
                rows = sorted(
                    attention_rows,
                    key=lambda x: _safe_float(x.get("Balance")),
                    reverse=True
                )[:10]

                lines = [
                    "### 💰 Rent Outstanding",
                    "",
                    f"Total currently identified: **{_money(total_outstanding)}**",
                    ""
                ]

                for row in rows:
                    lines.append(
                        f"- **{row['Tenant']}** — {row['Property']} / "
                        f"Unit {row['Unit']}: **{_money(row['Balance'])}** "
                        f"({row['Status']})"
                    )

                return "\n".join(lines)

            return (
                "### 🎉 No outstanding rent\n\n"
                "I don't see outstanding rent for the current month."
            )

        if any(word in q for word in [
            "vacant", "vacancy", "empty unit", "empty units",
            "available unit", "available units"
        ]):
            if vacant_rows:
                vacant_rows_sorted = sorted(
                    vacant_rows,
                    key=lambda x: _safe_float(x["Monthly Rent"]),
                    reverse=True
                )

                lines = [
                    "### 🏠 Vacant Units",
                    "",
                    f"**{vacant_units}** vacant unit(s) represent "
                    f"**{_money(vacant_rent)} per month** in rent at risk.",
                    ""
                ]

                for row in vacant_rows_sorted[:10]:
                    lines.append(
                        f"- **{row['Property']} / Unit {row['Unit']}** — "
                        f"{_money(row['Monthly Rent'])}/month"
                    )

                return "\n".join(lines)

            return (
                "### 🎉 No vacancies\n\n"
                "All units are currently marked occupied."
            )

        if any(word in q for word in [
            "expense", "expenses", "spending", "spend", "cost", "costs",
            "high expense", "where are expenses"
        ]):
            if expense_by_category:
                top_category = max(
                    expense_by_category,
                    key=expense_by_category.get
                )
                return (
                    "### 💸 Expense Review\n\n"
                    f"The largest current-month expense category is "
                    f"**{top_category}** at "
                    f"**{_money(expense_by_category[top_category])}**.\n\n"
                    f"Total current-month expenses are "
                    f"**{_money(total_expenses)}**.\n\n"
                    "**Recommendation:** Review the largest category first "
                    "and compare it with prior months."
                )

            return "### 💸 Expenses\n\nNo current-month expenses were found."

        if any(word in q for word in [
            "cash flow", "forecast", "outlook", "future", "next three",
            "next 3", "projected noi", "projection"
        ]):
            current_noi = total_paid - total_expenses
            return (
                "### 🔮 Cash Flow Outlook\n\n"
                f"Current-month collections: **{_money(total_paid)}**\n\n"
                f"Current-month expenses: **{_money(total_expenses)}**\n\n"
                f"Current-month NOI: **{_money(current_noi)}**\n\n"
                f"Current collection rate: **{collection_rate:.1f}%**.\n\n"
                "A detailed 3-month forecast is available on the Dashboard."
            )

        if "property" in q or "portfolio" in q:
            return (
                "### 🏢 Portfolio Snapshot\n\n"
                f"- Properties: **{len(properties_data)}**\n"
                f"- Units: **{len(units_data)}**\n"
                f"- Occupied: **{len(units_data) - vacant_units}**\n"
                f"- Vacant: **{vacant_units}**\n"
                f"- Rent collected: **{_money(total_paid)}**\n"
                f"- Outstanding: **{_money(total_outstanding)}**\n"
                f"- Expenses: **{_money(total_expenses)}**\n"
                f"- Current NOI: **{_money(total_paid - total_expenses)}**"
            )

        return (
            "### 🤖 I can help with your portfolio\n\n"
            "Try asking:\n"
            "- Which maintenance requests are urgent?\n"
            "- Which leases are expiring soon?\n"
            "- Which properties are performing worst?\n"
            "- Which tenants are highest risk?\n"
            "- Who owes me rent?\n"
            "- What needs my attention today?"
        )

    if st.button(
        "🤖 Ask RentFlow",
        type="primary",
        key="ask_rentflow_page"
    ):
        with st.container(border=True):
            st.markdown(_ai_answer(active_question))

    # Keep Ask RentFlow focused on questions and answers.
    # Portfolio summary metrics already live on the Dashboard Performance.


