# P4C - ACTIVITY & AUDIT LOG
# =========================================================
def log_owner_activity(
    action_type,
    description,
    entity_type=None,
    entity_id=None,
    metadata=None,
):
    try:
        actor_id = getattr(auth_user, "id", None)
        if not actor_id and isinstance(auth_user, dict):
            actor_id = auth_user.get("id")

        actor_email = getattr(auth_user, "email", None)
        if not actor_email and isinstance(auth_user, dict):
            actor_email = auth_user.get("email")

        supabase.table("activity_log").insert({
            "owner_id": str(actor_id) if actor_id else None,
            "actor_user_id": str(actor_id) if actor_id else None,
            "actor_email": actor_email,
            "action_type": action_type,
            "description": description,
            "entity_type": entity_type,
            "entity_id": str(entity_id) if entity_id is not None else None,
            "metadata": metadata or {},
        }).execute()
    except Exception:
        pass



# =========================================================
# P5B - DOCUMENT INTEGRATION HELPERS
# =========================================================
def get_linked_documents(
    tenant_id=None,
    unit_id=None,
    property_id=None,
    document_type=None,
):
    try:
        query = (
            supabase
            .table("documents")
            .select(
                "document_id,document_name,document_type,"
                "property_id,unit_id,tenant_id,storage_path,"
                "mime_type,file_size,document_date,expiration_date,"
                "notes,created_at"
            )
        )

        if tenant_id is not None:
            query = query.eq("tenant_id", str(tenant_id))

        if unit_id is not None:
            query = query.eq("unit_id", str(unit_id))

        if property_id is not None:
            query = query.eq("property_id", str(property_id))

        if document_type is not None:
            query = query.eq("document_type", document_type)

        return (
            query
            .order("created_at", desc=True)
            .execute()
            .data
            or []
        )

    except Exception:
        return []


def render_linked_document_downloads(
    document_rows,
    key_prefix,
    empty_message="No linked documents are available.",
):
    if not document_rows:
        st.info(empty_message)
        return

    for row in document_rows:
        with st.container(border=True):
            col1, col2, col3 = st.columns([2, 1, 1])

            with col1:
                st.markdown(
                    f"**📄 {row.get('document_name') or 'Document'}**"
                )
                st.caption(
                    f"{row.get('document_type') or 'Other'}"
                )

            with col2:
                st.write("**Document Date**")
                st.write(
                    row.get("document_date")
                    or "—"
                )

            with col3:
                st.write("**Expiration**")
                st.write(
                    row.get("expiration_date")
                    or "—"
                )

            if row.get("notes"):
                st.caption(
                    f"Notes: {row.get('notes')}"
                )

            try:
                document_bytes = (
                    supabase
                    .storage
                    .from_("rentflow-documents")
                    .download(
                        row["storage_path"]
                    )
                )

                st.download_button(
                    "⬇️ Download",
                    data=document_bytes,
                    file_name=(
                        row.get("document_name")
                        or "rentflow_document"
                    ),
                    mime=(
                        row.get("mime_type")
                        or "application/octet-stream"
                    ),
                    use_container_width=True,
                    key=(
                        f"{key_prefix}_"
                        f"{row.get('document_id')}"
                    )
                )

            except Exception as e:
                st.warning(
                    "Unable to download this document."
                )
                show_debug_exception(e)


def upload_tenant_lease_document(
    uploaded_file,
    tenant_record,
    unit_record,
    notes=None,
):
    size_ok, size_message = validate_upload_size(uploaded_file, max_mb=10)
    if not size_ok:
        raise ValueError(size_message)
    import uuid
    import re

    owner_id = getattr(
        auth_user,
        "id",
        None
    )

    if not owner_id:
        raise RuntimeError(
            "Owner account is not available."
        )

    safe_filename = re.sub(
        r"[^A-Za-z0-9._-]",
        "_",
        uploaded_file.name
    )

    storage_path = (
        f"{owner_id}/"
        f"{uuid.uuid4().hex}_"
        f"{safe_filename}"
    )

    file_bytes = uploaded_file.getvalue()

    mime_type = (
        uploaded_file.type
        or "application/octet-stream"
    )

    (
        supabase
        .storage
        .from_("rentflow-documents")
        .upload(
            storage_path,
            file_bytes,
            {
                "content-type": mime_type,
                "upsert": "false",
            }
        )
    )

    unit_id = tenant_record.get("unit_id")

    property_id = (
        unit_record.get("property_id")
        if unit_record
        else None
    )

    insert_result = (
        supabase
        .table("documents")
        .insert({
            "owner_id": str(owner_id),
            "document_name": uploaded_file.name,
            "document_type": "Lease",
            "property_id": (
                str(property_id)
                if property_id is not None
                else None
            ),
            "unit_id": (
                str(unit_id)
                if unit_id is not None
                else None
            ),
            "tenant_id": (
                str(
                    tenant_record.get(
                        "tenant_id"
                    )
                )
                if tenant_record.get(
                    "tenant_id"
                ) is not None
                else None
            ),
            "storage_path": storage_path,
            "mime_type": mime_type,
            "file_size": len(file_bytes),
            "document_date": date.today().isoformat(),
            "expiration_date": (
                tenant_record.get(
                    "lease_end"
                )
                or None
            ),
            "notes": (
                notes.strip()
                if notes
                and notes.strip()
                else None
            ),
        })
        .execute()
    )

    new_document_id = (
        insert_result.data[0].get(
            "document_id"
        )
        if insert_result.data
        else None
    )

    log_owner_activity(
        "lease_document_uploaded",
        (
            f"Lease document uploaded for "
            f"{tenant_record.get('tenant_name', 'tenant')}"
        ),
        "document",
        new_document_id,
        {
            "tenant_id": tenant_record.get("tenant_id"),
            "unit_id": unit_id,
            "property_id": property_id,
            "document_name": uploaded_file.name,
        }
    )

    return new_document_id


