# V78D - CANONICAL OWNER NAVIGATION
# =========================================================
# One place owns legacy -> current navigation names. New code should
# only use the canonical names on the right-hand side.
_RENTFLOW_NAV_ALIASES = {
    "🏠 Dashboard": "🏠 Dashboard",
    "💵 Financials": "💵 Financials",
    "💰 Rent": "💰 Rent",
    "👥 Tenants": "👥 Tenants",
    "🏢 Properties": "🏢 Properties",
    "📁 Documents": "📁 Documents",
    "📊 Reports": "📊 Reports",
    "⚙️ Admin": "⚙️ Admin",
    # Older labels retained only as inbound compatibility.
    "💳 Plans & Usage": "⚙️ Admin",
    "💳 Plan & Admin": "⚙️ Admin",
}

_RENTFLOW_SUBTAB_ALIASES = {
    "🏠 Dashboard": {
        "Owner Action Center": "AI Action Center",
        "Risks": "AI Action Center",
    },
    "💵 Financials": {
        "Financial Dashboard": "Dashboard",
        "Manage Expenses": "Expenses",
        "Expense Intelligence": "Expenses",
        "Cashflow Performance": "Cashflow",
    },
    "💰 Rent": {
        "Monthly Rent": "Rent Action Center",
        "Owner Collections Center": "Collection Center",
        "Payments": "Payment Center",
        "Payment History": "Payment Center",
    },
    "👥 Tenants": {
        "Maintenance": "Maintenance Center",
        "Lease": "Lease Center",
        "Portal Access": "Onboarding Center",
        "Move Out Center": "Move-Out Center",
    },
    "📁 Documents": {
        "Documents": "Documents Center",
        "Upload Document": "Documents Center",
        "Document Alerts": "Documents Center",
    },
    "📊 Reports": {
        "Rent Roll": "Rent Report",
        "Payment Report": "Rent Report",
        "Property Performance": "Rent Report",
        "Tenant Ledger": "Rent Report",
        "👤 Tenant Ledger": "Rent Report",
    },
}


def _rentflow_normalize_destination(nav_label, subtab=None):
    canonical_nav = _RENTFLOW_NAV_ALIASES.get(
        nav_label,
        nav_label,
    )
    canonical_subtab = _RENTFLOW_SUBTAB_ALIASES.get(
        canonical_nav,
        {},
    ).get(
        subtab,
        subtab,
    )
    return canonical_nav, canonical_subtab


def _rentflow_set_focus(nav_label, subtab, section_label, record_id=None):
    """Store a one-time logical destination inside a RentFlow page."""
    nav_label, subtab = _rentflow_normalize_destination(
        nav_label,
        subtab,
    )
    st.session_state["rentflow_focus_context"] = {
        "nav_label": nav_label,
        "subtab": subtab,
        "section_label": section_label,
        "record_id": record_id,
    }


def _rentflow_render_focus_banner(current_nav_label, current_subtab):
    """
    Confirm a smart deep link after the correct page and record have loaded.
    This uses Streamlit session_state only—no JavaScript scrolling.
    """
    current_nav_label, current_subtab = _rentflow_normalize_destination(
        current_nav_label,
        current_subtab,
    )
    focus = st.session_state.get("rentflow_focus_context")

    if not focus:
        return

    if (
        focus.get("nav_label") != current_nav_label
        or focus.get("subtab") != current_subtab
    ):
        return

    section_label = focus.get("section_label") or "Selected workflow"
    st.info(f"🎯 Opened directly to **{section_label}**.")
    st.session_state.pop("rentflow_focus_context", None)


def _rentflow_infer_focus(nav_label, subtab):
    """
    Infer a focus only when a Go/Open action has already placed a specific
    record ID in session state. Plain menu navigation remains unchanged.
    """
    nav_label, subtab = _rentflow_normalize_destination(
        nav_label,
        subtab,
    )

    rules = {
        ("👥 Tenants", "Maintenance Center"): (
            "owner_action_maintenance_request_id",
            "Selected Maintenance Request",
        ),
        ("👥 Tenants", "Tenant 360"): (
            "owner_action_tenant360_id",
            "Selected Tenant",
        ),
        ("👥 Tenants", "Lease Center"): (
            "owner_action_lease_tenant_id",
            "Selected Tenant Lease",
        ),
        ("👥 Tenants", "Onboarding Center"): (
            "owner_onboarding_handoff_tenant_id",
            "Selected Tenant Onboarding",
        ),
        ("👥 Tenants", "Move In Center"): (
            "owner_move_in_tenant_id",
            "Selected Tenant Move-In",
        ),
        ("👥 Tenants", "Move-Out Center"): (
            "owner_move_out_tenant_id",
            "Selected Tenant Move-Out",
        ),
        ("💰 Rent", "Rent Action Center"): (
            "owner_action_rent_tenant_id",
            "Selected Tenant Rent Action",
        ),
        ("💰 Rent", "Payment Center"): (
            "rent_pending_payment_tenant_id",
            "Record Payment",
        ),
    }

    state_rule = rules.get((nav_label, subtab))
    if not state_rule:
        return None, None

    state_key, section_label = state_rule
    record_id = st.session_state.get(state_key)
    if record_id is None:
        # Rent Action Center also uses this newer target key.
        if (
            nav_label == "💰 Rent"
            and subtab == "Rent Action Center"
        ):
            record_id = st.session_state.get(
                "rent_action_target_tenant_id"
            )

    if record_id is None:
        return None, None

    return section_label, record_id


def rentflow_go_to(
    nav_label,
    subtab=None,
    focus_section=None,
    focus_record_id=None,
):
    """
    Queue an owner-page navigation change using canonical RentFlow
    destinations. Legacy names are normalized here instead of being
    repeated throughout page-specific routing code.
    """
    nav_label, subtab = _rentflow_normalize_destination(
        nav_label,
        subtab,
    )

    if not focus_section:
        focus_section, focus_record_id = _rentflow_infer_focus(
            nav_label,
            subtab,
        )

    if focus_section:
        _rentflow_set_focus(
            nav_label,
            subtab,
            focus_section,
            focus_record_id,
        )

    st.session_state["rentflow_pending_nav"] = nav_label

    if subtab:
        if nav_label == "💰 Rent":
            st.session_state[
                "rentflow_pending_owner_sidebar"
            ] = subtab
        else:
            st.session_state["rentflow_pending_subtab"] = subtab


def set_owner_return_context(
    origin_nav_label,
    origin_subtab=None,
    origin_label=None,
    target_nav_label=None,
    target_subtab=None,
):
    """
    Remember the page that opened a detail/action workflow.
    The sidebar Back control is shown only on the exact destination.
    """
    origin_nav_label, origin_subtab = _rentflow_normalize_destination(
        origin_nav_label,
        origin_subtab,
    )
    target_nav_label, target_subtab = _rentflow_normalize_destination(
        target_nav_label,
        target_subtab,
    )

    st.session_state["owner_return_context"] = {
        "origin_nav_label": origin_nav_label,
        "origin_subtab": origin_subtab,
        "origin_label": (
            origin_label
            or origin_subtab
            or origin_nav_label
        ),
        "target_nav_label": target_nav_label,
        "target_subtab": target_subtab,
    }


def owner_drilldown_go_to(
    nav_label,
    subtab=None,
    origin_nav_label="🏠 Dashboard",
    origin_subtab=None,
    origin_label=None,
    focus_section=None,
    focus_record_id=None,
):
    """
    Navigate to a detail page and create a temporary sidebar Back link.
    """
    set_owner_return_context(
        origin_nav_label=origin_nav_label,
        origin_subtab=origin_subtab,
        origin_label=origin_label,
        target_nav_label=nav_label,
        target_subtab=subtab,
    )

    rentflow_go_to(
        nav_label,
        subtab,
        focus_section=focus_section,
        focus_record_id=focus_record_id,
    )


def set_ai_action_return_context(
    group_name=None,
    record_type=None,
    record_id=None,
    target_nav_label=None,
    target_subtab=None,
):
    """
    Remember that the current workflow was opened from AI Action Center.
    The return control is valid only on the exact destination workflow.
    """
    target_nav_label, target_subtab = _rentflow_normalize_destination(
        target_nav_label,
        target_subtab,
    )

    st.session_state["ai_action_return_context"] = {
        "from_ai_action_center": True,
        "group_name": group_name,
        "record_type": record_type,
        "record_id": record_id,
        "target_nav_label": target_nav_label,
        "target_subtab": target_subtab,
    }

    set_owner_return_context(
        origin_nav_label="🏠 Dashboard",
        origin_subtab="AI Action Center",
        origin_label="AI Action Center",
        target_nav_label=target_nav_label,
        target_subtab=target_subtab,
    )


def render_ai_action_return(
    current_nav_label=None,
    current_subtab=None,
):
    """
    Return navigation is rendered contextually in the owner sidebar.
    Kept as a compatibility hook for existing destination pages.
    """
    return


def owner_action_go_to(
    nav_label,
    subtab=None,
    state_key=None,
    state_value=None,
    return_group=None,
    record_type=None,
    record_id=None,
    focus_section=None,
):
    """
    Navigate from AI Action Center to the related workflow, carry the
    target record, and remember how to return to the Action Center.
    """
    if state_key:
        st.session_state[state_key] = state_value

    set_ai_action_return_context(
        group_name=return_group,
        record_type=record_type,
        record_id=record_id,
        target_nav_label=nav_label,
        target_subtab=subtab,
    )

    normalized_nav, normalized_subtab = _rentflow_normalize_destination(
        nav_label,
        subtab,
    )

    if not focus_section:
        focus_section = {
            ("👥 Tenants", "Maintenance Center"): "Selected Maintenance Request",
            ("👥 Tenants", "Tenant 360"): "Selected Tenant",
            ("👥 Tenants", "Lease Center"): "Selected Tenant Lease",
            ("👥 Tenants", "Onboarding Center"): "Selected Tenant Onboarding",
            ("👥 Tenants", "Move In Center"): "Selected Tenant Move-In",
            ("👥 Tenants", "Move-Out Center"): "Selected Tenant Move-Out",
            ("💰 Rent", "Rent Action Center"): "Selected Tenant Rent Action",
            ("💰 Rent", "Collection Center"): "Selected Collection",
            ("💰 Rent", "Payment Center"): "Record Payment",
            ("🏢 Properties", "Property 360"): "Selected Property",
            ("🏢 Properties", "Unit Turnover Center"): "Selected Unit Turnover",
            ("💵 Financials", "Expenses"): "Expense Workflow",
            ("💵 Financials", "Cashflow"): "Cashflow Details",
        }.get((normalized_nav, normalized_subtab))

    rentflow_go_to(
        normalized_nav,
        normalized_subtab,
        focus_section=focus_section,
        focus_record_id=(
            record_id
            if record_id is not None
            else state_value
        ),
    )


def _rentflow_previous_month(month_value=None):
    month_value = month_value or date.today().replace(day=1)
    month_value = month_value.replace(day=1)

    if month_value.month == 1:
        return date(
            month_value.year - 1,
            12,
            1
        )

    return date(
        month_value.year,
        month_value.month - 1,
        1
    )


def _rentflow_owner_id():
    owner_id = getattr(
        auth_user,
        "id",
        None
    )

    if (
        not owner_id
        and isinstance(auth_user, dict)
    ):
        owner_id = auth_user.get("id")

    return str(owner_id) if owner_id else None


def _rentflow_get_month_close(rent_month):
    owner_id = _rentflow_owner_id()

    if not owner_id:
        return None

    try:
        rows = (
            supabase
            .table("rent_month_closures")
            .select("*")
            .eq("owner_id", owner_id)
            .eq(
                "rent_month",
                rent_month.isoformat()
            )
            .limit(1)
            .execute()
            .data
            or []
        )

        return rows[0] if rows else None

    except Exception:
        return None


def _rentflow_month_is_closed(rent_month):
    row = _rentflow_get_month_close(
        rent_month
    )

    return bool(
        row
        and str(
            row.get("status")
            or ""
        ).lower() == "closed"
    )



# =========================================================
# V67 - CONNECTED ACCOUNT TENANT PAYMENT WEBHOOK
# =========================================================
# Admin access is backed by public.rentflow_admins + RLS. The app never uses
# a Supabase service-role key in the browser-facing Streamlit process.

def rentflow_is_admin(user_id):
    if not user_id:
        return False

    try:
        rows = (
            supabase
            .table("rentflow_admins")
            .select("user_id")
            .eq("user_id", str(user_id))
            .limit(1)
            .execute()
            .data
            or []
        )
        return bool(rows)
    except Exception:
        # Before the V50 migration is installed, normal owner access continues.
        return False


_rentflow_admin_user_id = _rentflow_owner_id()
_rentflow_is_admin = rentflow_is_admin(
    _rentflow_admin_user_id
)

