def _money(value):
    try:
        return f"${float(value):,.2f}"
    except Exception:
        return "$0.00"


def _pdf_report(title, subtitle, headers, rows, landscape_mode=False):
    """Create a simple professional PDF report in memory."""
    if not REPORTLAB_AVAILABLE:
        return None

    buffer = BytesIO()
    page_size = landscape(letter) if landscape_mode else letter
    doc = SimpleDocTemplate(
        buffer,
        pagesize=page_size,
        rightMargin=0.35 * inch,
        leftMargin=0.35 * inch,
        topMargin=0.45 * inch,
        bottomMargin=0.45 * inch,
    )

    styles = getSampleStyleSheet()
    story = [
        Paragraph("RentFlow", styles["Title"]),
        Paragraph(title, styles["Heading2"]),
        Paragraph(subtitle, styles["Normal"]),
        Spacer(1, 0.15 * inch),
    ]

    safe_rows = [[str(h) for h in headers]]
    for row in rows:
        safe_rows.append([str("" if v is None else v) for v in row])

    table = Table(safe_rows, repeatRows=1)
    table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 7.5),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#D1D5DB")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F9FAFB")]),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]))

    story.append(table)
    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()



def _pdf_multi_section_report(title, subtitle, sections):
    """Create a professional multi-section PDF report in memory."""
    if not REPORTLAB_AVAILABLE:
        return None

    buffer = BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=letter,
        rightMargin=0.40 * inch,
        leftMargin=0.40 * inch,
        topMargin=0.45 * inch,
        bottomMargin=0.45 * inch,
    )

    styles = getSampleStyleSheet()
    story = [
        Paragraph("RentFlow", styles["Title"]),
        Paragraph(title, styles["Heading2"]),
        Paragraph(subtitle, styles["Normal"]),
        Spacer(1, 0.16 * inch),
    ]

    for section in sections:
        section_title = section.get("title")
        headers = section.get("headers") or []
        rows = section.get("rows") or []

        if section_title:
            story.append(Spacer(1, 0.08 * inch))
            story.append(Paragraph(section_title, styles["Heading3"]))

        safe_rows = [[str(h) for h in headers]]
        for row in rows:
            safe_rows.append([
                str("" if value is None else value)
                for value in row
            ])

        table = Table(safe_rows, repeatRows=1, hAlign="LEFT")
        table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ("FONTSIZE", (0, 0), (-1, -1), 7.5),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#D1D5DB")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [
                colors.white,
                colors.HexColor("#F9FAFB")
            ]),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), 4),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ]))
        story.append(table)
        story.append(Spacer(1, 0.12 * inch))

    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()


def _normalize_key(df, column):
    if column in df.columns:
        df[column] = df[column].astype("string")
    return df


def _load_report_dimensions():
    tenants = pd.DataFrame(
        supabase.table("tenants").select(
            "tenant_id,tenant_name"
        ).eq("owner_id", OWNER_SCOPE_ID).execute().data or []
    )
    units = pd.DataFrame(
        supabase.table("units").select(
            "unit_id,property_id,unit_number,monthly_rent,status"
        ).in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute().data or []
    )
    properties = pd.DataFrame(
        supabase.table("properties").select(
            "property_id,property_name"
        ).eq("owner_id", OWNER_SCOPE_ID).execute().data or []
    )

    for df, cols in [
        (tenants, ["tenant_id"]),
        (units, ["unit_id", "property_id"]),
        (properties, ["property_id"]),
    ]:
        for col in cols:
            _normalize_key(df, col)

    return tenants, units, properties


# =========================================================
# PHASE 7D - PROFESSIONAL REPORTS
# =========================================================


# =========================================================
# V78E - OWNER WORKFLOW RENDERERS
# =========================================================
# Large operational page bodies are kept in focused render functions.
# This makes navigation dispatch small and future changes safer while
# preserving the existing database model and user-facing workflows.

def render_rent_action_center():
    """Render Rent > Rent Action Center."""
    render_ai_action_return(
        "💰 Rent",
        "Rent Action Center",
    )

    st.subheader("🚨 Rent Action Center")
    _rentflow_render_focus_banner(
        "💰 Rent",
        "Rent Action Center",
    )
    st.caption(
        "See what needs attention, contact tenants, and move rent toward paid."
    )

    action_month = st.date_input(
        "Rent Month",
        value=date.today().replace(day=1),
        key="rent_action_month"
    ).replace(day=1)

    try:
        # V67C: repair stale unpaid rent-charge ownership before
        # building the Rent Action Center for the selected month.
        action_active_payers = (
            supabase.table("tenants")
            .select("tenant_id,unit_id,status,responsible_for_rent")
            .eq("owner_id", OWNER_SCOPE_ID)
            .eq("status", "Active")
            .eq("responsible_for_rent", True)
            .execute().data or []
        )
        for _payer in action_active_payers:
            _sync_unit_rent_charge_payer(
                OWNER_SCOPE_ID,
                _payer.get("unit_id"),
                _payer.get("tenant_id"),
                action_month,
            )

        action_rents = (
            supabase.table("rent_charges")
            .select("tenant_id,unit_id,rent_month,due_date,amount_due")
            .eq("rent_month", action_month.isoformat())
            .execute().data or []
        )

        action_payments = (
            supabase.table("payments")
            .select("*")
            .eq("rent_month", action_month.isoformat())
            .execute().data or []
        )

        action_tenants = (
            supabase.table("tenants")
            .select(
                "tenant_id,tenant_name,email,unit_id,status,"
                "tenant_role,responsible_for_rent"
            )
            .eq("owner_id", OWNER_SCOPE_ID).execute().data or []
        )

        action_units = (
            supabase.table("units")
            .select(
                "unit_id,unit_number,property_id,"
                "properties(property_name)"
            )
            .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute().data or []
        )

        tenant_by_id = {
            str(r.get("tenant_id")): r
            for r in action_tenants
        }
        unit_by_id = {
            str(r.get("unit_id")): r
            for r in action_units
        }

        paid_lookup = {}
        for p in action_payments:
            key = (
                str(p.get("tenant_id")),
                str(p.get("unit_id"))
            )
            paid_lookup[key] = (
                paid_lookup.get(key, 0.0)
                + float(p.get("amount_paid") or 0)
            )

        today_action = date.today()
        action_rows = []

        for charge in action_rents:
            tenant_id = str(charge.get("tenant_id"))
            unit_id = str(charge.get("unit_id"))
            tenant = tenant_by_id.get(tenant_id, {})
            unit = unit_by_id.get(unit_id, {})
            property_info = unit.get("properties") or {}

            due = float(charge.get("amount_due") or 0)
            paid = paid_lookup.get((tenant_id, unit_id), 0.0)
            balance = max(due - paid, 0.0)

            due_date_raw = charge.get("due_date")
            due_date_value = None
            if due_date_raw:
                try:
                    due_date_value = pd.to_datetime(
                        due_date_raw
                    ).date()
                except Exception:
                    pass

            days_to_due = (
                (due_date_value - today_action).days
                if due_date_value else None
            )

            if balance <= 0:
                workflow_status = "PAID"
            elif paid > 0:
                workflow_status = "PARTIAL"
            elif days_to_due is not None and days_to_due < 0:
                workflow_status = "OVERDUE"
            elif days_to_due == 0:
                workflow_status = "DUE TODAY"
            elif days_to_due is not None and 0 < days_to_due <= 5:
                workflow_status = "DUE SOON"
            else:
                workflow_status = "UPCOMING"

            action_rows.append({
                "Tenant ID": tenant_id,
                "Unit ID": unit_id,
                "Tenant": tenant.get("tenant_name") or "Tenant",
                "Email": tenant.get("email") or "",
                "Tenant Status": tenant.get("status") or "Unknown",
                "Tenant Role": (
                    tenant.get("tenant_role")
                    or "Primary Tenant"
                ),
                "Responsible Payer": bool(
                    tenant.get("responsible_for_rent")
                ),
                "Property": property_info.get(
                    "property_name", "Unknown"
                ),
                "Unit": unit.get("unit_number") or "—",
                "Due Date": due_date_raw,
                "Rent Due": due,
                "Paid": paid,
                "Balance": balance,
                "Workflow": workflow_status,
                "Days": days_to_due,
            })

        actionable_rows = [
            r for r in action_rows
            if r["Workflow"] != "PAID"
            and str(r["Tenant Status"]).lower() == "active"
        ]

        overdue_rows = [
            r for r in actionable_rows
            if r["Workflow"] == "OVERDUE"
        ]
        due_soon_rows = [
            r for r in actionable_rows
            if r["Workflow"] in ("DUE SOON", "DUE TODAY")
        ]
        partial_rows = [
            r for r in actionable_rows
            if r["Workflow"] == "PARTIAL"
        ]
        paid_rows = [
            r for r in action_rows
            if r["Workflow"] == "PAID"
        ]

        c1, c2, c3, c4 = st.columns(4)
        c1.metric("🔴 Overdue", len(overdue_rows))
        c2.metric("🟡 Due Soon / Today", len(due_soon_rows))
        c3.metric("🟠 Partial", len(partial_rows))
        c4.metric("✅ Paid", len(paid_rows))

        total_due_action = sum(
            float(row.get("Rent Due") or 0)
            for row in action_rows
        )
        total_paid_action = sum(
            float(row.get("Paid") or 0)
            for row in action_rows
        )
        total_outstanding_action = sum(
            float(row.get("Balance") or 0)
            for row in action_rows
        )
        collection_rate_action = (
            (total_paid_action / total_due_action) * 100
            if total_due_action > 0
            else 0
        )

        f1, f2, f3, f4 = st.columns(4)
        f1.metric("💰 Rent Due", f"${total_due_action:,.2f}")
        f2.metric("✅ Collected", f"${total_paid_action:,.2f}")
        f3.metric(
            "⚠️ Outstanding",
            f"${total_outstanding_action:,.2f}",
        )
        f4.metric(
            "📈 Collection Rate",
            f"{collection_rate_action:.1f}%",
        )

        st.divider()

        if not action_rows:
            st.info(
                "No rent charges exist for the selected month. "
                "Use Monthly Rent to generate charges."
            )
        else:
            priority = {
                "OVERDUE": 1,
                "PARTIAL": 2,
                "DUE TODAY": 3,
                "DUE SOON": 4,
                "UPCOMING": 5,
                "PAID": 6,
            }

            display_action = pd.DataFrame(action_rows)
            display_action["_priority"] = (
                display_action["Workflow"]
                .map(priority)
                .fillna(9)
            )
            display_action = display_action.sort_values(
                ["_priority", "Balance"],
                ascending=[True, False]
            ).drop(columns=["_priority"])

            visible_action = display_action[[
                "Workflow", "Property", "Unit", "Tenant",
                "Tenant Role", "Responsible Payer",
                "Due Date", "Rent Due", "Paid", "Balance"
            ]].copy()

            visible_action["Responsible Payer"] = (
                visible_action["Responsible Payer"]
                .map(lambda value: "Yes" if value else "No")
            )

            for money_col in ["Rent Due", "Paid", "Balance"]:
                visible_action[money_col] = (
                    visible_action[money_col]
                    .map(lambda x: f"${float(x):,.2f}")
                )

            st.dataframe(
                visible_action,
                use_container_width=True,
                hide_index=True
            )

            st.markdown("### Take Action")

            selection_options = {}
            for row in actionable_rows:
                label = (
                    f"{row['Workflow']} | {row['Tenant']} | "
                    f"{row['Property']} / Unit {row['Unit']} | "
                    f"${row['Balance']:,.2f}"
                )
                selection_options[label] = row

            if not selection_options:
                st.success(
                    "No rent follow-up is required for active tenants."
                )
            else:
                rent_action_labels = list(
                    selection_options.keys()
                )

                pending_rent_action_tenant_id = st.session_state.pop(
                    "owner_action_rent_tenant_id",
                    None
                )

                if pending_rent_action_tenant_id is not None:
                    for option_label in rent_action_labels:
                        option_row = selection_options[
                            option_label
                        ]
                        if str(
                            option_row.get(
                                "Tenant ID"
                            )
                        ) == str(
                            pending_rent_action_tenant_id
                        ):
                            st.session_state[
                                "rent_action_selected_item"
                            ] = option_label
                            break

                selected_action_label = st.selectbox(
                    "Select Tenant / Rent Item",
                    rent_action_labels,
                    key="rent_action_selected_item"
                )
                selected_action = selection_options[
                    selected_action_label
                ]

                a1, a2, a3 = st.columns(3)

                with a1:
                    reminder_button_label = (
                        "Send Overdue Notice"
                        if selected_action["Workflow"] == "OVERDUE"
                        else "Send Payment Reminder"
                    )

                    if st.button(
                        reminder_button_label,
                        type="primary",
                        use_container_width=True,
                        key="rent_action_send_reminder"
                    ):
                        tenant_email = selected_action["Email"]

                        if not tenant_email:
                            st.error(
                                "This tenant does not have an email address."
                            )
                        else:
                            workflow = selected_action["Workflow"]
                            due_date_text = (
                                selected_action["Due Date"] or "the due date"
                            )

                            if workflow == "OVERDUE":
                                subject = (
                                    f"RentFlow: Rent payment overdue — "
                                    f"${selected_action['Balance']:,.2f}"
                                )
                                opening = (
                                    "Our records show an outstanding rent "
                                    "balance that is now overdue."
                                )
                            elif workflow == "PARTIAL":
                                subject = (
                                    f"RentFlow: Remaining rent balance — "
                                    f"${selected_action['Balance']:,.2f}"
                                )
                                opening = (
                                    "Thank you for your payment. A remaining "
                                    "rent balance is still due."
                                )
                            else:
                                subject = (
                                    "RentFlow: Upcoming rent payment reminder"
                                )
                                opening = (
                                    "This is a friendly reminder that your "
                                    "rent payment is coming due."
                                )

                            email_body = f"""Hello {selected_action['Tenant']},

{opening}

Property: {selected_action['Property']}
Unit: {selected_action['Unit']}
Due Date: {due_date_text}
Rent Due: ${selected_action['Rent Due']:,.2f}
Paid: ${selected_action['Paid']:,.2f}
Remaining Balance: ${selected_action['Balance']:,.2f}

You can sign in to the RentFlow Tenant Portal to review your account and, when available, pay securely online.

Thank you,
RentFlow
"""

                            sent, message = (
                                send_rentflow_transactional_email(
                                    tenant_email,
                                    subject,
                                    email_body
                                )
                            )

                            communication_status = (
                                "Sent" if sent else "Failed"
                            )

                            try:
                                actor_user_id = getattr(
                                    auth_user,
                                    "id",
                                    None
                                )
                                if (
                                    not actor_user_id
                                    and isinstance(auth_user, dict)
                                ):
                                    actor_user_id = auth_user.get("id")

                                (
                                    supabase
                                    .table("tenant_communications")
                                    .insert({
                                        "tenant_id":
                                            selected_action["Tenant ID"],
                                        "unit_id":
                                            selected_action["Unit ID"],
                                        "rent_month":
                                            action_month.isoformat(),
                                        "communication_type":
                                            (
                                                "Overdue Notice"
                                                if selected_action["Workflow"] == "OVERDUE"
                                                else (
                                                    "Partial Balance Reminder"
                                                    if selected_action["Workflow"] == "PARTIAL"
                                                    else "Payment Reminder"
                                                )
                                            ),
                                        "channel": "Email",
                                        "recipient": tenant_email,
                                        "subject": subject,
                                        "message_body": email_body,
                                        "delivery_status":
                                            communication_status,
                                        "delivery_message": message,
                                        "sent_at":
                                            pd.Timestamp.utcnow().isoformat(),
                                        "created_by":
                                            (
                                                str(actor_user_id)
                                                if actor_user_id
                                                else None
                                            ),
                                    })
                                    .execute()
                                )
                            except Exception as communication_error:
                                st.warning(
                                    "The email action completed, but RentFlow "
                                    "could not save the communication history. "
                                    "Apply the tenant communications migration."
                                )
                                show_debug_exception(
                                    communication_error
                                )

                            if sent:
                                st.success(message)
                                log_owner_activity(
                                    "rent_reminder_sent",
                                    (
                                        f"{reminder_button_label}: "
                                        f"{selected_action['Tenant']}"
                                    ),
                                    "tenant",
                                    selected_action["Tenant ID"],
                                    {
                                        "rent_month":
                                            action_month.isoformat(),
                                        "workflow":
                                            selected_action["Workflow"],
                                        "balance":
                                            selected_action["Balance"],
                                        "email":
                                            tenant_email,
                                    }
                                )
                            else:
                                st.warning(message)

                with a2:
                    if st.button(
                        "Record Payment",
                        use_container_width=True,
                        key="rent_action_record_payment"
                    ):
                        st.session_state[
                            "rent_pending_payment_tenant_id"
                        ] = selected_action["Tenant ID"]
                        st.session_state[
                            "rent_pending_payment_month"
                        ] = action_month.isoformat()
                        st.session_state[
                            "rentflow_pending_owner_sidebar"
                        ] = "Payment Center"
                        st.rerun()

                with a3:
                    if st.button(
                        "View Payment History",
                        use_container_width=True,
                        key="rent_action_payment_history"
                    ):
                        current_inline_tenant = st.session_state.get(
                            "rent_action_inline_history_tenant"
                        )

                        if str(current_inline_tenant) == str(
                            selected_action["Tenant ID"]
                        ):
                            st.session_state.pop(
                                "rent_action_inline_history_tenant",
                                None
                            )
                        else:
                            st.session_state[
                                "rent_action_inline_history_tenant"
                            ] = selected_action["Tenant ID"]

                with st.expander(
                    "✉️ Recent Rent Notifications",
                    expanded=False,
                ):
                    try:
                        recent_communications = (
                            supabase
                            .table("tenant_communications")
                            .select(
                                "tenant_id,rent_month,communication_type,"
                                "recipient,delivery_status,sent_at"
                            )
                            .order("sent_at", desc=True)
                            .limit(50)
                            .execute()
                            .data
                            or []
                        )

                        if recent_communications:
                            communication_tenant_lookup = {
                                str(t.get("tenant_id")):
                                    t.get("tenant_name", "Tenant")
                                for t in action_tenants
                            }

                            communication_display_rows = []
                            for communication in recent_communications:
                                communication_display_rows.append({
                                    "Sent At":
                                        communication.get("sent_at"),
                                    "Tenant":
                                        communication_tenant_lookup.get(
                                            str(
                                                communication.get(
                                                    "tenant_id"
                                                )
                                            ),
                                            "Tenant",
                                        ),
                                    "Rent Month":
                                        communication.get("rent_month"),
                                    "Notification":
                                        communication.get(
                                            "communication_type"
                                        ),
                                    "Recipient":
                                        communication.get("recipient"),
                                    "Status":
                                        communication.get(
                                            "delivery_status"
                                        ),
                                })

                            st.dataframe(
                                pd.DataFrame(
                                    communication_display_rows
                                ),
                                use_container_width=True,
                                hide_index=True,
                            )
                        else:
                            st.info(
                                "No RentFlow rent notifications have been "
                                "recorded yet."
                            )
                    except Exception:
                        st.info(
                            "Apply the tenant communications migration "
                            "to enable notification history."
                        )

                st.caption(
                    "V1 reminders are owner-triggered. Automatic reminder "
                    "schedules can be added later after first-customer feedback."
                )

                # ---------------------------------------------
                # QUICK TENANT HISTORY — stays in Action Center
                # ---------------------------------------------
                inline_history_tenant = st.session_state.get(
                    "rent_action_inline_history_tenant"
                )

                if (
                    inline_history_tenant
                    and str(inline_history_tenant)
                    == str(selected_action["Tenant ID"])
                ):
                    st.divider()
                    st.markdown(
                        f"### 🧾 {selected_action['Tenant']} — Payment History"
                    )

                    try:
                        inline_payments = (
                            supabase
                            .table("payments")
                            .select("*")
                            .eq(
                                "tenant_id",
                                selected_action["Tenant ID"]
                            )
                            .order(
                                "payment_date",
                                desc=True
                            )
                            .limit(20)
                            .execute()
                            .data
                            or []
                        )

                        if inline_payments:
                            inline_payment_rows = []

                            for payment in inline_payments:
                                method = (
                                    payment.get("payment_method")
                                    or "Other"
                                )
                                stripe_session = payment.get(
                                    "stripe_session_id"
                                )
                                stripe_intent = payment.get(
                                    "stripe_payment_intent_id"
                                )

                                source = (
                                    "Stripe / Tenant Portal"
                                    if (
                                        stripe_session
                                        or stripe_intent
                                        or str(method).lower()
                                        == "stripe"
                                    )
                                    else "Manual / Owner Recorded"
                                )

                                inline_payment_rows.append({
                                    "Payment Date":
                                        payment.get("payment_date"),
                                    "Rent Month":
                                        payment.get("rent_month"),
                                    "Amount":
                                        float(
                                            payment.get(
                                                "amount_paid"
                                            )
                                            or 0
                                        ),
                                    "Method": method,
                                    "Source": source,
                                    "Notes":
                                        payment.get("notes") or "",
                                })

                            inline_payment_df = pd.DataFrame(
                                inline_payment_rows
                            )

                            inline_payment_df["Amount"] = (
                                inline_payment_df["Amount"]
                                .map(
                                    lambda value:
                                    f"${value:,.2f}"
                                )
                            )

                            st.dataframe(
                                inline_payment_df,
                                use_container_width=True,
                                hide_index=True
                            )
                        else:
                            st.info(
                                "No payments have been recorded for "
                                "this tenant yet."
                            )

                    except Exception as e:
                        st.warning(
                            "Unable to load this tenant's payment history."
                        )
                        show_debug_exception(e)

                    st.markdown("### ✉️ Communication History")

                    try:
                        communication_rows = (
                            supabase
                            .table("tenant_communications")
                            .select(
                                "communication_type,channel,recipient,"
                                "subject,delivery_status,sent_at,"
                                "rent_month,delivery_message"
                            )
                            .eq(
                                "tenant_id",
                                selected_action["Tenant ID"]
                            )
                            .order(
                                "sent_at",
                                desc=True
                            )
                            .limit(20)
                            .execute()
                            .data
                            or []
                        )

                        if communication_rows:
                            communication_df = pd.DataFrame(
                                communication_rows
                            ).rename(
                                columns={
                                    "communication_type":
                                        "Communication",
                                    "channel": "Channel",
                                    "recipient": "Recipient",
                                    "subject": "Subject",
                                    "delivery_status": "Status",
                                    "sent_at": "Sent At",
                                    "rent_month": "Rent Month",
                                    "delivery_message":
                                        "Delivery Detail",
                                }
                            )

                            st.dataframe(
                                communication_df,
                                use_container_width=True,
                                hide_index=True
                            )
                        else:
                            st.info(
                                "No RentFlow rent notifications have "
                                "been recorded for this tenant yet."
                            )

                    except Exception:
                        st.info(
                            "Communication history will appear here after "
                            "the V15 tenant communications migration is applied."
                        )

    except Exception as e:
        st.error("Unable to load the Rent Action Center.")
        show_debug_exception(e)


# =========================================================
# V77A - OWNER COLLECTIONS CENTER
# =========================================================


def render_collection_center():
    """Render Rent > Collection Center."""
    render_ai_action_return(
        "💰 Rent",
        "Collection Center",
    )

    st.markdown("### 💳 Collection Center")
    _rentflow_render_focus_banner(
        "💰 Rent",
        "Collection Center",
    )
    st.caption(
        "One portfolio view of money still owed by active and former tenants. "
        "Use the Rent Action Center and Move-Out Center to perform the actual collection workflow."
    )
    st.info(
        "AI Action Center = collection priorities · Collections Center = recovery pipeline · "
        "Rent / Move-Out Centers = transaction-specific actions"
    )

    try:
        collection_today = date.today()
        collection_month = collection_today.replace(day=1)

        # -----------------------------------------------------
        # Core portfolio data
        # -----------------------------------------------------
        collection_tenants = (
            supabase.table("tenants")
            .select(
                "tenant_id,tenant_name,email,phone,status,unit_id,"
                "responsible_for_rent"
            )
            .eq("owner_id", OWNER_SCOPE_ID)
            .execute().data or []
        )

        collection_units = (
            supabase.table("units")
            .select(
                "unit_id,unit_number,property_id,"
                "properties(property_name)"
            )
            .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY)
            .execute().data or []
        )

        tenant_lookup_collections = {
            str(row.get("tenant_id")): row
            for row in collection_tenants
            if row.get("tenant_id") is not None
        }
        unit_lookup_collections = {
            str(row.get("unit_id")): row
            for row in collection_units
            if row.get("unit_id") is not None
        }

        # -----------------------------------------------------
        # Active tenant rent collections
        # -----------------------------------------------------
        active_charge_rows = (
            supabase.table("rent_charges")
            .select(
                "tenant_id,unit_id,rent_month,due_date,amount_due"
            )
            .eq("rent_month", collection_month.isoformat())
            .execute().data or []
        )

        active_payment_rows = (
            supabase.table("payments")
            .select(
                "tenant_id,unit_id,rent_month,amount_paid,payment_date"
            )
            .eq("rent_month", collection_month.isoformat())
            .execute().data or []
        )

        paid_lookup_collections = {}
        last_payment_lookup_collections = {}

        for payment in active_payment_rows:
            key = (
                str(payment.get("tenant_id")),
                str(payment.get("unit_id")),
            )
            paid_lookup_collections[key] = (
                paid_lookup_collections.get(key, 0.0)
                + float(payment.get("amount_paid") or 0)
            )

            payment_date_value = payment.get("payment_date")
            if payment_date_value:
                current_last = last_payment_lookup_collections.get(key)
                if (
                    current_last is None
                    or str(payment_date_value) > str(current_last)
                ):
                    last_payment_lookup_collections[key] = payment_date_value

        try:
            communication_rows_collections = (
                supabase.table("tenant_communications")
                .select(
                    "tenant_id,communication_type,delivery_status,sent_at"
                )
                .order("sent_at", desc=True)
                .execute().data or []
            )
        except Exception:
            communication_rows_collections = []

        last_contact_by_tenant = {}
        for row in communication_rows_collections:
            tenant_key = str(row.get("tenant_id") or "")
            if (
                tenant_key
                and tenant_key not in last_contact_by_tenant
                and str(row.get("delivery_status") or "").lower()
                == "sent"
            ):
                last_contact_by_tenant[tenant_key] = row.get("sent_at")

        collection_rows = []

        for charge in active_charge_rows:
            tenant_id_value = str(charge.get("tenant_id"))
            unit_id_value = str(charge.get("unit_id"))
            tenant = tenant_lookup_collections.get(
                tenant_id_value,
                {}
            )

            if str(
                tenant.get("status") or ""
            ).strip().lower() != "active":
                continue

            if not bool(tenant.get("responsible_for_rent")):
                continue

            key = (tenant_id_value, unit_id_value)
            due_amount = float(charge.get("amount_due") or 0)
            paid_amount = paid_lookup_collections.get(key, 0.0)
            balance_amount = max(due_amount - paid_amount, 0.0)

            if balance_amount <= 0.005:
                continue

            due_date_value = charge.get("due_date")
            days_past_due = None
            try:
                due_date_parsed = pd.to_datetime(
                    due_date_value
                ).date()
                days_past_due = (
                    collection_today - due_date_parsed
                ).days
            except Exception:
                pass

            if paid_amount > 0:
                collection_stage = "Partially Paid"
            elif (
                days_past_due is not None
                and days_past_due > 0
            ):
                collection_stage = "Contact Needed"
            else:
                collection_stage = "New Balance"

            last_contact = last_contact_by_tenant.get(
                tenant_id_value
            )
            if (
                last_contact
                and collection_stage != "Partially Paid"
            ):
                collection_stage = "Payment Requested"

            unit = unit_lookup_collections.get(
                unit_id_value,
                {}
            )
            property_info = unit.get("properties") or {}

            collection_rows.append({
                "Collection Type": "Monthly Rent",
                "Tenant ID": tenant_id_value,
                "Unit ID": unit_id_value,
                "Tenant": tenant.get("tenant_name") or "Tenant",
                "Property": property_info.get(
                    "property_name",
                    "Property",
                ),
                "Unit": unit.get("unit_number") or "—",
                "Amount Due": balance_amount,
                "Stage": collection_stage,
                "Days Past Due": (
                    max(days_past_due, 0)
                    if days_past_due is not None
                    else None
                ),
                "Last Payment": (
                    last_payment_lookup_collections.get(key)
                ),
                "Last Contact": last_contact,
                "Payment Link": "Tenant Portal",
                "Email": tenant.get("email") or "",
                "Phone": tenant.get("phone") or "",
                "Source": "rent",
            })

        # -----------------------------------------------------
        # Move-out settlement collections
        # -----------------------------------------------------
        try:
            settlement_rows_collections = (
                supabase.table("move_out_settlements")
                .select(
                    "tenant_id,unit_id,balance_due,status,updated_at,"
                    "final_balance_collected,final_balance_paid_at,"
                    "stripe_checkout_session_id,stripe_checkout_url,"
                    "payment_link_emailed_at"
                )
                .eq("owner_id", OWNER_SCOPE_ID)
                .execute().data or []
            )
        except Exception:
            settlement_rows_collections = []

        for settlement in settlement_rows_collections:
            balance_amount = float(
                settlement.get("balance_due") or 0
            )
            if balance_amount <= 0.005:
                continue

            if str(
                settlement.get("status") or ""
            ).strip().lower() == "settled":
                continue

            tenant_id_value = str(
                settlement.get("tenant_id")
            )
            unit_id_value = str(
                settlement.get("unit_id")
            )

            tenant = tenant_lookup_collections.get(
                tenant_id_value,
                {}
            )
            unit = unit_lookup_collections.get(
                unit_id_value,
                {}
            )
            property_info = unit.get("properties") or {}

            payment_link_sent = bool(
                settlement.get("payment_link_emailed_at")
            )
            has_checkout = bool(
                settlement.get("stripe_checkout_session_id")
                or settlement.get("stripe_checkout_url")
            )

            if payment_link_sent:
                collection_stage = "Payment Requested"
                payment_link_status = "Email Sent"
            elif has_checkout:
                collection_stage = "Contact Needed"
                payment_link_status = "Link Created"
            else:
                collection_stage = "New Balance"
                payment_link_status = "Not Sent"

            collection_rows.append({
                "Collection Type": "Move-Out Balance",
                "Tenant ID": tenant_id_value,
                "Unit ID": unit_id_value,
                "Tenant": tenant.get("tenant_name") or "Tenant",
                "Property": property_info.get(
                    "property_name",
                    "Property",
                ),
                "Unit": unit.get("unit_number") or "—",
                "Amount Due": balance_amount,
                "Stage": collection_stage,
                "Days Past Due": None,
                "Last Payment": settlement.get(
                    "final_balance_paid_at"
                ),
                "Last Contact": settlement.get(
                    "payment_link_emailed_at"
                ),
                "Payment Link": payment_link_status,
                "Email": tenant.get("email") or "",
                "Phone": tenant.get("phone") or "",
                "Source": "move_out",
            })

        # -----------------------------------------------------
        # Summary
        # -----------------------------------------------------
        total_collection_balance = sum(
            float(row["Amount Due"])
            for row in collection_rows
        )
        active_rent_balance = sum(
            float(row["Amount Due"])
            for row in collection_rows
            if row["Collection Type"] == "Monthly Rent"
        )
        move_out_balance = sum(
            float(row["Amount Due"])
            for row in collection_rows
            if row["Collection Type"] == "Move-Out Balance"
        )
        payment_requested_count = sum(
            1 for row in collection_rows
            if row["Stage"] == "Payment Requested"
        )

        cc1, cc2, cc3, cc4 = st.columns(4)
        cc1.metric(
            "Total Outstanding",
            f"${total_collection_balance:,.2f}",
        )
        cc2.metric(
            "Active Rent",
            f"${active_rent_balance:,.2f}",
        )
        cc3.metric(
            "Move-Out Balances",
            f"${move_out_balance:,.2f}",
        )
        cc4.metric(
            "Payment Requested",
            payment_requested_count,
        )

        st.divider()

        if not collection_rows:
            st.success(
                "✅ No active collection balances require attention."
            )
        else:
            # -------------------------------------------------
            # Filters
            # -------------------------------------------------
            fc1, fc2 = st.columns(2)
            with fc1:
                collection_type_filter = st.selectbox(
                    "Collection Type",
                    [
                        "All",
                        "Monthly Rent",
                        "Move-Out Balance",
                    ],
                    key="v77a_collection_type",
                )
            with fc2:
                collection_stage_filter = st.selectbox(
                    "Collection Stage",
                    [
                        "All",
                        "New Balance",
                        "Contact Needed",
                        "Payment Requested",
                        "Partially Paid",
                    ],
                    key="v77a_collection_stage",
                )

            filtered_collection_rows = collection_rows

            if collection_type_filter != "All":
                filtered_collection_rows = [
                    row
                    for row in filtered_collection_rows
                    if row["Collection Type"]
                    == collection_type_filter
                ]

            if collection_stage_filter != "All":
                filtered_collection_rows = [
                    row
                    for row in filtered_collection_rows
                    if row["Stage"]
                    == collection_stage_filter
                ]

            st.markdown("#### Collection Pipeline")

            collection_display_rows = []
            for row in filtered_collection_rows:
                collection_display_rows.append({
                    "Type": row["Collection Type"],
                    "Tenant": row["Tenant"],
                    "Property": row["Property"],
                    "Unit": row["Unit"],
                    "Amount": f"${row['Amount Due']:,.2f}",
                    "Stage": row["Stage"],
                    "Days Past Due": (
                        row["Days Past Due"]
                        if row["Days Past Due"] is not None
                        else "—"
                    ),
                    "Last Payment": (
                        row["Last Payment"] or "—"
                    ),
                    "Last Contact": (
                        row["Last Contact"] or "—"
                    ),
                    "Payment Link": row["Payment Link"],
                })

            st.dataframe(
                pd.DataFrame(collection_display_rows),
                use_container_width=True,
                hide_index=True,
            )

            st.markdown("#### Collection Actions")

            option_map = {}
            for idx, row in enumerate(
                filtered_collection_rows
            ):
                option_label = (
                    f"{row['Collection Type']} | "
                    f"{row['Tenant']} | "
                    f"{row['Property']} Unit {row['Unit']} | "
                    f"${row['Amount Due']:,.2f} | "
                    f"{row['Stage']}"
                )
                option_map[f"{idx}|{option_label}"] = row

            if option_map:
                selected_collection_label = st.selectbox(
                    "Select Collection",
                    list(option_map.keys()),
                    format_func=lambda value: value.split(
                        "|",
                        1,
                    )[1],
                    key="v77a_selected_collection",
                )
                selected_collection = option_map[
                    selected_collection_label
                ]

                with st.container(border=True):
                    dc1, dc2, dc3, dc4 = st.columns(4)
                    dc1.metric(
                        "Amount Due",
                        f"${selected_collection['Amount Due']:,.2f}",
                    )
                    dc2.metric(
                        "Stage",
                        selected_collection["Stage"],
                    )
                    dc3.metric(
                        "Last Contact",
                        selected_collection["Last Contact"] or "—",
                    )
                    dc4.metric(
                        "Payment Link",
                        selected_collection["Payment Link"],
                    )

                    st.write(
                        f"**{selected_collection['Tenant']}** · "
                        f"{selected_collection['Property']} · "
                        f"Unit {selected_collection['Unit']}"
                    )

                    action_col1, action_col2 = st.columns(2)

                    if (
                        selected_collection["Source"]
                        == "rent"
                    ):
                        with action_col1:
                            if st.button(
                                "🚨 Open Rent Action Center",
                                type="primary",
                                use_container_width=True,
                                key="v77a_open_rent_action",
                            ):
                                st.session_state[
                                    "rent_action_target_tenant_id"
                                ] = selected_collection[
                                    "Tenant ID"
                                ]
                                rentflow_go_to(
                                    "💰 Rent",
                                    "Rent Action Center",
                                )
                                st.rerun()

                        with action_col2:
                            if st.button(
                                "💵 Record Payment",
                                use_container_width=True,
                                key="v77a_record_payment",
                            ):
                                st.session_state[
                                    "rent_pending_payment_tenant_id"
                                ] = selected_collection[
                                    "Tenant ID"
                                ]
                                st.session_state[
                                    "rentflow_pending_owner_sidebar"
                                ] = "Payments"
                                st.rerun()

                    else:
                        with action_col1:
                            if st.button(
                                "💳 Open Move-Out Collection",
                                type="primary",
                                use_container_width=True,
                                key="v77a_open_moveout_collection",
                            ):
                                st.session_state[
                                    "owner_move_out_tenant_id"
                                ] = selected_collection[
                                    "Tenant ID"
                                ]
                                rentflow_go_to(
                                    "👥 Tenants",
                                    "Move-Out Center",
                                )
                                st.rerun()

                        with action_col2:
                            if st.button(
                                "👤 Open Tenant 360",
                                use_container_width=True,
                                key="v77a_open_collection_tenant",
                            ):
                                st.session_state[
                                    "owner_action_tenant360_id"
                                ] = selected_collection[
                                    "Tenant ID"
                                ]
                                rentflow_go_to(
                                    "👥 Tenants",
                                    "Tenant 360",
                                )
                                st.rerun()

            st.divider()
            st.caption(
                "V77A does not duplicate rent reminder, payment recording, "
                "Stripe Checkout, or move-out settlement controls. "
                "It provides one collections pipeline and routes each item "
                "to the existing workflow that owns the transaction."
            )

    except Exception as e:
        st.error(
            "Unable to load Owner Collections Center. "
            f"Error: {e}"
        )
        show_debug_exception(e)


def render_month_close():
    """Render Rent > Month Close."""
    st.subheader("🔒 Rent Month Close")
    st.caption(
        "Review rent, payments, and outstanding balances before closing a month."
    )

    default_close_month = (
        _rentflow_previous_month(
            date.today().replace(
                day=1
            )
        )
    )

    close_month = (
        st.date_input(
            "Month to Review",
            value=default_close_month,
            key="rent_month_close_selector"
        )
        .replace(
            day=1
        )
    )

    close_month_text = (
        close_month.strftime(
            "%B %Y"
        )
    )

    existing_close = (
        _rentflow_get_month_close(
            close_month
        )
    )

    try:
        close_rents = (
            supabase
            .table("rent_charges")
            .select(
                "tenant_id,unit_id,"
                "due_date,amount_due"
            )
            .eq(
                "rent_month",
                close_month.isoformat()
            )
            .execute()
            .data
            or []
        )

        close_payments = (
            supabase
            .table("payments")
            .select(
                "tenant_id,unit_id,"
                "payment_date,amount_paid"
            )
            .eq(
                "rent_month",
                close_month.isoformat()
            )
            .execute()
            .data
            or []
        )

        close_tenants = (
            supabase
            .table("tenants")
            .select(
                "tenant_id,tenant_name"
            )
            .eq("owner_id", OWNER_SCOPE_ID).execute()
            .data
            or []
        )

        close_units = (
            supabase
            .table("units")
            .select(
                "unit_id,unit_number,"
                "properties(property_name)"
            )
            .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute()
            .data
            or []
        )

        close_tenant_lookup = {
            str(
                tenant.get(
                    "tenant_id"
                )
            ):
            tenant.get(
                "tenant_name",
                "Tenant"
            )
            for tenant in close_tenants
        }

        close_unit_lookup = {
            str(
                unit.get(
                    "unit_id"
                )
            ): unit
            for unit in close_units
        }

        close_payment_lookup = {}

        for payment in close_payments:
            payment_key = (
                str(
                    payment.get(
                        "tenant_id"
                    )
                ),
                str(
                    payment.get(
                        "unit_id"
                    )
                ),
            )

            close_payment_lookup[
                payment_key
            ] = (
                close_payment_lookup.get(
                    payment_key,
                    0.0
                )
                + float(
                    payment.get(
                        "amount_paid"
                    )
                    or 0
                )
            )

        close_rows = []
        close_total_due = 0.0
        close_total_paid = 0.0
        close_total_outstanding = 0.0
        close_unpaid_tenants = set()
        close_partial_tenants = set()

        for charge in close_rents:
            tenant_id = str(
                charge.get(
                    "tenant_id"
                )
            )
            unit_id = str(
                charge.get(
                    "unit_id"
                )
            )

            charge_due = float(
                charge.get(
                    "amount_due"
                )
                or 0
            )

            charge_paid = (
                close_payment_lookup.get(
                    (
                        tenant_id,
                        unit_id
                    ),
                    0.0
                )
            )

            charge_balance = max(
                charge_due
                - charge_paid,
                0.0
            )

            if charge_balance <= 0:
                charge_status = "PAID"
            elif charge_paid > 0:
                charge_status = "PARTIAL"
                close_partial_tenants.add(
                    tenant_id
                )
            else:
                charge_status = "OVERDUE"

            if charge_balance > 0:
                close_unpaid_tenants.add(
                    tenant_id
                )

            close_total_due += (
                charge_due
            )
            close_total_paid += (
                charge_paid
            )
            close_total_outstanding += (
                charge_balance
            )

            close_unit = (
                close_unit_lookup.get(
                    unit_id,
                    {}
                )
            )

            close_property = (
                close_unit.get(
                    "properties"
                )
                or {}
            )

            close_rows.append({
                "Status":
                    charge_status,
                "Property":
                    close_property.get(
                        "property_name",
                        "Unknown"
                    ),
                "Unit":
                    close_unit.get(
                        "unit_number"
                    )
                    or "—",
                "Tenant":
                    close_tenant_lookup.get(
                        tenant_id,
                        "Tenant"
                    ),
                "Rent Due":
                    charge_due,
                "Paid":
                    charge_paid,
                "Outstanding":
                    charge_balance,
            })

        close_collection_rate = (
            close_total_paid
            / close_total_due
            * 100
            if close_total_due > 0
            else 0
        )

        close_status = (
            str(
                existing_close.get(
                    "status"
                )
                or ""
            )
            if existing_close
            else "Open"
        )

        st.markdown(
            f"### {close_month_text}"
        )

        if (
            close_status.lower()
            == "closed"
        ):
            st.success(
                f"✅ {close_month_text} is closed."
            )
        else:
            st.warning(
                f"⚠️ {close_month_text} is still open."
            )

        m1, m2, m3, m4 = (
            st.columns(4)
        )

        m1.metric(
            "Rent Due",
            f"${close_total_due:,.2f}"
        )
        m2.metric(
            "Collected",
            f"${close_total_paid:,.2f}"
        )
        m3.metric(
            "Outstanding",
            f"${close_total_outstanding:,.2f}"
        )
        m4.metric(
            "Collection Rate",
            f"{close_collection_rate:.1f}%"
        )

        issue1, issue2 = (
            st.columns(2)
        )

        issue1.metric(
            "Unpaid Tenants",
            len(
                close_unpaid_tenants
            )
        )
        issue2.metric(
            "Partial Payments",
            len(
                close_partial_tenants
            )
        )

        if close_rows:
            close_df = pd.DataFrame(
                close_rows
            )

            outstanding_df = close_df[
                close_df[
                    "Outstanding"
                ] > 0
            ].copy()

            if not outstanding_df.empty:
                st.markdown(
                    "### Outstanding Balances"
                )

                for money_col in [
                    "Rent Due",
                    "Paid",
                    "Outstanding"
                ]:
                    outstanding_df[
                        money_col
                    ] = (
                        outstanding_df[
                            money_col
                        ]
                        .map(
                            lambda value:
                            f"${value:,.2f}"
                        )
                    )

                st.dataframe(
                    outstanding_df,
                    use_container_width=True,
                    hide_index=True
                )
            else:
                st.success(
                    "All rent charges for this month are fully paid."
                )
        else:
            st.info(
                "No rent charges exist for this month."
            )

        st.divider()

        owner_id = (
            _rentflow_owner_id()
        )

        if (
            close_status.lower()
            == "closed"
        ):
            st.caption(
                "Closed months are treated as read-only for normal "
                "rent processing. Reopen the month before making a "
                "historical correction."
            )

            if st.button(
                f"Reopen {close_month_text}",
                key="rent_reopen_month"
            ):
                try:
                    (
                        supabase
                        .table(
                            "rent_month_closures"
                        )
                        .update({
                            "status": "Open",
                            "reopened_at":
                                pd.Timestamp.utcnow().isoformat(),
                            "reopened_by":
                                owner_id,
                        })
                        .eq(
                            "owner_id",
                            owner_id
                        )
                        .eq(
                            "rent_month",
                            close_month.isoformat()
                        )
                        .execute()
                    )

                    log_owner_activity(
                        "rent_month_reopened",
                        (
                            f"Rent month reopened: "
                            f"{close_month_text}"
                        ),
                        "rent_month",
                        close_month.isoformat(),
                        {
                            "rent_month":
                                close_month.isoformat()
                        }
                    )

                    st.success(
                        f"{close_month_text} reopened."
                    )
                    st.rerun()

                except Exception as e:
                    st.error(
                        "Unable to reopen the rent month. "
                        "Apply the V16 month-close migration first."
                    )
                    show_debug_exception(e)

        elif close_total_due <= 0:
            st.info(
                "Generate rent charges before closing this month."
            )

        else:
            close_with_balance = (
                close_total_outstanding
                > 0
            )

            if close_with_balance:
                st.warning(
                    "This month still has outstanding rent. "
                    "Closing with outstanding balances preserves those "
                    "amounts as prior-month receivables; they are not erased."
                )

            close_button_label = (
                "Close With Outstanding Balances"
                if close_with_balance
                else f"Close {close_month_text}"
            )

            if st.button(
                close_button_label,
                type="primary",
                key="rent_close_month"
            ):
                close_payload = {
                    "owner_id":
                        owner_id,
                    "rent_month":
                        close_month.isoformat(),
                    "status":
                        "Closed",
                    "rent_due":
                        close_total_due,
                    "rent_collected":
                        close_total_paid,
                    "outstanding_balance":
                        close_total_outstanding,
                    "unpaid_tenant_count":
                        len(
                            close_unpaid_tenants
                        ),
                    "partial_tenant_count":
                        len(
                            close_partial_tenants
                        ),
                    "closed_with_outstanding":
                        close_with_balance,
                    "closed_at":
                        pd.Timestamp.utcnow().isoformat(),
                    "closed_by":
                        owner_id,
                    "reopened_at":
                        None,
                    "reopened_by":
                        None,
                }

                try:
                    existing_row = (
                        _rentflow_get_month_close(
                            close_month
                        )
                    )

                    if existing_row:
                        (
                            supabase
                            .table(
                                "rent_month_closures"
                            )
                            .update(
                                close_payload
                            )
                            .eq(
                                "owner_id",
                                owner_id
                            )
                            .eq(
                                "rent_month",
                                close_month.isoformat()
                            )
                            .execute()
                        )
                    else:
                        (
                            supabase
                            .table(
                                "rent_month_closures"
                            )
                            .insert(
                                close_payload
                            )
                            .execute()
                        )

                    log_owner_activity(
                        "rent_month_closed",
                        (
                            f"Rent month closed: "
                            f"{close_month_text}"
                        ),
                        "rent_month",
                        close_month.isoformat(),
                        {
                            "rent_month":
                                close_month.isoformat(),
                            "outstanding":
                                close_total_outstanding,
                            "closed_with_outstanding":
                                close_with_balance,
                        }
                    )

                    st.success(
                        f"{close_month_text} closed successfully."
                    )
                    st.rerun()

                except Exception as e:
                    st.error(
                        "Unable to close the rent month. "
                        "Apply the V16 month-close migration first."
                    )
                    show_debug_exception(e)

    except Exception as e:
        st.error(
            "Unable to load the month-close review."
        )
        show_debug_exception(e)


def render_payment_center():
    """Render Rent > Payment Center."""
    render_ai_action_return(
        "💰 Rent",
        "Payment Center",
    )

    st.subheader("💵 Payment Center")
    _rentflow_render_focus_banner(
        "💰 Rent",
        "Payment Center",
    )
    st.caption(
        "Record payments received outside the Tenant Portal and review "
        "the tenant balance. Stripe payments are recorded automatically."
    )

    try:

        # -------------------------------------------------
        # ACTIVE TENANTS
        # -------------------------------------------------

        tenants_result = (
            supabase
            .table("tenants")
            .select(
                "tenant_id,"
                "tenant_name,"
                "unit_id,"
                "status"
            )
            .eq(
                "status",
                "Active"
            )
            .eq("owner_id", OWNER_SCOPE_ID).execute()
        )

        tenants_data = (
            tenants_result.data or []
        )

        if not tenants_data:

            st.warning(
                "No active tenants found."
            )

        else:

            # ---------------------------------------------
            # UNIT INFORMATION
            # ---------------------------------------------

            units_result = (
                supabase
                .table("units")
                .select(
                    "unit_id,"
                    "unit_number,"
                    "monthly_rent,"
                    "properties(property_name)"
                )
                .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute()
            )

            units_data = (
                units_result.data or []
            )

            units_lookup = {
                u["unit_id"]: u
                for u in units_data
            }

            tenant_options = {}

            for tenant in tenants_data:

                unit = units_lookup.get(
                    tenant["unit_id"],
                    {}
                )

                property_info = (
                    unit.get("properties")
                    or {}
                )

                property_name = (
                    property_info.get(
                        "property_name",
                        "Unknown"
                    )
                )

                unit_number = (
                    unit.get(
                        "unit_number",
                        "Unknown"
                    )
                )

                label = (
                    f"{property_name} | "
                    f"Unit {unit_number} | "
                    f"{tenant['tenant_name']}"
                )

                tenant_options[label] = (
                    tenant
                )

            pending_payment_tenant_id = st.session_state.pop(
                "rent_pending_payment_tenant_id",
                None
            )

            tenant_labels = list(tenant_options.keys())
            tenant_default_index = 0

            if pending_payment_tenant_id:
                for idx, label in enumerate(tenant_labels):
                    if str(
                        tenant_options[label].get("tenant_id")
                    ) == str(pending_payment_tenant_id):
                        tenant_default_index = idx
                        break

            selected_label = st.selectbox(
                "Tenant",
                tenant_labels,
                index=tenant_default_index,
                key="rent_payment_tenant_select"
            )

            selected_tenant = (
                tenant_options[
                    selected_label
                ]
            )

            tenant_id = (
                selected_tenant[
                    "tenant_id"
                ]
            )

            unit_id = (
                selected_tenant[
                    "unit_id"
                ]
            )

            unit = units_lookup.get(
                unit_id,
                {}
            )

            monthly_rent = float(
                unit.get(
                    "monthly_rent",
                    0
                )
            )

            unit_number = unit.get(
                "unit_number",
                ""
            )

            property_info = (
                unit.get("properties")
                or {}
            )

            property_name = (
                property_info.get(
                    "property_name",
                    "Unknown"
                )
            )

            st.info(
                f"**{property_name}** | "
                f"Unit **{unit_number}** | "
                f"Monthly Rent "
                f"**${monthly_rent:,.2f}**"
            )

            # ---------------------------------------------
            # RENT MONTH
            # ---------------------------------------------

            pending_payment_month = st.session_state.pop(
                "rent_pending_payment_month",
                None
            )

            try:
                payment_month_default = (
                    pd.to_datetime(
                        pending_payment_month
                    ).date()
                    if pending_payment_month
                    else date.today().replace(day=1)
                )
            except Exception:
                payment_month_default = date.today().replace(day=1)

            payment_month = st.date_input(
                "Rent Month",
                value=payment_month_default,
                key="payment_rent_month"
            )

            payment_month = (
                payment_month.replace(
                    day=1
                )
            )

            # ---------------------------------------------
            # EXISTING PAYMENTS
            # ---------------------------------------------

            existing_payments_result = (
                supabase
                .table("payments")
                .select(
                    "amount_paid"
                )
                .eq(
                    "tenant_id",
                    tenant_id
                )
                .eq(
                    "unit_id",
                    unit_id
                )
                .eq(
                    "rent_month",
                    payment_month.isoformat()
                )
                .execute()
            )

            existing_payments = (
                existing_payments_result.data
                or []
            )

            total_paid = sum(
                float(
                    p["amount_paid"]
                )
                for p in existing_payments
            )

            balance = (
                monthly_rent
                - total_paid
            )

            st.write(
                f"Already Paid: "
                f"**${total_paid:,.2f}**"
            )

            outstanding_balance = max(float(balance or 0), 0.0)
            payment_is_paid_in_full = outstanding_balance <= 0.005

            st.write(
                f"Outstanding: "
                f"**${outstanding_balance:,.2f}**"
            )

            if payment_is_paid_in_full:
                st.success(
                    "✅ Paid in Full — no additional payment is required "
                    "for this rent month."
                )

            # ---------------------------------------------
            # PAYMENT FORM
            # ---------------------------------------------

            st.divider()

            payment_date = st.date_input(
                "Payment Date",
                value=date.today(),
                disabled=payment_is_paid_in_full
            )

            if payment_is_paid_in_full:
                amount_paid = st.number_input(
                    "Payment Amount",
                    min_value=0.00,
                    max_value=0.00,
                    value=0.00,
                    step=50.00,
                    disabled=True
                )
            else:
                amount_paid = st.number_input(
                    "Payment Amount",
                    min_value=0.01,
                    max_value=float(outstanding_balance),
                    value=float(outstanding_balance),
                    step=50.00
                )

            payment_method = st.selectbox(
                "Payment Method",
                [
                    "ACH",
                    "Check",
                    "Cash",
                    "Credit Card",
                    "Debit Card",
                    "Money Order",
                    "Other"
                ],
                disabled=payment_is_paid_in_full
            )

            notes = st.text_area(
                "Notes",
                placeholder=(
                    "Optional payment notes..."
                ),
                disabled=payment_is_paid_in_full
            )

            payment_month_closed = (
                _rentflow_month_is_closed(
                    payment_month
                )
            )

            if payment_month_closed:
                st.warning(
                    f"🔒 {payment_month.strftime('%B %Y')} is closed. "
                    "Reopen the month before recording a historical payment."
                )

            if st.button(
                "Record Payment",
                type="primary",
                disabled=(
                    payment_month_closed
                    or payment_is_paid_in_full
                )
            ):

                # V61 defense-in-depth: re-check the remaining balance
                # immediately before any payment is written.
                if payment_is_paid_in_full:
                    st.error(
                        "This rent month is already paid in full."
                    )

                elif amount_paid <= 0:
                    st.error(
                        "Payment amount must be greater than zero."
                    )

                elif amount_paid > outstanding_balance + 0.005:
                    st.error(
                        f"Payment cannot exceed the outstanding balance "
                        f"of ${outstanding_balance:,.2f}."
                    )

                else:

                    payment_record = {

                        "tenant_id":
                            tenant_id,

                        "unit_id":
                            unit_id,

                        "rent_month":
                            payment_month.isoformat(),

                        "payment_date":
                            payment_date.isoformat(),

                        "amount_paid":
                            float(
                                amount_paid
                            ),

                        "payment_method":
                            payment_method,

                        "notes":
                            (
                                ("Manual owner entry. " + notes)
                                if notes
                                else "Manual owner entry"
                            )
                    }

                    try:

                        (
                            supabase
                            .table("payments")
                            .insert(
                                payment_record
                            )
                            .execute()
                        )

                        log_owner_activity(
                            "payment_recorded",
                            (
                                f"Payment recorded: "
                                f"${amount_paid:,.2f} for "
                                f"{selected_tenant.get('tenant_name', 'tenant')}"
                            ),
                            "tenant",
                            tenant_id,
                            {
                                "unit_id": unit_id,
                                "rent_month": payment_month.isoformat(),
                                "payment_date": payment_date.isoformat(),
                                "amount_paid": float(amount_paid),
                                "payment_method": payment_method,
                            }
                        )

                        st.success(
                            f"Payment of "
                            f"${amount_paid:,.2f} "
                            "recorded successfully."
                        )

                        st.rerun()

                    except Exception as e:

                        st.error(
                            "Unable to record payment."
                        )

                        show_debug_exception(e)

    except Exception as e:

        st.error(
            "Unable to load payment information."
        )

        show_debug_exception(e)




    st.divider()
    st.subheader("🧾 Payment History")
    st.caption(
        "Review Stripe and manually recorded rent payments in one audit trail."
    )

    history_month = st.date_input(
        "Payment Month",
        value=date.today().replace(day=1),
        key="rent_payment_history_month"
    ).replace(day=1)

    try:
        history_payments = (
            supabase.table("payments")
            .select("*")
            .eq("rent_month", history_month.isoformat())
            .order("payment_date", desc=True)
            .execute().data or []
        )

        history_tenants = (
            supabase.table("tenants")
            .select("tenant_id,tenant_name")
            .eq("owner_id", OWNER_SCOPE_ID).execute().data or []
        )

        history_units = (
            supabase.table("units")
            .select(
                "unit_id,unit_number,properties(property_name)"
            )
            .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute().data or []
        )

        tenant_history_lookup = {
            str(t.get("tenant_id")):
                t.get("tenant_name", "Tenant")
            for t in history_tenants
        }
        unit_history_lookup = {
            str(u.get("unit_id")): u
            for u in history_units
        }

        pending_history_tenant = None

        if history_payments:
            history_rows = []

            for payment in history_payments:
                tenant_id = str(payment.get("tenant_id"))
                unit_id = str(payment.get("unit_id"))

                if (
                    pending_history_tenant
                    and tenant_id != str(pending_history_tenant)
                ):
                    continue

                unit = unit_history_lookup.get(unit_id, {})
                property_info = unit.get("properties") or {}

                method = payment.get("payment_method") or "Other"
                stripe_session = payment.get("stripe_session_id")
                stripe_intent = payment.get(
                    "stripe_payment_intent_id"
                )

                source = (
                    "Stripe / Tenant Portal"
                    if stripe_session
                    or stripe_intent
                    or str(method).lower() == "stripe"
                    else "Manual / Owner Recorded"
                )

                history_rows.append({
                    "Date": payment.get("payment_date"),
                    "Tenant": tenant_history_lookup.get(
                        tenant_id, "Tenant"
                    ),
                    "Property": property_info.get(
                        "property_name", "Unknown"
                    ),
                    "Unit": unit.get("unit_number") or "—",
                    "Amount": float(
                        payment.get("amount_paid") or 0
                    ),
                    "Method": method,
                    "Source": source,
                    "Notes": payment.get("notes") or "",
                    "Stripe Reference": (
                        stripe_session
                        or stripe_intent
                        or ""
                    ),
                })

            if history_rows:
                history_df = pd.DataFrame(history_rows)

                total_history = history_df["Amount"].sum()
                stripe_total = history_df.loc[
                    history_df["Source"] == "Stripe / Tenant Portal",
                    "Amount"
                ].sum()
                manual_total = total_history - stripe_total

                h1, h2, h3 = st.columns(3)
                h1.metric("Total Received", f"${total_history:,.2f}")
                h2.metric("Stripe", f"${stripe_total:,.2f}")
                h3.metric("Manual", f"${manual_total:,.2f}")

                display_history = history_df.copy()
                display_history["Amount"] = (
                    display_history["Amount"]
                    .map(lambda x: f"${x:,.2f}")
                )

                st.dataframe(
                    display_history,
                    use_container_width=True,
                    hide_index=True
                )

                st.download_button(
                    "⬇️ Download Payment History",
                    data=history_df.to_csv(
                        index=False
                    ).encode("utf-8"),
                    file_name=(
                        "payment_history_"
                        f"{history_month.strftime('%Y_%m')}.csv"
                    ),
                    mime="text/csv",
                    key="rent_download_payment_history"
                )
            else:
                st.info(
                    "No payments match the selected tenant and month."
                )
        else:
            st.info(
                f"No payments were recorded for "
                f"{history_month.strftime('%B %Y')}."
            )

        st.caption(
            "Stripe payments are written to RentFlow after successful "
            "checkout verification. Manual payments are recorded by the owner."
        )

    except Exception as e:
        st.error("Unable to load payment history.")
        show_debug_exception(e)


    # =========================================================
    # CSV IMPORT
    # =========================================================


def render_documents_center(documents_section='Documents Center'):
    """Render the consolidated Documents Center."""
    _documents_section = documents_section

    st.subheader("📁 Documents Center")
    st.caption(
        "Upload, organize, review, and monitor portfolio documents in one place."
    )

    if _documents_section in (
        "Documents",
        "Upload Document",
        "Document Alerts",
    ):
        _documents_section = "Documents Center"


    # -----------------------------------------------------
    # Shared lookup data
    # -----------------------------------------------------
    try:
        doc_properties = (
            supabase
            .table("properties")
            .select("property_id,property_name")
            .order("property_name")
            .eq("owner_id", OWNER_SCOPE_ID).execute()
            .data
            or []
        )
    except Exception:
        doc_properties = []

    try:
        doc_units = (
            supabase
            .table("units")
            .select("unit_id,unit_number,property_id")
            .order("unit_number")
            .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute()
            .data
            or []
        )
    except Exception:
        doc_units = []

    try:
        doc_tenants = (
            supabase
            .table("tenants")
            .select("tenant_id,tenant_name,unit_id,status")
            .order("tenant_name")
            .eq("owner_id", OWNER_SCOPE_ID).execute()
            .data
            or []
        )
    except Exception:
        doc_tenants = []

    property_lookup = {
        str(row.get("property_id")): row.get("property_name", "Property")
        for row in doc_properties
    }

    unit_lookup = {
        str(row.get("unit_id")): row
        for row in doc_units
    }

    tenant_lookup = {
        str(row.get("tenant_id")): row
        for row in doc_tenants
    }

    # =====================================================
    # TAB 1 - DOCUMENTS
    # =====================================================
    if _documents_section == "Documents Center":
        st.markdown("### ⬆️ Upload Document")

        st.caption(
            "Attach a file to a property, unit, tenant, or lease."
        )

        document_file = st.file_uploader(
            "Choose Document",
            type=[
                "pdf",
                "doc",
                "docx",
                "jpg",
                "jpeg",
                "png",
                "txt",
                "csv",
            ],
            key="p5a_document_file"
        )

        document_type = st.selectbox(
            "Document Type",
            [
                "Lease",
                "Notice",
                "Receipt",
                "Inspection",
                "Property",
                "Insurance",
                "Maintenance",
                "Other",
            ],
            key="p5a_document_type"
        )

        property_options = {
            "Not linked to a property": None
        }

        for row in doc_properties:
            property_options[
                row.get(
                    "property_name",
                    "Property"
                )
            ] = row.get(
                "property_id"
            )

        selected_property_label = st.selectbox(
            "Property",
            list(property_options.keys()),
            key="p5a_document_property"
        )

        selected_property_id = property_options[
            selected_property_label
        ]

        available_units = [
            row
            for row in doc_units
            if (
                selected_property_id is None
                or str(row.get("property_id"))
                == str(selected_property_id)
            )
        ]

        unit_options = {
            "Not linked to a unit": None
        }

        for row in available_units:
            unit_options[
                f"Unit {row.get('unit_number', '—')}"
            ] = row.get("unit_id")

        selected_unit_label = st.selectbox(
            "Unit",
            list(unit_options.keys()),
            key="p5a_document_unit"
        )

        selected_unit_id = unit_options[
            selected_unit_label
        ]

        available_tenants = [
            row
            for row in doc_tenants
            if (
                selected_unit_id is None
                or str(row.get("unit_id"))
                == str(selected_unit_id)
            )
        ]

        tenant_options = {
            "Not linked to a tenant": None
        }

        for row in available_tenants:
            tenant_options[
                row.get(
                    "tenant_name",
                    "Tenant"
                )
            ] = row.get(
                "tenant_id"
            )

        selected_tenant_label = st.selectbox(
            "Tenant",
            list(tenant_options.keys()),
            key="p5a_document_tenant"
        )

        selected_tenant_id = tenant_options[
            selected_tenant_label
        ]

        date_col1, date_col2 = st.columns(2)

        with date_col1:
            document_date = st.date_input(
                "Document Date",
                value=date.today(),
                key="p5a_document_date"
            )

        with date_col2:
            track_expiration = st.checkbox(
                "Track expiration",
                value=False,
                key="p5a_track_expiration"
            )

            expiration_date = None

            if track_expiration:
                expiration_date = st.date_input(
                    "Expiration Date",
                    value=(
                        date.today()
                        + timedelta(days=365)
                    ),
                    key="p5a_expiration_date"
                )

        document_notes = st.text_area(
            "Notes",
            placeholder=(
                "Optional notes, renewal details, notice type, "
                "or other document information."
            ),
            key="p5a_document_notes"
        )

        upload_busy = st.session_state.get(
            "p5a_document_upload_busy",
            False
        )

        if st.button(
            "Uploading..." if upload_busy else "Upload Document",
            type="primary",
            use_container_width=True,
            disabled=upload_busy,
            key="p5a_upload_document_button"
        ):

            if document_file is None:
                st.error(
                    "Choose a document to upload."
                )

            elif (
                expiration_date is not None
                and expiration_date < document_date
            ):
                st.error(
                    "Expiration Date cannot be before Document Date."
                )

            else:
                st.session_state[
                    "p5a_document_upload_busy"
                ] = True

                try:
                    import re
                    import uuid

                    owner_id = getattr(
                        auth_user,
                        "id",
                        None
                    )

                    safe_filename = re.sub(
                        r"[^A-Za-z0-9._-]",
                        "_",
                        document_file.name
                    )

                    storage_path = (
                        f"{owner_id}/"
                        f"{uuid.uuid4().hex}_"
                        f"{safe_filename}"
                    )

                    upload_size_ok, upload_size_message = (
                        validate_upload_size(
                            document_file,
                            max_mb=10
                        )
                    )

                    if not upload_size_ok:
                        st.error(
                            upload_size_message
                        )
                        st.stop()

                    file_bytes = (
                        document_file.getvalue()
                    )

                    mime_type = (
                        document_file.type
                        or "application/octet-stream"
                    )

                    (
                        supabase
                        .storage
                        .from_("rentflow-documents")
                        .upload(
                            storage_path,
                            file_bytes,
                            {
                                "content-type":
                                    mime_type,
                                "upsert":
                                    "false",
                            }
                        )
                    )

                    insert_result = (
                        supabase
                        .table("documents")
                        .insert({
                            "owner_id":
                                str(owner_id),

                            "document_name":
                                document_file.name,

                            "document_type":
                                document_type,

                            "property_id":
                                (
                                    str(selected_property_id)
                                    if selected_property_id
                                    is not None
                                    else None
                                ),

                            "unit_id":
                                (
                                    str(selected_unit_id)
                                    if selected_unit_id
                                    is not None
                                    else None
                                ),

                            "tenant_id":
                                (
                                    str(selected_tenant_id)
                                    if selected_tenant_id
                                    is not None
                                    else None
                                ),

                            "storage_path":
                                storage_path,

                            "mime_type":
                                mime_type,

                            "file_size":
                                len(file_bytes),

                            "document_date":
                                document_date.isoformat(),

                            "expiration_date":
                                (
                                    expiration_date.isoformat()
                                    if expiration_date
                                    is not None
                                    else None
                                ),

                            "notes":
                                (
                                    document_notes.strip()
                                    or None
                                ),
                        })
                        .execute()
                    )

                    new_document_id = (
                        insert_result.data[0].get(
                            "document_id"
                        )
                        if insert_result.data
                        else None
                    )

                    log_owner_activity(
                        "document_uploaded",
                        (
                            f"Document uploaded: "
                            f"{document_file.name}"
                        ),
                        "document",
                        new_document_id,
                        {
                            "document_type":
                                document_type,

                            "property_id":
                                (
                                    str(selected_property_id)
                                    if selected_property_id
                                    is not None
                                    else None
                                ),

                            "tenant_id":
                                (
                                    str(selected_tenant_id)
                                    if selected_tenant_id
                                    is not None
                                    else None
                                ),
                        }
                    )

                    st.session_state[
                        "p5a_document_upload_success"
                    ] = True

                except Exception as e:
                    st.error(
                        "Unable to upload document."
                    )
                    show_debug_exception(e)

                finally:
                    st.session_state[
                        "p5a_document_upload_busy"
                    ] = False

                if st.session_state.get(
                    "p5a_document_upload_success"
                ):
                    st.rerun()

        if st.session_state.pop(
            "p5a_document_upload_success",
            False
        ):
            st.success(
                "Document uploaded successfully."
            )

