# =========================================================
# UNIT / TENANT OCCUPANCY INTEGRITY
# =========================================================

def sync_unit_occupancy(unit_id):
    """
    Unit occupancy is derived from tenant lifecycle:
    >= 1 Active tenant -> Occupied
    0 Active tenants    -> Vacant

    This intentionally ignores tenant role. Primary tenants,
    co-tenants, and occupants all count as occupying the unit
    when their tenant status is Active.
    """
    if not unit_id:
        return

    active_rows = (
        supabase.table("tenants")
        .select("tenant_id")
        .eq("unit_id", unit_id)
        .eq("status", "Active")
        .limit(1)
        .eq("owner_id", OWNER_SCOPE_ID).execute().data or []
    )

    unit_status = "Occupied" if active_rows else "Vacant"

    (
        supabase.table("units")
        .update({"status": unit_status})
        .eq("unit_id", unit_id)
        .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute()
    )


def reconcile_all_unit_occupancy():
    """
    Repairs existing unit status values from current tenant data.
    Safe to rerun; no tenant, rent, or payment history is deleted.
    """
    units = (
        supabase.table("units")
        .select("unit_id")
        .in_("property_id", OWNER_PROPERTY_IDS_FOR_QUERY).execute().data or []
    )

    for unit in units:
        sync_unit_occupancy(unit.get("unit_id"))

